  'Tax invoice details: consignee, delivery, dispatch': 'ടാക്സ് ഇൻവോയ്സ് വിവരങ്ങൾ: സ്വീകർത്താവ്, ഡെലിവറി, അയയ്ക്കൽ',
  'Printed on the Tally-style invoice. Blank buyer fields use the customer\'s record; a blank consignee means the same as the buyer.': 'ടാലി ശൈലിയിലുള്ള ഇൻവോയ്സിൽ അച്ചടിക്കും. ഒഴിച്ചിട്ട വാങ്ങുന്നയാളുടെ ഫീൽഡുകൾക്ക് ഉപഭോക്താവിന്റെ രേഖ ഉപയോഗിക്കും; ഒഴിച്ചിട്ട സ്വീകർത്താവ് എന്നാൽ വാങ്ങുന്നയാൾ തന്നെ.',
