  'How this phone shows the app. It stays on this phone and changes nothing on your bills or reports.': 'ഈ ഫോൺ ആപ്പ് എങ്ങനെ കാണിക്കുന്നു. ഇത് ഈ ഫോണിൽ മാത്രം നിൽക്കും, നിങ്ങളുടെ ബില്ലുകളിലോ റിപ്പോർട്ടുകളിലോ ഒന്നും മാറ്റില്ല.',
  'Receipts and shared bills always show the exact amount.': 'രസീതുകളും പങ്കിട്ട ബില്ലുകളും എപ്പോഴും കൃത്യമായ തുക കാണിക്കും.',
  'Download a copy of all your records (customers, products, bills, payments, expenses and stock) as a ZIP of CSV files, then save or send it from the share sheet. Keep it somewhere safe. FlowXP does not restore from it by itself: ask support if you ever need your data put back.': 'നിങ്ങളുടെ എല്ലാ രേഖകളുടെയും (ഉപഭോക്താക്കൾ, ഉൽപ്പന്നങ്ങൾ, ബില്ലുകൾ, പേയ്മെന്റുകൾ, ചെലവുകൾ, സ്റ്റോക്ക്) പകർപ്പ് CSV ഫയലുകളുടെ ZIP ആയി ഡൗൺലോഡ് ചെയ്ത് ഷെയർ ഷീറ്റിൽ നിന്ന് സേവ് ചെയ്യുകയോ അയയ്ക്കുകയോ ചെയ്യുക. സുരക്ഷിതമായി സൂക്ഷിക്കുക. FlowXP ഇതിൽ നിന്ന് സ്വയം പുനഃസ്ഥാപിക്കില്ല: ഡാറ്റ തിരികെ വേണമെങ്കിൽ സപ്പോർട്ടിനോട് ചോദിക്കുക.',
  'Could not take the backup.': 'ബാക്കപ്പ് എടുക്കാനായില്ല.',
  'Could not take the backup. Only the owner can, and the phone needs a connection.': 'ബാക്കപ്പ് എടുക്കാനായില്ല. ഉടമയ്ക്ക് മാത്രമേ കഴിയൂ, ഫോണിന് കണക്ഷൻ വേണം.',
  'This phone cannot share files from FlowXP.': 'ഈ ഫോണിന് FlowXP-ൽ നിന്ന് ഫയലുകൾ പങ്കിടാനാകില്ല.',
