  'You pay a flat share of your turnover instead of charging GST. Bills become Bills of Supply with no tax on them.': 'GST ഈടാക്കുന്നതിനു പകരം നിങ്ങളുടെ വിറ്റുവരവിന്റെ ഒരു നിശ്ചിത വിഹിതം അടയ്ക്കുന്നു. ബില്ലുകൾ നികുതിയില്ലാത്ത സപ്ലൈ ബില്ലുകളാകും.',
