  'Compensation cess on top of GST. Set the cess rate on each product (Products → edit); it is added to the line and the bill.': 'GST-ക്ക് പുറമെയുള്ള നഷ്ടപരിഹാര സെസ്. ഓരോ ഉൽപ്പന്നത്തിലും സെസ് നിരക്ക് നൽകുക (ഉൽപ്പന്നങ്ങൾ → തിരുത്തുക); ഇത് വരിയിലും ബില്ലിലും ചേർക്കും.',
  'TCS (tax collected at source)': 'TCS (ഉറവിടത്തിൽ ഈടാക്കുന്ന നികുതി)',
  'A "Collect TCS" tick appears on the billing screen. When ticked, the TCS is added to that bill.': 'ബില്ലിങ് സ്ക്രീനിൽ "TCS ഈടാക്കുക" എന്ന ടിക്ക് വരും. ടിക്ക് ചെയ്താൽ ആ ബില്ലിൽ TCS ചേർക്കും.',
  'TCS rate (%)': 'TCS നിരക്ക് (%)',
  'TDS (tax deducted by the customer)': 'TDS (ഉപഭോക്താവ് കുറയ്ക്കുന്ന നികുതി)',
  'A "Customer deducts TDS" tick appears on the billing screen. When ticked, the TDS is taken off what the customer pays and noted on the bill.': 'ബില്ലിങ് സ്ക്രീനിൽ "ഉപഭോക്താവ് TDS കുറയ്ക്കുന്നു" എന്ന ടിക്ക് വരും. ടിക്ക് ചെയ്താൽ ഉപഭോക്താവ് നൽകുന്ന തുകയിൽ നിന്ന് TDS കുറച്ച് ബില്ലിൽ രേഖപ്പെടുത്തും.',
  'TDS rate (%)': 'TDS നിരക്ക് (%)',
  'A "Tax payable on reverse charge" tick appears on the billing screen and prints on the invoice.': 'ബില്ലിങ് സ്ക്രീനിൽ "റിവേഴ്സ് ചാർജ് പ്രകാരം നൽകേണ്ട നികുതി" എന്ന ടിക്ക് വരികയും ഇൻവോയ്സിൽ അച്ചടിക്കുകയും ചെയ്യും.',
  'Details, receipt, GST and invoice (owner)': 'വിവരങ്ങൾ, രസീത്, GST, ഇൻവോയ്സ് (ഉടമ)',
