  'Email goes to the address you sign in with. Phone alerts go to the FlowXP app on the phones you are signed in on. Notifications are never sent to customers.': 'ഇമെയിൽ നിങ്ങൾ സൈൻ ഇൻ ചെയ്യുന്ന വിലാസത്തിലേക്ക് പോകുന്നു. ഫോൺ അലേർട്ടുകൾ നിങ്ങൾ സൈൻ ഇൻ ചെയ്തിരിക്കുന്ന ഫോണുകളിലെ FlowXP ആപ്പിലേക്ക് പോകുന്നു. അറിയിപ്പുകൾ ഒരിക്കലും ഉപഭോക്താക്കൾക്ക് അയയ്ക്കില്ല.',
