  'Prepare your GSTR-1 file, the GSTR-3B figures and e-invoice files. You upload them on the GST portal.': 'നിങ്ങളുടെ GSTR-1 ഫയൽ, GSTR-3B കണക്കുകൾ, ഇ-ഇൻവോയ്സ് ഫയലുകൾ എന്നിവ തയ്യാറാക്കുക. ഇവ നിങ്ങൾ ജിഎസ്ടി പോർട്ടലിൽ അപ്‌ലോഡ് ചെയ്യുന്നു.',
  'Month': 'മാസം',
  'GSTR-1': 'GSTR-1',
  'GSTR-3B': 'GSTR-3B',
  'E-invoice': 'ഇ-ഇൻവോയ്സ്',
  'GST is not switched on for this business. Turn it on in Business settings to prepare returns.': 'ഈ ബിസിനസിന് ജിഎസ്ടി ഓണാക്കിയിട്ടില്ല. റിട്ടേണുകൾ തയ്യാറാക്കാൻ ബിസിനസ് ക്രമീകരണങ്ങളിൽ ഇത് ഓണാക്കുക.',
  'Add your GSTIN in Business settings first.': 'ആദ്യം ബിസിനസ് ക്രമീകരണങ്ങളിൽ നിങ്ങളുടെ GSTIN ചേർക്കുക.',
  'B2B invoices': 'B2B ഇൻവോയ്സുകൾ',
  'B2C large (inter-state)': 'B2C വലുത് (അന്തർസംസ്ഥാന)',
  'B2C small (summary rows)': 'B2C ചെറുത് (സംഗ്രഹ വരികൾ)',
  'Credit notes': 'ക്രെഡിറ്റ് നോട്ടുകൾ',
  'Check:': 'പരിശോധന:',
  'Nothing to fix. The file is ready to upload.': 'ശരിയാക്കാൻ ഒന്നുമില്ല. ഫയൽ അപ്‌ലോഡ് ചെയ്യാൻ തയ്യാറാണ്.',
  'Upload it on the GST portal (Returns, GSTR-1, Prepare offline) or give it to your accountant. {hsn_rows} HSN rows included.': 'ഇത് ജിഎസ്ടി പോർട്ടലിൽ അപ്‌ലോഡ് ചെയ്യുക (റിട്ടേണുകൾ, GSTR-1, ഓഫ്‌ലൈൻ തയ്യാറാക്കുക) അല്ലെങ്കിൽ നിങ്ങളുടെ അക്കൗണ്ടന്റിന് നൽകുക. {hsn_rows} HSN വരികൾ ഉൾപ്പെടുന്നു.',
  'Taxable value': 'നികുതി ബാധക മൂല്യം',
  'IGST': 'IGST',
  'CGST': 'CGST',
  '3.1(a) Outward taxable supplies (net of credit notes)': '3.1(a) പുറത്തേക്കുള്ള നികുതി ബാധകമായ വിതരണങ്ങൾ (ക്രെഡിറ്റ് നോട്ടുകൾ കഴിച്ച്)',
  '3.1(c) Nil-rated, exempt': '3.1(c) നിൽ റേറ്റഡ്, ഒഴിവാക്കിയത്',
