  '4(A) Input tax credit you can claim': '4(A) നിങ്ങൾക്ക് ക്ലെയിം ചെയ്യാവുന്ന ഇൻപുട്ട് ടാക്സ് ക്രെഡിറ്റ്',
  'Tax to pay in cash (after credit)': 'പണമായി അടയ്ക്കേണ്ട നികുതി (ക്രെഡിറ്റിന് ശേഷം)',
  'No sales to GST-registered customers in this month.': 'ഈ മാസം ജിഎസ്ടി രജിസ്റ്റർ ചെയ്ത ഉപഭോക്താക്കൾക്ക് വിൽപ്പനയില്ല.',
