  'Large inter-state invoice limit (₹)': 'വലിയ അന്തർസംസ്ഥാന ഇൻവോയ്സ് പരിധി (₹)',
  'Inter-state sales to people without a GSTIN above this go in the B2CL table. Confirm the current limit with your accountant.': 'GSTIN ഇല്ലാത്തവർക്കുള്ള ഇതിന് മുകളിലുള്ള അന്തർസംസ്ഥാന വിൽപ്പനകൾ B2CL പട്ടികയിൽ പോകും. നിലവിലെ പരിധി നിങ്ങളുടെ അക്കൗണ്ടന്റിനോട് ഉറപ്പാക്കുക.',
  'My business must issue e-invoices': 'എന്റെ ബിസിനസ് ഇ-ഇൻവോയ്സുകൾ നൽകണം',
  'Your GSTIN is set in Business settings. Add each customer\'s state, pincode and GSTIN on the Customers page, and an HSN/SAC code on every product, so the files come out complete.': 'നിങ്ങളുടെ GSTIN ബിസിനസ് ക്രമീകരണങ്ങളിൽ സജ്ജമാക്കിയിട്ടുണ്ട്. ഫയലുകൾ പൂർണ്ണമാകാൻ ഉപഭോക്താക്കളുടെ പേജിൽ ഓരോ ഉപഭോക്താവിന്റെയും സംസ്ഥാനം, പിൻകോഡ്, GSTIN എന്നിവയും ഓരോ ഉൽപ്പന്നത്തിലും HSN/SAC കോഡും ചേർക്കുക.',
  '{customers} customers · {taxable} taxable': '{customers} ഉപഭോക്താക്കൾ · {taxable} നികുതി ബാധകം',
  '{taxable} taxable': '{taxable} നികുതി ബാധകം',
