  '{registered} to registered · {others} to others': '{registered} രജിസ്റ്റർ ചെയ്തവർക്ക് · {others} മറ്റുള്ളവർക്ക്',
  'Download the GSTR-1 file': 'GSTR-1 ഫയൽ ഡൗൺലോഡ് ചെയ്യുക',
  'SGST/UTGST': 'SGST/UTGST',
  'Purchases from suppliers without a GSTIN carry {amount} of tax that is not claimable.': 'GSTIN ഇല്ലാത്ത വിതരണക്കാരിൽ നിന്നുള്ള വാങ്ങലുകളിൽ {amount} നികുതി ക്ലെയിം ചെയ്യാനാകാത്തതാണ്.',
  'E-invoicing applies to businesses above a turnover limit and only for sales to customers with a GSTIN. If it does not apply to you, ignore this tab.': 'ഇ-ഇൻവോയ്സിങ് ഒരു വിറ്റുവരവ് പരിധിക്ക് മുകളിലുള്ള ബിസിനസുകൾക്കും GSTIN ഉള്ള ഉപഭോക്താക്കൾക്കുള്ള വിൽപ്പനയ്ക്കും മാത്രമേ ബാധകമാകൂ. ബാധകമല്ലെങ്കിൽ ഈ ടാബ് അവഗണിക്കുക.',
