  'Only owners and admins can prepare returns.': 'റിട്ടേണുകൾ തയ്യാറാക്കാൻ ഉടമകൾക്കും അഡ്മിനുകൾക്കും മാത്രമേ കഴിയൂ.',
  'Could not download. The phone needs a connection, and filing needs permission.': 'ഡൗൺലോഡ് ചെയ്യാനായില്ല. ഫോണിന് കണക്ഷൻ വേണം, ഫയലിങ്ങിന് അനുമതിയും വേണം.',
