  'A customer is their mobile number. Every day they are billed counts as one visit, at any outlet. On the visit that earns it, the free item comes off the bill once it is on the order (the till offers to add it).': 'ഒരു ഉപഭോക്താവ് എന്നാൽ അവരുടെ മൊബൈൽ നമ്പറാണ്. ബിൽ ചെയ്യുന്ന ഓരോ ദിവസവും ഒരു സന്ദർശനമായി കണക്കാക്കും, ഏത് ഔട്ട്‌ലെറ്റിലായാലും. പ്രതിഫലം ലഭിക്കുന്ന സന്ദർശനത്തിൽ, സൗജന്യ ഇനം ഓർഡറിൽ വന്നാൽ ബില്ലിൽ നിന്ന് കുറയ്ക്കും (ടിൽ അത് ചേർക്കാൻ നിർദ്ദേശിക്കും).',
