  '{n} visits stamped': '{n} സന്ദർശനങ്ങൾക്ക് സ്റ്റാമ്പ് ചെയ്തു',
  'Free items given': 'നൽകിയ സൗജന്യ ഇനങ്ങൾ',
  '{n} in 30 days · worth {value}': '30 ദിവസത്തിൽ {n} · മൂല്യം {value}',
