  'Most of one bill points can pay (%)': 'ഒരു ബില്ലിൽ പോയിന്റ് കൊണ്ട് അടയ്ക്കാവുന്ന പരമാവധി ഭാഗം (%)',
  'Tiers': 'ടയറുകൾ',
  'A tier is decided by the points a customer has earned over time (spending points never lowers it). A higher tier earns points faster. The first tier must start at 0. Leave empty for no tiers.': 'ഒരു ഉപഭോക്താവ് കാലക്രമേണ നേടിയ പോയിന്റുകൾ അനുസരിച്ചാണ് ടയർ നിശ്ചയിക്കുന്നത് (പോയിന്റ് ചെലവഴിച്ചാൽ അത് കുറയില്ല). ഉയർന്ന ടയറിൽ പോയിന്റുകൾ വേഗത്തിൽ കിട്ടും. ആദ്യ ടയർ 0-ൽ തുടങ്ങണം. ടയർ വേണ്ടെങ്കിൽ ഒഴിച്ചിടുക.',
