  'Loyalty reminder': 'ലോയൽറ്റി ഓർമ്മപ്പെടുത്തൽ',
  'When a customer\'s next visit earns their free item (at most once a week).': 'ഉപഭോക്താവിന്റെ അടുത്ത സന്ദർശനത്തിൽ സൗജന്യ ഇനം ലഭിക്കുമ്പോൾ (ആഴ്ചയിൽ പരമാവധി ഒരു തവണ).',
  'Offers and reminders only go to customers who have not opted out. Bills and booking messages are service messages and are sent regardless.': 'ഓഫറുകളും ഓർമ്മപ്പെടുത്തലുകളും ഒഴിവാക്കിയിട്ടില്ലാത്ത ഉപഭോക്താക്കൾക്ക് മാത്രമേ പോകൂ. ബില്ലും ബുക്കിംഗ് സന്ദേശങ്ങളും സേവന സന്ദേശങ്ങളാണ്, അവ എന്തായാലും അയയ്ക്കും.',
  'Show the WhatsApp templates to create in Meta': 'Meta-യിൽ സൃഷ്ടിക്കേണ്ട വാട്സ്ആപ്പ് ടെംപ്ലേറ്റുകൾ കാണിക്കുക',
  'Hide the WhatsApp templates': 'വാട്സ്ആപ്പ് ടെംപ്ലേറ്റുകൾ മറയ്ക്കുക',
  'WhatsApp only lets a business start a chat with pre-approved templates. Create each one once in Meta Business Manager (category: Utility for bills and bookings, Marketing for offers), using exactly this name and text.': 'മുൻകൂട്ടി അംഗീകരിച്ച ടെംപ്ലേറ്റുകൾ ഉപയോഗിച്ച് മാത്രമേ വാട്സ്ആപ്പ് ഒരു ബിസിനസ്സിനെ ചാറ്റ് തുടങ്ങാൻ അനുവദിക്കൂ. ഓരോന്നും Meta Business Manager-ൽ ഒരു തവണ സൃഷ്ടിക്കുക (വിഭാഗം: ബില്ലുകൾക്കും ബുക്കിംഗിനും Utility, ഓഫറുകൾക്ക് Marketing), ഈ പേരും വാചകവും അതുപോലെ ഉപയോഗിച്ച്.',
