  'Transporter GSTIN (optional)': 'ട്രാൻസ്പോർട്ടറുടെ GSTIN (ഓപ്ഷണൽ)',
  'Transporter name (optional)': 'ട്രാൻസ്പോർട്ടറുടെ പേര് (ഓപ്ഷണൽ)',
  'Prepare the file': 'ഫയൽ തയ്യാറാക്കുക',
  'Fix these first:': 'ആദ്യം ഇവ ശരിയാക്കുക:',
  'Share the e-way bill file (JSON)': 'ഇ-വേ ബിൽ ഫയൽ (JSON) പങ്കിടുക',
  'Upload it on the e-way bill portal (Generate in bulk). The portal gives you a 12-digit number: save it here.': 'ഇത് ഇ-വേ ബിൽ പോർട്ടലിൽ അപ്‌ലോഡ് ചെയ്യുക (ബൾക്കായി ജനറേറ്റ് ചെയ്യുക). പോർട്ടൽ 12 അക്ക നമ്പർ തരും: അത് ഇവിടെ സേവ് ചെയ്യുക.',
  'E-way bill number': 'ഇ-വേ ബിൽ നമ്പർ',
  'Save number': 'നമ്പർ സേവ് ചെയ്യുക',
  'E-way bill {number} is saved on this invoice.': 'ഇ-വേ ബിൽ {number} ഈ ഇൻവോയ്സിൽ സേവ് ചെയ്തു.',
  'Distance is a whole number of kilometres, up to 4000': 'ദൂരം കിലോമീറ്ററിന്റെ പൂർണ്ണസംഖ്യയാണ്, പരമാവധി 4000',
  'The transporter GSTIN has 15 letters and digits': 'ട്രാൻസ്പോർട്ടറുടെ GSTIN-ൽ 15 അക്ഷരങ്ങളും അക്കങ്ങളുമുണ്ട്',
  'An e-way bill number is 12 digits': 'ഇ-വേ ബിൽ നമ്പർ 12 അക്കമാണ്',
  'Only owners and admins can prepare e-way bills.': 'ഉടമകൾക്കും അഡ്മിനുകൾക്കും മാത്രമേ ഇ-വേ ബില്ലുകൾ തയ്യാറാക്കാൻ കഴിയൂ.',
  'Could not prepare the file. Check the connection and try again.': 'ഫയൽ തയ്യാറാക്കാൻ കഴിഞ്ഞില്ല. കണക്ഷൻ പരിശോധിച്ച് വീണ്ടും ശ്രമിക്കുക.',
  // E-way bill (more)
  'Vehicle number': 'വാഹന നമ്പർ',
  // Stock counts
  'Scan the shelf and see what differs': 'ഷെൽഫ് സ്കാൻ ചെയ്ത് വ്യത്യാസം കാണുക',
  'Stock counts': 'സ്റ്റോക്ക് എണ്ണൽ',
  'Walk the shelf, scan each product once per unit, and see what differs from the system before anything changes.': 'ഷെൽഫിലൂടെ നടക്കുക, ഓരോ യൂണിറ്റിനും ഒരിക്കൽ ഉൽപ്പന്നം സ്കാൻ ചെയ്യുക, ഒന്നും മാറുന്നതിന് മുമ്പ് സിസ്റ്റത്തിൽ നിന്ന് എന്ത് വ്യത്യാസമെന്ന് കാണുക.',
  'Count stock': 'സ്റ്റോക്ക് എണ്ണുക',
  'Start counting': 'എണ്ണൽ തുടങ്ങുക',
  'No stock counts yet.': 'ഇതുവരെ സ്റ്റോക്ക് എണ്ണലുകളില്ല.',
  'In progress': 'പുരോഗമിക്കുന്നു',
  'Whole store': 'മുഴുവൻ സ്റ്റോർ',
