  '{n} counted': '{n} എണ്ണി',
  '{n} adjusted · {units} units': '{n} ക്രമീകരിച്ചു · {units} യൂണിറ്റ്',
  'So you can tell counts apart later, like “Aisle 3” or “Month end”.': 'പിന്നീട് എണ്ണലുകൾ തിരിച്ചറിയാൻ, ഉദാ. “ഇടനാഴി 3” അല്ലെങ്കിൽ “മാസാവസാനം”.',
  'What are you counting?': 'നിങ്ങൾ എന്താണ് എണ്ണുന്നത്?',
  'The whole store': 'മുഴുവൻ സ്റ്റോർ',
  'Give the count a name (up to 80 characters)': 'എണ്ണലിന് ഒരു പേര് നൽകുക (80 അക്ഷരം വരെ)',
  'You do not have access to stock counts.': 'സ്റ്റോക്ക് എണ്ണലുകൾക്ക് നിങ്ങൾക്ക് അനുമതിയില്ല.',
  'Counting only {category}': '{category} മാത്രം എണ്ണുന്നു',
  'Counting the whole store': 'മുഴുവൻ സ്റ്റോറും എണ്ണുന്നു',
  'Scan items': 'ഇനങ്ങൾ സ്കാൻ ചെയ്യുക',
  'Stop scanning': 'സ്കാനിംഗ് നിർത്തുക',
  'Point the camera at the barcode': 'ക്യാമറ ബാർകോഡിലേക്ക് തിരിക്കുക',
  'Allow the camera so FlowXP can read barcodes. It does not take or keep photos.': 'FlowXP-ന് ബാർകോഡ് വായിക്കാൻ ക്യാമറ അനുവദിക്കുക. ഇത് ഫോട്ടോ എടുക്കുകയോ സൂക്ഷിക്കുകയോ ചെയ്യില്ല.',
  '{code} is not in your products. Check the code, or add it under Products.': '{code} നിങ്ങളുടെ ഉൽപ്പന്നങ്ങളിൽ ഇല്ല. കോഡ് പരിശോധിക്കുക, അല്ലെങ്കിൽ ഉൽപ്പന്നങ്ങളിൽ ചേർക്കുക.',
