  '{value} per portion': 'ഒരു പോർഷന് {value}',
  'No items sold in this period.': 'ഈ കാലയളവിൽ ഇനങ്ങളൊന്നും വിറ്റിട്ടില്ല.',
  'FlowXP cannot know what your card machine or delivery platform charges. Enter your real rates; anything left at 0 is not deducted.': 'നിങ്ങളുടെ കാർഡ് മെഷീനോ ഡെലിവറി പ്ലാറ്റ്ഫോമോ എത്ര ഈടാക്കുന്നു എന്ന് FlowXP-ന് അറിയാൻ കഴിയില്ല. നിങ്ങളുടെ യഥാർത്ഥ നിരക്കുകൾ നൽകുക; 0 ആയി വിടുന്നത് കുറയ്ക്കില്ല.',
  'Payment fees (% of amount collected)': 'പേയ്‌മെന്റ് ഫീസ് (ശേഖരിച്ച തുകയുടെ %)',
  'Delivery platform commission (% of food value)': 'ഡെലിവറി പ്ലാറ്റ്ഫോം കമ്മീഷൻ (ഭക്ഷണ മൂല്യത്തിന്റെ %)',
  'Packaging per takeaway / delivery order (₹)': 'ഓരോ ടേക്ക്അവേ / ഡെലിവറി ഓർഡറിനും പാക്കേജിംഗ് (₹)',
  'Box, bag, cutlery.': 'പെട്ടി, ബാഗ്, കട്ട്ലറി.',
  'Save assumptions': 'അനുമാനങ്ങൾ സേവ് ചെയ്യുക',
  'A rate is a percentage from 0 to 100': 'നിരക്ക് 0 മുതൽ 100 വരെയുള്ള ശതമാനമാണ്',
  'Packaging must be an amount in rupees': 'പാക്കേജിംഗ് രൂപയിലുള്ള ഒരു തുകയായിരിക്കണം',
  'Net revenue is what was billed before tax, minus discounts and refunds. Cancelled invoices are left out. Food cost is the ingredient cost recorded on each bill when it was made. Fees, commission and packaging use your assumptions: unset means zero. Contribution is what each sale leaves toward rent, salaries and other fixed costs.': 'അറ്റ വരുമാനം എന്നത് നികുതിക്ക് മുമ്പ് ബിൽ ചെയ്തതിൽ നിന്ന് കിഴിവുകളും റീഫണ്ടുകളും കുറച്ചതാണ്. റദ്ദാക്കിയ ഇൻവോയ്സുകൾ ഒഴിവാക്കും. ഓരോ ബിൽ ഉണ്ടാക്കുമ്പോഴും രേഖപ്പെടുത്തിയ ചേരുവ ചെലവാണ് ഭക്ഷണ ചെലവ്. ഫീസ്, കമ്മീഷൻ, പാക്കേജിംഗ് എന്നിവ നിങ്ങളുടെ അനുമാനങ്ങൾ ഉപയോഗിക്കുന്നു: സജ്ജമാക്കിയില്ലെങ്കിൽ പൂജ്യം. വാടക, ശമ്പളം, മറ്റ് സ്ഥിര ചെലവുകൾ എന്നിവയ്ക്കായി ഓരോ വിൽപ്പനയും ബാക്കിവയ്ക്കുന്നതാണ് സംഭാവന.',
  'What to expect, and what to have in the kitchen for it.': 'എന്ത് പ്രതീക്ഷിക്കാം, അതിനായി അടുക്കളയിൽ എന്ത് വേണം.',
