  'On the last {days} days the same method was off by {pct}% on average for orders.': 'കഴിഞ്ഞ {days} ദിവസങ്ങളിൽ ഇതേ രീതി ഓർഡറുകൾക്ക് ശരാശരി {pct}% തെറ്റി.',
  'It tended to run {pct}% high.': 'ഇത് {pct}% കൂടുതലായി പോകാൻ പ്രവണത കാണിച്ചു.',
