  'Nothing unusual found in the last {n} days. FlowXP compares against your own normal, so this improves as your history grows.': 'കഴിഞ്ഞ {n} ദിവസങ്ങളിൽ അസാധാരണമായി ഒന്നും കണ്ടെത്തിയില്ല. FlowXP നിങ്ങളുടെ സ്വന്തം സാധാരണ നിലയുമായി താരതമ്യം ചെയ്യുന്നു, അതിനാൽ ചരിത്രം വളരുമ്പോൾ ഇത് മെച്ചപ്പെടും.',
