  '{name} now averages {now} minutes, up from {before}.': '{name} ഇപ്പോൾ ശരാശരി {now} മിനിറ്റ് എടുക്കുന്നു, മുമ്പ് {before} ആയിരുന്നു.',
  'Worth asking: is it staffing at peak, a missing ingredient, a change to how it is made, or does the set time need updating?': 'ചോദിക്കേണ്ടത്: തിരക്കുള്ള സമയത്തെ ജീവനക്കാരാണോ, ഒരു ചേരുവ ഇല്ലാത്തതാണോ, ഉണ്ടാക്കുന്ന രീതി മാറിയതാണോ, അതോ നിശ്ചിത സമയം പുതുക്കണോ?',
