  'Average time by hour sent': 'അയച്ച മണിക്കൂർ അനുസരിച്ച് ശരാശരി സമയം',
  'Busy hours usually run slower; a big gap here is a staffing question.': 'തിരക്കുള്ള മണിക്കൂറുകൾ സാധാരണ മന്ദഗതിയിലാണ്; ഇവിടെ വലിയ വ്യത്യാസം ജീവനക്കാരുടെ ചോദ്യമാണ്.',
  'By dish': 'വിഭവം അനുസരിച്ച്',
  'Dishes with at least 3 finished items.': 'കുറഞ്ഞത് 3 പൂർത്തിയായ ഇനങ്ങളുള്ള വിഭവങ്ങൾ.',
