  'What your sales leave after food cost, fees and commission': 'ഭക്ഷണ ചെലവ്, ഫീസ്, കമ്മീഷൻ എന്നിവയ്ക്ക് ശേഷം നിങ്ങളുടെ വിൽപ്പന ബാക്കിവയ്ക്കുന്നത്',
