  // Forecast
  'Forecasting needs at least three weeks of history for the same weekday. You have {n} trading days so far. Check back as history builds.': 'പ്രവചനത്തിന് ഒരേ ദിവസത്തെ കുറഞ്ഞത് മൂന്ന് ആഴ്ചത്തെ ചരിത്രം വേണം. ഇതുവരെ നിങ്ങൾക്ക് {n} വ്യാപാര ദിവസങ്ങളാണുള്ളത്. ചരിത്രം വളരുമ്പോൾ വീണ്ടും നോക്കുക.',
  // Gym plans and settings
  'What you sell. Each membership keeps the rules it was sold with, so changing a plan only affects the next sale.': 'നിങ്ങൾ വിൽക്കുന്നത്. ഓരോ അംഗത്വവും വിൽക്കുമ്പോഴത്തെ നിയമങ്ങൾ നിലനിർത്തും, അതിനാൽ പ്ലാൻ മാറ്റുന്നത് അടുത്ത വിൽപ്പനയെ മാത്രം ബാധിക്കും.',
