  'Changing a plan does not change memberships already sold: each keeps the rules it was sold with.': 'പ്ലാൻ മാറ്റുന്നത് ഇതിനകം വിറ്റ അംഗത്വങ്ങളെ മാറ്റില്ല: ഓരോന്നും വിൽക്കുമ്പോഴത്തെ നിയമങ്ങൾ നിലനിർത്തും.',
  'Monthly, Student quarterly, Off-peak annual': 'പ്രതിമാസം, വിദ്യാർത്ഥി ത്രൈമാസം, ഓഫ്-പീക്ക് വാർഷികം',
