  'GST rate': 'GST നിരക്ക്',
  'Gym memberships are usually 18%.': 'ജിം അംഗത്വങ്ങൾക്ക് സാധാരണയായി 18% ആണ്.',
  'Description (optional)': 'വിവരണം (ഓപ്ഷണൽ)',
  'People covered': 'ഉൾപ്പെടുന്ന ആളുകൾ',
