  'Empty uses the gym\'s default. 0 means none for this plan.': 'ശൂന്യമാണെങ്കിൽ ജിമ്മിന്റെ ഡിഫോൾട്ട് ഉപയോഗിക്കും. 0 എന്നാൽ ഈ പ്ലാനിന് ഒന്നുമില്ല.',
  'Where and when it works': 'ഇത് എവിടെ, എപ്പോൾ പ്രവർത്തിക്കുന്നു',
