  'Members can freeze it': 'അംഗങ്ങൾക്ക് ഇത് ഫ്രീസ് ചെയ്യാം',
  'Most days they can freeze in all': 'ആകെ അവർക്ക് ഫ്രീസ് ചെയ്യാവുന്ന പരമാവധി ദിവസങ്ങൾ',
