  'Gym settings': 'ജിം ക്രമീകരണങ്ങൾ',
  'The rules for coming in, each branch\'s hours, and the entrance QR.': 'അകത്ത് വരാനുള്ള നിയമങ്ങൾ, ഓരോ ശാഖയുടെയും സമയം, പ്രവേശന QR.',
  'Rules': 'നിയമങ്ങൾ',
  'Branches and QR': 'ശാഖകളും QR-ഉം',
  'Check-in rules': 'ചെക്ക്-ഇൻ നിയമങ്ങൾ',
  'Every way in follows these: the desk, the member\'s phone and the gates.': 'അകത്തേക്കുള്ള എല്ലാ വഴികളും ഇവ പിന്തുടരുന്നു: ഡെസ്ക്, അംഗത്തിന്റെ ഫോൺ, ഗേറ്റുകൾ.',
  'Grace days after a membership ends': 'അംഗത്വം അവസാനിച്ച ശേഷമുള്ള ഗ്രേസ് ദിവസങ്ങൾ',
  'Ignore a repeat scan for (seconds)': 'ആവർത്തിച്ചുള്ള സ്കാൻ ഇത്ര സമയം അവഗണിക്കുക (സെക്കൻഡ്)',
  'Same card at two branches within (minutes)': 'ഒരേ കാർഡ് രണ്ട് ശാഖകളിൽ ഇത്ര മിനിറ്റിനുള്ളിൽ',
  'Record check-out as well as check-in': 'ചെക്ക്-ഇനോടൊപ്പം ചെക്ക്-ഔട്ടും രേഖപ്പെടുത്തുക',
  'Shows who is in the gym now.': 'ഇപ്പോൾ ജിമ്മിൽ ആരൊക്കെയുണ്ടെന്ന് കാണിക്കുന്നു.',
  'The desk confirms every scan by looking at the member': 'ഡെസ്ക് അംഗത്തെ നോക്കി ഓരോ സ്കാനും സ്ഥിരീകരിക്കുന്നു',
  'Members on their own phone': 'അംഗങ്ങൾ സ്വന്തം ഫോണിൽ',
  'A member signs in with a code sent to their phone, then shows a pass or checks in themselves. No app to install.': 'അംഗം ഫോണിലേക്ക് അയച്ച കോഡ് ഉപയോഗിച്ച് സൈൻ ഇൻ ചെയ്യുന്നു, പിന്നെ പാസ് കാണിക്കുകയോ സ്വയം ചെക്ക്-ഇൻ ചെയ്യുകയോ ചെയ്യുന്നു. ആപ്പ് ഇൻസ്റ്റാൾ ചെയ്യേണ്ട.',
  'Let members check in from their own phone': 'അംഗങ്ങളെ സ്വന്തം ഫോണിൽ നിന്ന് ചെക്ക്-ഇൻ ചെയ്യാൻ അനുവദിക്കുക',
  'They scan the poster at the door with their phone\'s camera.': 'അവർ ഫോണിന്റെ ക്യാമറ ഉപയോഗിച്ച് വാതിൽക്കലെ പോസ്റ്റർ സ്കാൻ ചെയ്യുന്നു.',
  'Also ask for today\'s front-desk code': 'ഇന്നത്തെ ഫ്രണ്ട്-ഡെസ്ക് കോഡും ചോദിക്കുക',
  'Ask for a fresh sign-in code every time': 'ഓരോ തവണയും പുതിയ സൈൻ-ഇൻ കോഡ് ചോദിക്കുക',
  'A code counts for (minutes)': 'ഒരു കോഡ് എത്ര സമയം സാധുവാണ് (മിനിറ്റ്)',
  'The gym\'s web address': 'ജിമ്മിന്റെ വെബ് വിലാസം',
  'Letters, digits and hyphens. Needed for members to sign in.': 'അക്ഷരങ്ങൾ, അക്കങ്ങൾ, ഹൈഫനുകൾ. അംഗങ്ങൾക്ക് സൈൻ ഇൻ ചെയ്യാൻ ആവശ്യമാണ്.',
  'Member number starts with': 'അംഗ നമ്പർ ആരംഭിക്കുന്നത്',
  'Stay signed in for (days)': 'ഇത്ര ദിവസം സൈൻ ഇൻ ആയി തുടരുക',
  'A phone pass QR lasts (seconds)': 'ഫോൺ പാസ് QR എത്ര സമയം നിലനിൽക്കും (സെക്കൻഡ്)',
  'Classes': 'ക്ലാസുകൾ',
  'How booking works for members and the desk.': 'അംഗങ്ങൾക്കും ഡെസ്കിനും ബുക്കിംഗ് എങ്ങനെ പ്രവർത്തിക്കുന്നു.',
  'Cancel a class free until (hours before)': 'ക്ലാസ് സൗജന്യമായി റദ്ദാക്കാം, ഇത്ര മണിക്കൂർ മുമ്പ് വരെ',
  'Cancel personal training free until (hours before)': 'പേഴ്സണൽ ട്രെയിനിംഗ് സൗജന്യമായി റദ്ദാക്കാം, ഇത്ര മണിക്കൂർ മുമ്പ് വരെ',
  'Members can book up to (days ahead)': 'അംഗങ്ങൾക്ക് ഇത്ര ദിവസം മുമ്പ് വരെ ബുക്ക് ചെയ്യാം',
  'A full class has a waitlist': 'നിറഞ്ഞ ക്ലാസിന് വെയിറ്റ്‌ലിസ്റ്റ് ഉണ്ട്',
  'Save settings': 'ക്രമീകരണങ്ങൾ സേവ് ചെയ്യുക',
  'Opening hours': 'പ്രവർത്തന സമയം',
  'Nobody is let in outside these hours, whatever their plan.': 'ഈ സമയത്തിന് പുറത്ത് ആരെയും അകത്ത് കടത്തിവിടില്ല, അവരുടെ പ്ലാൻ എന്തായാലും.',
  'Open all day, every day': 'എല്ലാ ദിവസവും ദിവസം മുഴുവൻ തുറന്നിരിക്കും',
  'Opens': 'തുറക്കുന്നു',
  'Closes': 'അടയ്ക്കുന്നു',
  'Holidays (closed all day)': 'അവധികൾ (ദിവസം മുഴുവൻ അടച്ചിരിക്കും)',
  'One date a line, like 2026-11-08.': 'ഒരു വരിയിൽ ഒരു തീയതി, ഉദാ: 2026-11-08.',
  'Save hours': 'സമയം സേവ് ചെയ്യുക',
  'Entrance QR': 'പ്രവേശന QR',
  'Put this poster at the door. It only opens the check-in page for this branch.': 'ഈ പോസ്റ്റർ വാതിൽക്കൽ വയ്ക്കുക. ഇത് ഈ ശാഖയുടെ ചെക്ക്-ഇൻ പേജ് മാത്രമേ തുറക്കൂ.',
  'Check in here': 'ഇവിടെ ചെക്ക്-ഇൻ ചെയ്യുക',
  'Scan with your phone\'s camera. Sign in with the code we send you, then tap Check in.': 'നിങ്ങളുടെ ഫോണിന്റെ ക്യാമറ ഉപയോഗിച്ച് സ്കാൻ ചെയ്യുക. ഞങ്ങൾ അയയ്ക്കുന്ന കോഡ് ഉപയോഗിച്ച് സൈൻ ഇൻ ചെയ്യുക, പിന്നെ ചെക്ക്-ഇൻ ടാപ്പ് ചെയ്യുക.',
