  'Optional — parking, what to bring, a festive notice.': 'ഓപ്ഷണൽ — പാർക്കിംഗ്, കൊണ്ടുവരേണ്ടത്, ഒരു ഉത്സവ അറിയിപ്പ്.',
  'Online bookings arrive as Booked appointments marked Online. One mobile number can hold up to three upcoming online bookings.': 'ഓൺലൈൻ ബുക്കിംഗുകൾ ഓൺലൈൻ എന്ന് അടയാളപ്പെടുത്തിയ ബുക്ക്ഡ് അപ്പോയിന്റ്മെന്റുകളായി വരും. ഒരു മൊബൈൽ നമ്പറിന് മൂന്ന് വരെ വരാനിരിക്കുന്ന ഓൺലൈൻ ബുക്കിംഗുകൾ ഉണ്ടാകാം.',
