  'Pay commission when a service is used from a package or membership': 'ഒരു പാക്കേജിൽ നിന്നോ അംഗത്വത്തിൽ നിന്നോ സേവനം ഉപയോഗിക്കുമ്പോൾ കമ്മീഷൻ നൽകുക',
  'Worked out on the service’s list price, since nothing is charged at the time.': 'ആ സമയത്ത് ഒന്നും ഈടാക്കാത്തതിനാൽ സേവനത്തിന്റെ ലിസ്റ്റ് വിലയിൽ കണക്കാക്കി.',
  'The programme': 'പ്രോഗ്രാം',
  'Points per ₹100, what a point is worth, and the most a bill can be paid with points.': '₹100-ന് പോയിന്റുകൾ, ഒരു പോയിന്റിന്റെ മൂല്യം, പോയിന്റ് ഉപയോഗിച്ച് ഒരു ബില്ലിൽ അടയ്ക്കാവുന്ന പരമാവധി.',
  'Earning rates by kind of sale': 'വിൽപ്പനയുടെ തരം അനുസരിച്ച് നേടൽ നിരക്കുകൾ',
  'Leave the rate empty to use the programme’s rate. Turn a kind off and it earns nothing. Gift cards never earn.': 'പ്രോഗ്രാമിന്റെ നിരക്ക് ഉപയോഗിക്കാൻ നിരക്ക് ശൂന്യമാക്കുക. ഒരു തരം ഓഫ് ആക്കിയാൽ അതൊന്നും നേടില്ല. ഗിഫ്റ്റ് കാർഡുകൾ ഒരിക്കലും നേടില്ല.',
  'Services': 'സേവനങ്ങൾ',
  'Retail products': 'റീട്ടെയിൽ ഉൽപ്പന്നങ്ങൾ',
  'Packages': 'പാക്കേജുകൾ',
  'Memberships': 'അംഗത്വങ്ങൾ',
  'Gift cards': 'ഗിഫ്റ്റ് കാർഡുകൾ',
  'Points per ₹100': '₹100-ന് പോയിന്റുകൾ',
  'Earns points': 'പോയിന്റുകൾ നേടുന്നു',
  'Expiry': 'കാലാവധി',
  'How long points last. Empty means they never expire.': 'പോയിന്റുകൾ എത്രകാലം നിലനിൽക്കും. ശൂന്യം എന്നാൽ ഒരിക്കലും കാലഹരണപ്പെടില്ല.',
  'Points expire on their own once a day. Clients are warned first if the Loyalty points expiry message is on under Messages.': 'പോയിന്റുകൾ ദിവസത്തിൽ ഒരിക്കൽ സ്വയം കാലഹരണപ്പെടും. സന്ദേശങ്ങൾക്ക് കീഴിൽ ലോയൽറ്റി പോയിന്റ് കാലാവധി സന്ദേശം ഓണാണെങ്കിൽ ക്ലയന്റുകൾക്ക് ആദ്യം മുന്നറിയിപ്പ് നൽകും.',
  'Expire old points now': 'പഴയ പോയിന്റുകൾ ഇപ്പോൾ കാലഹരണപ്പെടുത്തുക',
  'Expire old points now?': 'പഴയ പോയിന്റുകൾ ഇപ്പോൾ കാലഹരണപ്പെടുത്തണോ?',
  'Points older than the expiry period are taken off clients’ balances. Running it twice changes nothing more.': 'കാലാവധി കാലയളവിനേക്കാൾ പഴയ പോയിന്റുകൾ ക്ലയന്റുകളുടെ ബാലൻസിൽ നിന്ന് നീക്കം ചെയ്യും. രണ്ടുതവണ ഓടിച്ചാൽ കൂടുതലൊന്നും മാറില്ല.',
  'Expire points': 'പോയിന്റുകൾ കാലഹരണപ്പെടുത്തുക',
  'Last 30 days': 'കഴിഞ്ഞ 30 ദിവസം',
  'Issued': 'നൽകി',
  'Used': 'ഉപയോഗിച്ചു',
  'Owed to clients': 'ക്ലയന്റുകൾക്ക് നൽകാനുള്ളത്',
  'What the client segments mean': 'ക്ലയന്റ് സെഗ്മെന്റുകളുടെ അർത്ഥം',
  'Used by the client list, reminders and campaigns.': 'ക്ലയന്റ് പട്ടിക, ഓർമ്മപ്പെടുത്തലുകൾ, ക്യാമ്പെയ്നുകൾ എന്നിവ ഉപയോഗിക്കുന്നു.',
  'After their first visit': 'അവരുടെ ആദ്യ സന്ദർശനത്തിന് ശേഷം',
  'VIP: visits at least': 'VIP: കുറഞ്ഞത് ഇത്ര സന്ദർശനങ്ങൾ',
  'Frequent: visits in 90 days': 'സ്ഥിരം: 90 ദിവസത്തിനുള്ളിലെ സന്ദർശനങ്ങൾ',
  'Inactive after (days, up to three)': 'ഇതിന് ശേഷം നിഷ്ക്രിയം (ദിവസം, പരമാവധി മൂന്ന്)',
