  'Check now': 'ഇപ്പോൾ പരിശോധിക്കുക',
  'Checked — anything due has been sent': 'പരിശോധിച്ചു — അയയ്ക്കേണ്ടതെല്ലാം അയച്ചു',
  'Team only': 'ടീം മാത്രം',
