  'Send a campaign': 'ഒരു ക്യാമ്പെയ്ൻ അയയ്ക്കുക',
  'One message to a group of clients. One campaign an hour.': 'ഒരു കൂട്ടം ക്ലയന്റുകൾക്ക് ഒരു സന്ദേശം. മണിക്കൂറിൽ ഒരു ക്യാമ്പെയ്ൻ.',
