  'Targets running today. Setting one again for the same period changes it; it never adds a second.': 'ഇന്ന് നടക്കുന്ന ലക്ഷ്യങ്ങൾ. അതേ കാലയളവിൽ വീണ്ടും സജ്ജമാക്കിയാൽ അത് മാറും; രണ്ടാമത്തേത് ചേരില്ല.',
