  'Target saved': 'ലക്ഷ്യം സേവ് ചെയ്തു',
  'Each sold line earns under the most specific rule that fits. Without rules each person earns their own default percentage.': 'വിൽക്കുന്ന ഓരോ വരിയും ഏറ്റവും കൃത്യമായി ചേരുന്ന നിയമപ്രകാരം നേടുന്നു. നിയമങ്ങളില്ലെങ്കിൽ ഓരോരുത്തരും അവരവരുടെ സ്ഥിര ശതമാനം നേടും.',
