  '{n} days are not marked yet. Unmarked days are not paid until they are.': '{n} ദിവസം ഇതുവരെ രേഖപ്പെടുത്തിയിട്ടില്ല. രേഖപ്പെടുത്താത്ത ദിവസങ്ങൾക്ക് അതുവരെ ശമ്പളമില്ല.',
  'People, attendance and payroll for your workshop and counter': 'നിങ്ങളുടെ വർക്ക്‌ഷോപ്പിനും കൗണ്ടറിനുമുള്ള ആളുകൾ, ഹാജർ, ശമ്പളം',
  'You do not have access to staff.': 'സ്റ്റാഫിന് നിങ്ങൾക്ക് അനുമതിയില്ല.',
  'Add your mechanics and counter staff.': 'നിങ്ങളുടെ മെക്കാനിക്കുകളെയും കൗണ്ടർ സ്റ്റാഫിനെയും ചേർക്കുക.',
  'Job title': 'തസ്തിക',
  'Mechanic, counter, storekeeper': 'മെക്കാനിക്, കൗണ്ടർ, സ്റ്റോർകീപ്പർ',
