  'One decimal': 'ஒரு தசமம்',
  'Two decimals': 'இரண்டு தசமம்',
  'How this phone shows the app. It stays on this phone and changes nothing on your bills or reports.': 'இந்தத் தொலைபேசி செயலியை எப்படிக் காட்டுகிறது. இது இந்தத் தொலைபேசியிலேயே இருக்கும்; உங்கள் பில்கள் அல்லது அறிக்கைகளில் எதையும் மாற்றாது.',
  'Receipts and shared bills always show the exact amount.': 'ரசீதுகளும் பகிரப்பட்ட பில்களும் எப்போதும் சரியான தொகையைக் காட்டும்.',
  'Download a copy of all your records (customers, products, bills, payments, expenses and stock) as a ZIP of CSV files, then save or send it from the share sheet. Keep it somewhere safe. FlowXP does not restore from it by itself: ask support if you ever need your data put back.': 'உங்கள் எல்லா பதிவுகளின் (வாடிக்கையாளர்கள், பொருட்கள், பில்கள், கட்டணங்கள், செலவுகள், இருப்பு) நகலை CSV கோப்புகளின் ZIP ஆகப் பதிவிறக்கி, பகிர்வுத் திரையிலிருந்து சேமிக்கவும் அல்லது அனுப்பவும். பாதுகாப்பாக வைத்திருங்கள். FlowXP இதிலிருந்து தானாக மீட்டெடுக்காது: தரவு மீண்டும் வேண்டுமெனில் ஆதரவைக் கேளுங்கள்.',
  'Could not take the backup.': 'காப்புப்பிரதி எடுக்க முடியவில்லை.',
  'Could not take the backup. Only the owner can, and the phone needs a connection.': 'காப்புப்பிரதி எடுக்க முடியவில்லை. உரிமையாளர் மட்டுமே எடுக்க முடியும், தொலைபேசிக்கு இணைப்பு தேவை.',
  'This phone cannot share files from FlowXP.': 'இந்தத் தொலைபேசியால் FlowXP இலிருந்து கோப்புகளைப் பகிர முடியாது.',
