  'E. & O.E.': 'E. & O.E.',
  'Cut the paper after each receipt': 'ஒவ்வொரு ரசீதுக்குப் பிறகும் காகிதத்தை வெட்டு',
  'Composite scheme': 'கூட்டுத் திட்டம் (Composition)',
  'You pay a flat share of your turnover instead of charging GST. Bills become Bills of Supply with no tax on them.': 'GST வசூலிப்பதற்குப் பதிலாக உங்கள் விற்றுமுதலில் ஒரு நிலையான பங்கை செலுத்துகிறீர்கள். பில்கள் வரி இல்லாத விநியோக பில்களாக மாறும்.',
  'Composite tax rate (% of turnover)': 'கூட்டு வரி விகிதம் (விற்றுமுதலின் %)',
  'Compensation cess on top of GST. Set the cess rate on each product (Products → edit); it is added to the line and the bill.': 'GST-க்கு மேல் இழப்பீட்டு செஸ் வரி. ஒவ்வொரு பொருளிலும் செஸ் விகிதத்தை அமைக்கவும் (பொருட்கள் → திருத்து); இது வரியிலும் பில்லிலும் சேர்க்கப்படும்.',
  'TCS (tax collected at source)': 'TCS (மூலத்தில் வசூலிக்கப்படும் வரி)',
  'A "Collect TCS" tick appears on the billing screen. When ticked, the TCS is added to that bill.': 'பில்லிங் திரையில் "TCS வசூலிக்கவும்" என்ற டிக் தோன்றும். டிக் செய்தால் அந்த பில்லில் TCS சேர்க்கப்படும்.',
  'TCS rate (%)': 'TCS விகிதம் (%)',
  'TDS (tax deducted by the customer)': 'TDS (வாடிக்கையாளர் பிடித்தம் செய்யும் வரி)',
  'A "Customer deducts TDS" tick appears on the billing screen. When ticked, the TDS is taken off what the customer pays and noted on the bill.': 'பில்லிங் திரையில் "வாடிக்கையாளர் TDS பிடித்தம் செய்கிறார்" என்ற டிக் தோன்றும். டிக் செய்தால் வாடிக்கையாளர் செலுத்தும் தொகையிலிருந்து TDS கழிக்கப்பட்டு பில்லில் குறிக்கப்படும்.',
  'TDS rate (%)': 'TDS விகிதம் (%)',
  'A "Tax payable on reverse charge" tick appears on the billing screen and prints on the invoice.': 'பில்லிங் திரையில் "தலைகீழ் வரி முறையில் செலுத்த வேண்டிய வரி" என்ற டிக் தோன்றி விலைப்பட்டியலில் அச்சாகும்.',
  'Details, receipt, GST and invoice (owner)': 'விவரங்கள், ரசீது, GST, விலைப்பட்டியல் (உரிமையாளர்)',
  'Only the owner can change business settings.': 'உரிமையாளர் மட்டுமே தொழில் அமைப்புகளை மாற்ற முடியும்.',
  'Receipt and tax invoice details': 'ரசீது மற்றும் வரி விலைப்பட்டியல் விவரங்கள்',
  'What prints on receipts, and the PAN, bank details and terms a tax invoice carries.': 'ரசீதுகளில் எதை அச்சிடுவது, வரி விலைப்பட்டியலில் உள்ள PAN, வங்கி விவரங்கள், விதிமுறைகள்.',
  'How your A4 and A5 invoices look.': 'உங்கள் A4 மற்றும் A5 விலைப்பட்டியல்கள் எப்படி இருக்க வேண்டும்.',
  'Nothing changed.': 'எதுவும் மாறவில்லை.',
  'Optional. Only needed if you charge GST.': 'விருப்பம். GST வசூலித்தால் மட்டுமே தேவை.',
  'Copies': 'நகல்கள்',
  'Print the logo at the top of receipts': 'ரசீதுகளின் மேலே லோகோவை அச்சிடு',
  'Show the GSTIN on receipts': 'ரசீதுகளில் GSTIN ஐக் காட்டு',
  'Show a UPI QR for any unpaid balance': 'நிலுவைத் தொகைக்கு UPI QR ஐக் காட்டு',
  'Show the customer\'s loyalty card line': 'வாடிக்கையாளரின் லாயல்டி அட்டை வரியைக் காட்டு',
