  'Next number': 'அடுத்த எண்',
  'Decides GST place of supply for this outlet.': 'இந்தக் கிளைக்கான ஜிஎஸ்டி விநியோக இடத்தைத் தீர்மானிக்கும்.',
  'For GST e-invoices and e-way bills': 'ஜிஎஸ்டி மின்-விலைப்பட்டியல்கள் மற்றும் மின்-வழி பில்களுக்கு',
  'Optional. Gives this outlet its own numbers (IND-0001). Empty uses the business-wide series.': 'விருப்பம். இந்தக் கிளைக்குத் தனி எண்களைத் தரும் (IND-0001). காலியாக இருந்தால் வணிகம் முழுவதும் உள்ள தொடர் பயன்படும்.',
  'Only if this outlet has its own registration.': 'இந்தக் கிளைக்குத் தனிப் பதிவு இருந்தால் மட்டும்.',
  'Never lower than numbers already issued.': 'ஏற்கனவே வழங்கிய எண்களை விடக் குறையாது.',
