  'Avg order': 'சராசரி ஆர்டர்',
  'Comparing outlets is for owners and group managers.': 'கிளைகளை ஒப்பிடுவது உரிமையாளர்கள் மற்றும் குழு மேலாளர்களுக்கானது.',
