  '90 days': '90 நாட்கள்',
  'Only owners and admins can manage this.': 'இதை உரிமையாளர்களும் நிர்வாகிகளும் மட்டுமே நிர்வகிக்க முடியும்.',
  'Permissions': 'அனுமதிகள்',
  'Choose an outlet': 'ஒரு கிளையைத் தேர்ந்தெடுக்கவும்',
  'Leave on "Every outlet" for a group-level manager.': 'குழு அளவிலான மேலாளருக்கு "அனைத்து கிளைகளும்" என்றே விடவும்.',
  'Disabled: can\'t sign in to this business': 'முடக்கப்பட்டது: இந்தத் தொழிலில் உள்நுழைய முடியாது',
  '{role}s can see every outlet.': '{role} அனைத்து கிளைகளையும் காணலாம்.',
  'Sent {email} a link to set their password': '{email} க்கு கடவுச்சொல்லை அமைக்கும் இணைப்பு அனுப்பப்பட்டது',
