  'Notifications': 'அறிவிப்புகள்',
  'What needs your attention, so you don\'t have to go looking.': 'உங்கள் கவனம் தேவைப்படுவது எது, நீங்கள் தேட வேண்டியதில்லை.',
  'Mark all read': 'எல்லாவற்றையும் படித்ததாகக் குறி',
  'Unread only': 'படிக்காதவை மட்டும்',
  'Nothing unread.': 'படிக்காதது எதுவும் இல்லை.',
  'What to tell me about': 'எதைப் பற்றி எனக்குச் சொல்ல வேண்டும்',
  'In app': 'ஆப்பில்',
  'There are no notification settings for your role.': 'உங்கள் பங்குக்கு அறிவிப்பு அமைப்புகள் எதுவும் இல்லை.',
  'Email goes to the address you sign in with. Phone alerts go to the FlowXP app on the phones you are signed in on. Notifications are never sent to customers.': 'மின்னஞ்சல் நீங்கள் உள்நுழையும் முகவரிக்குச் செல்லும். தொலைபேசி எச்சரிக்கைகள் நீங்கள் உள்நுழைந்துள்ள தொலைபேசிகளின் FlowXP ஆப்பிற்குச் செல்லும். அறிவிப்புகள் வாடிக்கையாளர்களுக்கு ஒருபோதும் அனுப்பப்படாது.',
  'Accountant pack': 'கணக்காளர் தொகுப்பு',
  'One ZIP of CSV files for the period: sales and purchase registers, HSN and tax-rate summaries, profit and loss, expenses, every transaction, and what is owed each way.': 'இந்தக் காலத்துக்கான CSV கோப்புகளின் ஒரு ZIP: விற்பனை, கொள்முதல் பதிவேடுகள், HSN மற்றும் வரி விகிதச் சுருக்கங்கள், லாப நஷ்டம், செலவுகள், ஒவ்வொரு பரிவர்த்தனை, இரு பக்க நிலுவை.',
