  'How last week went, every Monday morning.': 'கடந்த வாரம் எப்படி சென்றது, ஒவ்வொரு திங்கள் காலையும்.',
  'Unusual numbers': 'வழக்கத்திற்கு மாறான எண்கள்',
  'A sudden drop or spike in sales, margin, discounts or expenses, or items sold below cost.': 'விற்பனை, மார்ஜின், தள்ளுபடி அல்லது செலவில் திடீர் வீழ்ச்சி அல்லது உயர்வு, அல்லது விலைக்குக் கீழே விற்ற பொருட்கள்.',
  'Integrations': 'ஒருங்கிணைப்புகள்',
  'A delivery platform order that could not be received.': 'பெற முடியாத ஒரு டெலிவரி தளத்தின் ஆர்டர்.',
