  'A guest or a delivery app has sent an order that needs accepting or cooking.': 'ஒரு விருந்தினர் அல்லது டெலிவரி செயலி அனுப்பிய ஆர்டரை ஏற்க அல்லது சமைக்க வேண்டும்.',
  'Order ready': 'ஆர்டர் தயார்',
