  'Gaming timers': 'கேமிங் நேரக்கணிப்புகள்',
  'A station is nearly out of time, or its time is over.': 'ஒரு நிலையத்தின் நேரம் கிட்டத்தட்ட முடிந்தது, அல்லது முடிந்துவிட்டது.',
  'New bookings': 'புதிய முன்பதிவுகள்',
  'A client has booked online.': 'ஒரு வாடிக்கையாளர் ஆன்லைனில் முன்பதிவு செய்துள்ளார்.',
  'This quarter': 'இந்தக் காலாண்டு',
