  'Preparing…': 'தயாராகிறது…',
  'Enter the accountant\'s email address.': 'கணக்காளரின் மின்னஞ்சல் முகவரியை உள்ளிடவும்.',
  'Sent: {email}': 'அனுப்பப்பட்டது: {email}',
  'Their address is remembered for next time.': 'அவர்களின் முகவரி அடுத்த முறைக்கு நினைவில் வைக்கப்படும்.',
  'Send the bill on WhatsApp': 'பில்லை WhatsApp-இல் அனுப்பவும்',
