  'Offers the till applies by itself: percentage off, buy some get some free, or a bundle price.': 'டில் தானாகப் பயன்படுத்தும் சலுகைகள்: சதவீதத் தள்ளுபடி, சிலவற்றை வாங்கினால் சில இலவசம், அல்லது தொகுப்பு விலை.',
  'Try “3 for ₹140” on milk, or 10% off a whole category this weekend.': 'பாலுக்கு “3 ₹140க்கு” முயற்சிக்கவும், அல்லது இந்த வார இறுதியில் முழு வகைக்கும் 10% தள்ளுபடி.',
