  'Products in the bundle': 'தொகுப்பில் உள்ள பொருட்கள்',
  'Pick two or more. Any of them can make up the bundle.': 'இரண்டு அல்லது அதற்கு மேல் தேர்ந்தெடுக்கவும். இவற்றில் எதுவும் தொகுப்பாக அமையலாம்.',
  'Search by name, SKU or barcode, then tap to add': 'பெயர், SKU அல்லது பார்கோடு மூலம் தேடி, சேர்க்கத் தட்டவும்',
