  'From (time of day)': 'முதல் (நாளின் நேரம்)',
  'Both, or neither. An end before the start runs overnight.': 'இரண்டும், அல்லது எதுவும் வேண்டாம். தொடக்கத்துக்கு முன் முடிவு என்றால் இரவு முழுவதும் நடக்கும்.',
  'Only when the bill has a customer on it': 'பில்லில் வாடிக்கையாளர் இருக்கும்போது மட்டும்',
  'If several offers fit one product, the one that saves the most is used. Offers never add up on top of each other.': 'ஒரு பொருளுக்குப் பல சலுகைகள் பொருந்தினால் அதிகம் சேமிப்பதே பயன்படுத்தப்படும். சலுகைகள் ஒன்றுடன் ஒன்று சேராது.',
  'Save the offer': 'சலுகையைச் சேமி',
  'Give the offer a name (up to 80 characters)': 'சலுகைக்குப் பெயர் கொடுங்கள் (80 எழுத்து வரை)',
  'Choose at least two products for a mix-and-match bundle': 'கலந்து தேர்ந்தெடுக்கும் தொகுப்புக்குக் குறைந்தது இரண்டு பொருட்களைத் தேர்ந்தெடுக்கவும்',
  'Choose the product the offer is for': 'சலுகை எந்தப் பொருளுக்கு என்பதைத் தேர்ந்தெடுக்கவும்',
  'Choose the category the offer is for': 'சலுகை எந்த வகைக்கு என்பதைத் தேர்ந்தெடுக்கவும்',
  'The percentage must be above 0 and at most 100': 'சதவீதம் 0க்கு மேல் இருக்க வேண்டும், அதிகபட்சம் 100',
  'From quantity must be at least 1': 'குறைந்தபட்ச அளவு குறைந்தது 1 ஆக இருக்க வேண்டும்',
  'Enter how many the customer buys and how many are free': 'வாடிக்கையாளர் எத்தனை வாங்குகிறார், எத்தனை இலவசம் என்பதை உள்ளிடவும்',
