  'Customers get {item} free on their visit {n}, then the card starts again.': 'வாடிக்கையாளர்களுக்கு அவர்களின் வருகை {n}-ல் {item} இலவசம், பிறகு அட்டை மீண்டும் தொடங்கும்.',
  'Pick the item that will be free.': 'இலவசமாகும் பொருளைத் தேர்ந்தெடுக்கவும்.',
  'Only bills of {value} or more earn a stamp.': '{value} அல்லது அதற்கு மேற்பட்ட பில்களுக்கு மட்டுமே முத்திரை கிடைக்கும்.',
  'Worth {value} to the customer.': 'வாடிக்கையாளருக்கு {value} மதிப்பு.',
  'A customer is their mobile number. Every day they are billed counts as one visit, at any outlet. On the visit that earns it, the free item comes off the bill once it is on the order (the till offers to add it).': 'வாடிக்கையாளர் என்பது அவர்களின் மொபைல் எண். பில் போடப்படும் ஒவ்வொரு நாளும் ஒரு வருகையாகக் கணக்கிடப்படும், எந்தக் கிளையிலும். பரிசு கிடைக்கும் வருகையில், இலவசப் பொருள் ஆர்டரில் சேர்ந்ததும் பில்லிலிருந்து கழிக்கப்படும் (டில் அதைச் சேர்க்க பரிந்துரைக்கும்).',
  '{n} new in the last 30 days': 'கடந்த 30 நாட்களில் {n} புதியவர்கள்',
  'Came back, 30 days': '30 நாட்களில் திரும்பியவர்கள்',
  '{n} visits stamped': '{n} வருகைகளுக்கு முத்திரை',
  'Free items given': 'வழங்கிய இலவசப் பொருட்கள்',
  '{n} in 30 days · worth {value}': '30 நாட்களில் {n} · மதிப்பு {value}',
  'Not back in 60 days': '60 நாட்களில் திரும்பவில்லை',
  'Free item due now': 'இலவசப் பொருள் இப்போது கிடைக்கும்',
  'One visit away': 'ஒரு வருகை தொலைவில்',
  'Their next bill gets the free item. A nice reason to call them in.': 'அவர்களின் அடுத்த பில்லில் இலவசப் பொருள் கிடைக்கும். அவர்களை அழைக்க நல்ல காரணம்.',
  'One more visit and the next one is free.': 'இன்னும் ஒரு வருகை, அடுத்தது இலவசம்.',
  'Nobody has a reward waiting.': 'யாருடைய பரிசும் காத்திருக்கவில்லை.',
  'Nobody is one visit away right now.': 'இப்போது யாரும் ஒரு வருகை தொலைவில் இல்லை.',
  '{visits} visits · last {when}': '{visits} வருகைகள் · கடைசி {when}',
  'today': 'இன்று',
  'How often members come': 'உறுப்பினர்கள் எத்தனை முறை வருகிறார்கள்',
  'Visits on the card since they joined.': 'சேர்ந்ததிலிருந்து அட்டையில் உள்ள வருகைகள்.',
