  'The price change is added to the dish\'s price. An option can use up an ingredient (extra cheese uses 20 g of cheese), so stock stays right.': 'விலை மாற்றம் உணவின் விலையுடன் சேர்க்கப்படும். ஒரு விருப்பம் ஒரு பொருளைப் பயன்படுத்தலாம் (கூடுதல் சீஸ் 20 கிராம் சீஸ் பயன்படுத்தும்), அதனால் இருப்பு சரியாக இருக்கும்.',
