  'At most must be a whole number from 1, or blank for no limit': 'அதிகபட்சம் 1-இலிருந்து தொடங்கும் முழு எண்ணாக இருக்க வேண்டும், வரம்பு வேண்டாமென்றால் காலியாக விடவும்',
  'At most cannot be less than at least': 'அதிகபட்சம் குறைந்தபட்சத்தை விடக் குறைவாக இருக்கக்கூடாது',
  'There are fewer options than the least a customer must pick': 'வாடிக்கையாளர் குறைந்தது தேர்ந்தெடுக்க வேண்டியதை விடக் குறைவான விருப்பங்களே உள்ளன',
  'You do not have access to options.': 'விருப்பங்களுக்கு உங்களுக்கு அனுமதி இல்லை.',
