  'Credit notes are for goods customers brought back. Debit notes are for goods sent back to a supplier, or a price correction.': 'வாடிக்கையாளர்கள் திருப்பிக் கொண்டு வந்த பொருட்களுக்கு கிரெடிட் நோட்டுகள். சப்ளையருக்குத் திருப்பி அனுப்பிய பொருட்கள் அல்லது விலைத் திருத்தத்துக்கு டெபிட் நோட்டுகள்.',
