  'Choose at least one line': 'குறைந்தது ஒரு வரியைத் தேர்ந்தெடுக்கவும்',
  'Arrived {n}, can still go back {left}': '{n} வந்தது, {left} இன்னும் திருப்பி அனுப்பலாம்',
  'Arrived {n}': '{n} வந்தது',
  'Overcharge per unit (₹)': 'ஒரு அலகுக்கு கூடுதல் வசூல் (₹)',
  'About {value} will come off what you owe, tax included.': 'நீங்கள் கொடுக்க வேண்டியதிலிருந்து சுமார் {value} குறையும், வரி உட்பட.',
  'Issue the debit note': 'டெபிட் நோட்டை வழங்கு',
  'Only an order that has arrived can have a debit note.': 'வந்து சேர்ந்த ஆர்டருக்கு மட்டுமே டெபிட் நோட்டு இருக்க முடியும்.',
  'Only {n} of {name} can still be returned': '{name}-ல் {n} மட்டுமே இன்னும் திருப்பி அனுப்ப முடியும்',
  'Only {n} of {name} arrived': '{name}-ல் {n} மட்டுமே வந்தது',
  'Enter the overcharge per unit for {name}': '{name}-க்கான ஒரு அலகு கூடுதல் வசூலை உள்ளிடவும்',
  'The overcharge cannot be more than the price paid for {name}': 'கூடுதல் வசூல் {name}-க்குச் செலுத்திய விலையை விட அதிகமாக இருக்கக்கூடாது',
  'You do not have access to notes.': 'நோட்டுகளைப் பார்க்க உங்களுக்கு அனுமதி இல்லை.',
