  'Next billing date': 'அடுத்த கட்டணத் தேதி',
  'Trial ended': 'சோதனை முடிந்தது',
  'Your trial has ended. Everything you created is still here and still readable. Paying turns billing back on.': 'உங்கள் சோதனை முடிந்தது. நீங்கள் உருவாக்கியவை அனைத்தும் இன்னும் இங்கே உள்ளன, படிக்கலாம். கட்டணம் செலுத்தினால் பில்லிங் மீண்டும் இயங்கும்.',
  '{amount} / {cycle}': '{amount} / {cycle}',
  'A payment link was sent for your account. Pay on Cashfree\'s secure page. We never see your card or UPI details.': 'உங்கள் கணக்குக்கு கட்டண இணைப்பு அனுப்பப்பட்டது. Cashfree-யின் பாதுகாப்பான பக்கத்தில் செலுத்துங்கள். உங்கள் கார்டு அல்லது UPI விவரங்களை நாங்கள் ஒருபோதும் பார்ப்பதில்லை.',
  'Pay {amount} now': 'இப்போது {amount} செலுத்து',
  '{price}/month': '{price}/மாதம்',
  'Pricing on request': 'விலை கோரிக்கையின் பேரில்',
  'Pricing is agreed with our team, not self-serve. Contact flowxp.manager@gmail.com and we will send a secure payment link for your plan.': 'விலை எங்கள் குழுவுடன் ஒப்புக்கொள்ளப்படும், தானாக அல்ல. flowxp.manager@gmail.com-ஐத் தொடர்புகொள்ளுங்கள், உங்கள் திட்டத்துக்கான பாதுகாப்பான கட்டண இணைப்பை அனுப்புவோம்.',
  'Only the owner can see the subscription.': 'உரிமையாளர் மட்டுமே சந்தாவைப் பார்க்க முடியும்.',
  'Could not open the payment page.': 'கட்டணப் பக்கத்தைத் திறக்க முடியவில்லை.',
