  'Settlements': 'தீர்வுகள்',
  'Check the statement each delivery platform pays against what was billed here.': 'ஒவ்வொரு டெலிவரி தளமும் செலுத்தும் அறிக்கையை இங்கே பில் செய்தவற்றுடன் சரிபார்க்கவும்.',
  'Import a statement': 'அறிக்கையை இறக்குமதி செய்',
  'One settled order per line, comma separated, in this order: {columns}. Leave charges blank if the platform does not break them out.': 'ஒவ்வொரு வரியிலும் ஒரு தீர்க்கப்பட்ட ஆர்டர், காற்புள்ளியால் பிரித்து, இந்த வரிசையில்: {columns}. தளம் கட்டணங்களைப் பிரித்துத் தராவிட்டால் காலியாக விடவும்.',
