  'Billed orders with no matching statement line at all yet: money that should have been paid.': 'இதுவரை பொருந்தும் அறிக்கை வரியே இல்லாத பில் செய்த ஆர்டர்கள்: செலுத்தப்பட்டிருக்க வேண்டிய பணம்.',
  'Nothing unpaid, as far as an imported statement can tell.': 'இறக்குமதி செய்த அறிக்கையின்படி எதுவும் செலுத்தப்படாமல் இல்லை.',
