  'What your sales actually leave, after the costs that come with them.': 'அவற்றுடன் வரும் செலவுகளுக்குப் பிறகு உங்கள் விற்பனை உண்மையில் மிச்சப்படுத்துவது.',
  'Built from recorded sales and your cost assumptions, not an accounting figure.': 'பதிவான விற்பனை மற்றும் உங்கள் செலவு அனுமானங்களிலிருந்து உருவாக்கப்பட்டது, கணக்கியல் எண் அல்ல.',
