  'revenue {value}': 'வருவாய் {value}',
  '{value} per portion': 'ஒரு பகுதிக்கு {value}',
  'No items sold in this period.': 'இந்தக் காலத்தில் எந்தப் பொருளும் விற்கப்படவில்லை.',
  'FlowXP cannot know what your card machine or delivery platform charges. Enter your real rates; anything left at 0 is not deducted.': 'உங்கள் கார்டு இயந்திரம் அல்லது டெலிவரி தளம் எவ்வளவு வசூலிக்கிறது என்பதை FlowXP அறிய முடியாது. உங்கள் உண்மையான விகிதங்களை உள்ளிடவும்; 0-ஆக விட்டது கழிக்கப்படாது.',
  'Payment fees (% of amount collected)': 'கட்டணக் கட்டணங்கள் (வசூலித்த தொகையின் %)',
  'Delivery platform commission (% of food value)': 'டெலிவரி தளக் கமிஷன் (உணவு மதிப்பின் %)',
  'Packaging per takeaway / delivery order (₹)': 'ஒரு டேக்அவே / டெலிவரி ஆர்டருக்கு பேக்கேஜிங் (₹)',
  'Box, bag, cutlery.': 'பெட்டி, பை, கட்லரி.',
  'Save assumptions': 'அனுமானங்களைச் சேமி',
  'A rate is a percentage from 0 to 100': 'விகிதம் 0 முதல் 100 வரையிலான சதவீதம்',
  'Packaging must be an amount in rupees': 'பேக்கேஜிங் ரூபாயில் ஒரு தொகையாக இருக்க வேண்டும்',
  'Net revenue is what was billed before tax, minus discounts and refunds. Cancelled invoices are left out. Food cost is the ingredient cost recorded on each bill when it was made. Fees, commission and packaging use your assumptions: unset means zero. Contribution is what each sale leaves toward rent, salaries and other fixed costs.': 'நிகர வருவாய் என்பது வரிக்கு முன் பில் செய்ததிலிருந்து தள்ளுபடிகள், திருப்பங்களைக் கழித்தது. ரத்தான இன்வாய்ஸ்கள் விடப்படும். உணவுச் செலவு என்பது ஒவ்வொரு பில்லும் உருவான போது பதிவான மூலப்பொருள் செலவு. கட்டணங்கள், கமிஷன், பேக்கேஜிங் உங்கள் அனுமானங்களைப் பயன்படுத்தும்: அமைக்காவிட்டால் பூஜ்யம். வாடகை, சம்பளம், பிற நிலையான செலவுகளுக்கு ஒவ்வொரு விற்பனையும் மிச்சப்படுத்துவது பங்களிப்பு.',
  'What to expect, and what to have in the kitchen for it.': 'என்ன எதிர்பார்க்கலாம், அதற்காக சமையலறையில் என்ன இருக்க வேண்டும்.',
  'Demand': 'தேவை',
  'Working out the week ahead…': 'வரும் வாரத்தைக் கணக்கிடுகிறது…',
  'Not enough history': 'போதிய வரலாறு இல்லை',
  'Not enough history yet to check how accurate this has been.': 'இது எவ்வளவு துல்லியமாக இருந்தது என்பதைச் சரிபார்க்க இன்னும் போதிய வரலாறு இல்லை.',
  'On the last {days} days the same method was off by {pct}% on average for orders.': 'கடந்த {days} நாட்களில் இதே முறை ஆர்டர்களுக்குச் சராசரியாக {pct}% தவறியது.',
  'It tended to run {pct}% high.': 'இது {pct}% அதிகமாக இருக்கும் போக்கு காட்டியது.',
  'It tended to run {pct}% low.': 'இது {pct}% குறைவாக இருக்கும் போக்கு காட்டியது.',
