  'low': 'குறைவு',
  'hour by hour': 'மணிநேரம் வாரியாக',
  'No hourly pattern yet.': 'இன்னும் மணிநேர வடிவம் இல்லை.',
  'Expected portions': 'எதிர்பார்க்கும் பகுதிகள்',
  'portions': 'பகுதிகள்',
  'No item history yet.': 'இன்னும் பொருள் வரலாறு இல்லை.',
  'Things you know that history does not': 'வரலாற்றுக்குத் தெரியாதது, உங்களுக்குத் தெரிந்தவை',
  'A festival, a match night, a promotion, a planned closure. Tell FlowXP and it adjusts that day\'s forecast.': 'ஒரு திருவிழா, போட்டி இரவு, விளம்பரம், திட்டமிட்ட மூடல். FlowXP-இடம் சொல்லுங்கள், அந்த நாளின் முன்கணிப்பை அது சரிசெய்யும்.',
  'What is happening': 'என்ன நடக்கிறது',
  'e.g. Diwali weekend': 'எ.கா. தீபாவளி வார இறுதி',
  'Expected change %': 'எதிர்பார்க்கும் மாற்றம் %',
  'Say what is happening': 'என்ன நடக்கிறது என்று சொல்லுங்கள்',
  'Enter the expected change as a number': 'எதிர்பார்க்கும் மாற்றத்தை எண்ணாக உள்ளிடவும்',
  'Event added, forecasts updated': 'நிகழ்வு சேர்க்கப்பட்டது, முன்கணிப்புகள் புதுப்பிக்கப்பட்டன',
