  'Draft orders created. See Purchases.': 'வரைவு ஆர்டர்கள் உருவாக்கப்பட்டன. கொள்முதலைப் பாருங்கள்.',
  'Everything suggested is already on an open order.': 'பரிந்துரைத்த அனைத்தும் ஏற்கனவே திறந்த ஆர்டரில் உள்ளன.',
  'Nothing needs ordering right now.': 'இப்போது எதுவும் ஆர்டர் செய்யத் தேவையில்லை.',
  'Nothing is ordered until you send it.': 'நீங்கள் அனுப்பும் வரை எதுவும் ஆர்டர் செய்யப்படாது.',
  'Every tracked item': 'கண்காணிக்கப்படும் ஒவ்வொரு பொருளும்',
