  'Not enough usage history yet: forecasts start once an item has a week of use.': 'பயன்பாட்டு வரலாறு போதாது: ஒரு பொருளுக்கு ஒரு வாரப் பயன்பாடு இருந்தால் முன்கணிப்பு தொடங்கும்.',
  'Projecting stock…': 'இருப்பைக் கணிக்கிறது…',
