  'Activity that differs from your own normal and may be costing you money.': 'உங்கள் சொந்த வழக்கத்திலிருந்து வேறுபட்டு உங்களுக்குப் பணம் இழப்பை ஏற்படுத்தக்கூடிய செயல்பாடு.',
  'Only the owner and admins can see this page.': 'இந்தப் பக்கத்தை உரிமையாளரும் நிர்வாகிகளும் மட்டுமே பார்க்க முடியும்.',
  'Checking your records…': 'உங்கள் பதிவுகளைச் சரிபார்க்கிறது…',
  'Potential leakage detected': 'சாத்தியமான கசிவு கண்டறியப்பட்டது',
