  '{n} needing attention': '{n} கவனம் தேவை',
  'Nothing unusual found in the last {n} days. FlowXP compares against your own normal, so this improves as your history grows.': 'கடந்த {n} நாட்களில் வழக்கத்துக்கு மாறாக எதுவும் இல்லை. FlowXP உங்கள் சொந்த வழக்கத்துடன் ஒப்பிடுகிறது, எனவே வரலாறு வளரும்போது இது மேம்படும்.',
  'Stock adjustments': 'இருப்புச் சரிசெய்தல்கள்',
