  'Hide reviewed or dismissed': 'மதிப்பாய்வு செய்த அல்லது நிராகரித்தவற்றை மறை',
  'Kitchen performance': 'சமையலறை செயல்திறன்',
  'How long dishes take from being sent to being ready.': 'உணவுகள் அனுப்பப்பட்டதிலிருந்து தயாராகும் வரை எவ்வளவு நேரம் எடுக்கின்றன.',
  'You need report access to see kitchen performance.': 'சமையலறை செயல்திறனைப் பார்க்க உங்களுக்கு அறிக்கை அனுமதி தேவை.',
  'Reading the tickets…': 'டிக்கெட்டுகளைப் படிக்கிறது…',
  'No finished tickets in this period yet. Times are recorded from when an order is sent to the kitchen until the kitchen marks it ready.': 'இந்தக் காலத்தில் இன்னும் முடிந்த டிக்கெட்டுகள் இல்லை. ஆர்டர் சமையலறைக்கு அனுப்பப்பட்டதிலிருந்து சமையலறை தயார் எனக் குறிக்கும் வரை நேரம் பதிவாகும்.',
  'Average preparation': 'சராசரி தயாரிப்பு',
