  '{name} now averages {now} minutes, up from {before}.': '{name} இப்போது சராசரியாக {now} நிமிடங்கள் எடுக்கிறது, முன்பு {before}.',
  'Worth asking: is it staffing at peak, a missing ingredient, a change to how it is made, or does the set time need updating?': 'கேட்கத் தகுந்தது: உச்ச நேர ஊழியர்களா, ஒரு பொருள் இல்லையா, செய்முறை மாறியதா, அல்லது நிர்ணய நேரத்தைப் புதுப்பிக்க வேண்டுமா?',
  'slowest 1 in 10: {v}': '10-ல் மிக மெதுவான 1: {v}',
  'on time {pct}': 'நேரத்தில் {pct}',
  'Average time by hour sent': 'அனுப்பிய மணிநேரப்படி சராசரி நேரம்',
  'Busy hours usually run slower; a big gap here is a staffing question.': 'பரபரப்பான மணிநேரங்கள் பொதுவாக மெதுவாக இருக்கும்; இங்கு பெரிய இடைவெளி ஊழியர் பற்றிய கேள்வி.',
  'By dish': 'உணவு வாரியாக',
  'Dishes with at least 3 finished items.': 'குறைந்தது 3 முடிந்த பொருட்கள் உள்ள உணவுகள்.',
  'set time {v}': 'நிர்ணய நேரம் {v}',
  'What your sales leave after food cost, fees and commission': 'உணவுச் செலவு, கட்டணங்கள், கமிஷனுக்குப் பிறகு உங்கள் விற்பனை மிச்சப்படுத்துவது',
  'The week ahead, and what to buy for it': 'வரும் வாரம், அதற்கு என்ன வாங்க வேண்டும்',
  'Unusual discounts, cancellations, refunds and wastage': 'வழக்கத்துக்கு மாறான தள்ளுபடிகள், ரத்துகள், திருப்பங்கள், வீணடிப்பு',
