  'Each hall has its capacity and the rent for one function.': 'ஒவ்வொரு மண்டபத்திற்கும் அதன் கொள்ளளவும் ஒரு நிகழ்வுக்கான வாடகையும் உண்டு.',
  'Add a hall': 'மண்டபத்தைச் சேர்',
  'No banquet halls yet.': 'விருந்து மண்டபங்கள் இன்னும் இல்லை.',
