  'Standing': 'நிலையான',
  'Rent a function': 'நிகழ்வுக்கு வாடகை',
  'What the hall has': 'மண்டபத்தில் என்ன உள்ளது',
  'Stage, air conditioning, projector, parking': 'மேடை, ஏர் கண்டிஷனிங், புரொஜெக்டர், வாகன நிறுத்தம்',
  'Menu packages': 'உணவுப்பட்டியல் தொகுப்புகள்',
  'A package is a menu with a price a plate. Pick one when you plan a function and the food is charged for the guaranteed guests.': 'தொகுப்பு என்பது தட்டுக்கு விலை கொண்ட உணவுப்பட்டியல். நிகழ்ச்சியைத் திட்டமிடும்போது ஒன்றைத் தேர்ந்தெடுக்கவும்; உறுதியான விருந்தினர்களுக்கு உணவுக்குக் கட்டணம் விதிக்கப்படும்.',
  'Add a package': 'தொகுப்பைச் சேர்',
  'No packages yet.': 'தொகுப்புகள் இன்னும் இல்லை.',
  'Diet': 'உணவுமுறை',
  'Price a plate': 'தட்டுக்கு விலை',
  'Fewest guests charged': 'மிகக் குறைந்த விருந்தினர்களுக்கான கட்டணம்',
  'GST %': 'ஜிஎஸ்டி %',
  'Menu': 'பட்டியல்',
  'Welcome drink, two starters, three mains, rice, breads, dessert': 'வரவேற்புப் பானம், இரண்டு ஸ்டார்ட்டர்கள், மூன்று முதன்மை உணவுகள், சாதம், ரொட்டிகள், இனிப்பு',
  'Check-in and check-out': 'செக்-இன் மற்றும் செக்-அவுட்',
  'Check-in from': 'செக்-இன் முதல்',
