  'Booking number prefix': 'முன்பதிவு எண் முன்னொட்டு',
  'The hotel\'s date today': 'இன்றைய ஹோட்டல் தேதி',
  'You can set this until you run the first night audit. After that only night audit moves it.': 'முதல் இரவுத் தணிக்கையை இயக்கும் வரை இதை அமைக்கலாம். அதன் பிறகு இரவுத் தணிக்கை மட்டுமே இதை நகர்த்தும்.',
  'Only night audit moves this now.': 'இப்போது இரவுத் தணிக்கை மட்டுமே இதை நகர்த்தும்.',
  'GST on room tariff': 'அறைக் கட்டணத்திற்கு GST',
  'Limit a night': 'ஓர் இரவுக்கான வரம்பு',
  'Up to this, the lower rate applies': 'இது வரை குறைந்த விகிதம் பொருந்தும்',
  'GST up to the limit (%)': 'வரம்பு வரை GST (%)',
  'GST above the limit (%)': 'வரம்புக்கு மேல் GST (%)',
  'Bookings': 'முன்பதிவுகள்',
  'Allow more bookings than rooms': 'அறைகளை விட அதிக முன்பதிவுகளை அனுமதி',
  'Off is safer: the system refuses a booking when no room of that type is free.': 'அணைத்து வைப்பது பாதுகாப்பானது: அந்த வகை அறை காலியாக இல்லாதபோது அமைப்பு முன்பதிவை மறுக்கும்.',
  'You do not have access to hotel set-up.': 'ஹோட்டல் அமைப்புக்கு உங்களுக்கு அனுமதி இல்லை.',
  'Rack rate {value}': 'ரேக் விலை {value}',
