  'Give the room type a name': 'அறை வகைக்குப் பெயர் கொடுங்கள்',
  'Enter the rack rate for a night (before GST)': 'ஒரு இரவுக்கான ரேக் விலையை உள்ளிடவும் (ஜிஎஸ்டிக்கு முன்)',
  'Extra charges are amounts in rupees': 'கூடுதல் கட்டணங்கள் ரூபாயில் தொகைகள்',
  'People are whole numbers (at least 1 adult)': 'நபர்கள் முழு எண்கள் (குறைந்தது 1 பெரியவர்)',
  'Most adults cannot be fewer than the adults the rate includes': 'அதிகபட்ச பெரியவர்கள் விலையில் உள்ளடங்கிய பெரியவர்களை விடக் குறையக்கூடாது',
  'floor {n}': 'தளம் {n}',
  'Choose the room type': 'அறை வகையைத் தேர்ந்தெடுக்கவும்',
  'First and last number are whole numbers': 'முதல் மற்றும் கடைசி எண் முழு எண்கள்',
  'The last number cannot be before the first': 'கடைசி எண் முதல் எண்ணுக்கு முன் இருக்கக்கூடாது',
  'Add up to 200 rooms at a time': 'ஒரு நேரத்தில் 200 அறைகள் வரை சேர்க்கலாம்',
  '1 room added': '1 அறை சேர்க்கப்பட்டது',
  '{n} rooms added': '{n} அறைகள் சேர்க்கப்பட்டன',
  '(the rest already existed)': '(மீதமுள்ளவை ஏற்கனவே இருந்தன)',
  'Give the room a number': 'அறைக்கு ஒரு எண் கொடுங்கள்',
  'Room only': 'அறை மட்டும்',
  'Breakfast and one meal': 'காலை உணவும் ஒரு வேளை உணவும்',
  'All meals': 'அனைத்து உணவுகளும்',
  'Rate a night for each room type (before GST)': 'ஒவ்வொரு அறை வகைக்கும் ஓர் இரவுக்கான விலை (ஜிஎஸ்டிக்கு முன்)',
  'Rates are amounts in rupees': 'விலைகள் ரூபாயில் தொகைகள்',
  'Seasonal rate': 'பருவகால விலை',
  'Dates are written like 2026-11-01': 'தேதியை இப்படி எழுதவும்: 2026-11-01',
  'The last date cannot be before the first': 'கடைசி தேதி முதல் தேதிக்கு முன் இருக்கக்கூடாது',
  'Enter the rate for a night (before GST)': 'ஓர் இரவுக்கான விலையை உள்ளிடவும் (ஜிஎஸ்டிக்கு முன்)',
  'Take a room off the calendar for repairs, painting or owner use. For a room that is out of order right now, use the front desk.': 'பழுது, வண்ணம் பூசுதல் அல்லது உரிமையாளர் பயன்பாட்டுக்காக அறையை நாள்காட்டியிலிருந்து எடுக்கவும். இப்போது செயல்படாத அறைக்கு முன்பதிவு மேசையைப் பயன்படுத்தவும்.',
  'Put room {room} back on sale?': 'அறை {room} மீண்டும் விற்பனைக்கு வைக்கவா?',
  'Room taken out of sale': 'அறை விற்பனையிலிருந்து எடுக்கப்பட்டது',
  'Choose the room': 'அறையைத் தேர்ந்தெடுக்கவும்',
  'The room must be back on sale after the first night': 'முதல் இரவுக்குப் பிறகு அறை மீண்டும் விற்பனைக்கு வர வேண்டும்',
  '{n} seated': '{n} அமர்ந்து',
  '{n} standing': '{n} நின்று',
  'rent {value}': 'வாடகை {value}',
  'Give the hall a name': 'மண்டபத்துக்குப் பெயர் கொடுங்கள்',
  'Capacity is a whole number of people': 'கொள்ளளவு நபர்களின் முழு எண்',
  'Rent is an amount in rupees': 'வாடகை ரூபாயில் தொகை',
  'It cannot be removed while events are booked in it.': 'இதில் நிகழ்வுகள் பதிவாகியிருக்கும் வரை நீக்க முடியாது.',
  'Vegetarian': 'சைவம்',
  'Non-vegetarian': 'அசைவம்',
  'Jain': 'ஜைனம்',
  'Veg and non-veg': 'சைவமும் அசைவமும்',
  '{value} a plate': 'ஒரு தட்டுக்கு {value}',
  'from {n} guests': '{n} விருந்தினர்கள் முதல்',
  'Events already booked keep their price.': 'ஏற்கனவே பதிவான நிகழ்வுகள் தங்கள் விலையை வைத்திருக்கும்.',
  'Give the package a name': 'தொகுப்புக்குப் பெயர் கொடுங்கள்',
  'Enter the price a plate (before GST)': 'ஒரு தட்டின் விலையை உள்ளிடவும் (ஜிஎஸ்டிக்கு முன்)',
  'Fewest guests is a whole number': 'குறைந்தபட்ச விருந்தினர்கள் முழு எண்',
  'GST is a percentage from 0 to 100': 'ஜிஎஸ்டி 0 முதல் 100 வரையிலான சதவீதம்',
  'Room tariff is taxed by the rate charged for the night. Check the rates and the limit with your accountant; the law has changed more than once.': 'அறை வாடகைக்கு வரி அந்த இரவுக்கு வசூலித்த விலையின்படி விதிக்கப்படுகிறது. விகிதங்களையும் வரம்பையும் உங்கள் கணக்காளருடன் சரிபாருங்கள்; சட்டம் பலமுறை மாறியுள்ளது.',
  'Times are written like 12:00': 'நேரத்தை இப்படி எழுதவும்: 12:00',
  'The booking prefix is 1 to 8 letters or digits': 'முன்பதிவு முன்னொட்டு 1 முதல் 8 எழுத்துகள் அல்லது எண்கள்',
  'The limit a night is an amount in rupees': 'ஓர் இரவுக்கான வரம்பு ரூபாயில் தொகை',
  'The date is written like 2026-11-01': 'தேதியை இப்படி எழுதவும்: 2026-11-01',
  'Rooms, rates, banquet and the property\'s rules': 'அறைகள், விலைகள், விருந்து மண்டபம், சொத்தின் விதிகள்',
  // Gaming set-up
  'Zones': 'மண்டலங்கள்',
  'Stations': 'நிலையங்கள்',
  'Hour packs': 'மணிநேர பேக்குகள்',
  'Games': 'விளையாட்டுகள்',
  'Kind': 'வகை',
  'Zone': 'மண்டலம்',
  'Players': 'வீரர்கள்',
