  'Give the offer a name': 'சலுகைக்குப் பெயர் கொடுங்கள்',
  'Hours must be more than zero': 'மணி நேரம் பூஜ்ஜியத்தை விட அதிகமாக இருக்க வேண்டும்',
  'Players covered is a whole number from 1 to 20': 'உள்ளடக்கிய வீரர்கள் 1 முதல் 20 வரையிலான முழு எண்',
