  'A beat is a salesperson\'s route on one day: the shops to visit, in order.': 'பீட் என்பது ஒரு நாளில் விற்பனையாளர் செல்லும் வழித்தடம்: செல்ல வேண்டிய கடைகள், வரிசையாக.',
  'No beats yet.': 'இன்னும் பீட்கள் இல்லை.',
  'Monday, Ameerpet': 'திங்கள், அமீர்பேட்',
  'No area': 'பகுதி இல்லை',
  'The shops on a beat, and their order, are set on the web. A beat you edit here keeps its shops.': 'பீட்டில் உள்ள கடைகளும் அவற்றின் வரிசையும் வலையில் அமைக்கப்படுகின்றன. இங்கே திருத்தும் பீட் தன் கடைகளை வைத்திருக்கும்.',
  'Vans': 'வேன்கள்',
  'The vans that carry stock to your shops': 'உங்கள் கடைகளுக்குச் சரக்கை எடுத்துச் செல்லும் வேன்கள்',
