  'Add the vans that carry stock to your shops.': 'உங்கள் கடைகளுக்குச் சரக்கை எடுத்துச் செல்லும் வேன்களைச் சேர்க்கவும்.',
  'Capacity (kg)': 'கொள்ளளவு (கிலோ)',
