  'Loading a van and counting it at the end of the day is done on the web.': 'வேனில் சரக்கு ஏற்றுவதும் நாளின் முடிவில் எண்ணுவதும் வலையில் செய்யப்படுகிறது.',
  'Give the principal a name': 'பிரின்சிபலுக்குப் பெயர் கொடுங்கள்',
