  'Make an offer: buy 10 cartons, get 1 free; 5% off 100 units; ₹2,000 off an order above ₹50,000.': 'ஒரு சலுகையை உருவாக்குங்கள்: 10 அட்டைப்பெட்டி வாங்கினால் 1 இலவசம்; 100 எண்ணிக்கைக்கு 5% தள்ளுபடி; ₹50,000-க்கு மேல் ஆர்டருக்கு ₹2,000 தள்ளுபடி.',
  'Tell qualifying shops?': 'தகுதியான கடைகளுக்குத் தெரிவிக்கவா?',
