  'Tell the shops': 'கடைகளுக்குத் தெரிவிக்கவும்',
  'A scheme that orders have used can only be switched off.': 'ஆர்டர்கள் பயன்படுத்திய திட்டத்தை அணைக்க மட்டுமே முடியும்.',
  'Name or barcode': 'பெயர் அல்லது பார்கோடு',
  'Leave empty to give the same product free.': 'அதே பொருளை இலவசமாகத் தர காலியாக விடவும்.',
  'Choose a free product, as this scheme is not for one product.': 'இந்தத் திட்டம் ஒரு பொருளுக்கானது அல்ல என்பதால் இலவசப் பொருளைத் தேர்ந்தெடுக்கவும்.',
