  'Only named shops and territories are set on the web. A scheme you edit here keeps the ones it has.': 'பெயர் குறிப்பிட்ட கடைகளும் மண்டலங்களும் வலையில் அமைக்கப்படுகின்றன. இங்கே திருத்தும் திட்டம் தன்னிடம் உள்ளவற்றை வைத்திருக்கும்.',
  'Sales team': 'விற்பனைக் குழு',
  'Your salespeople, their targets and what they earn': 'உங்கள் விற்பனையாளர்கள், அவர்களின் இலக்குகள் மற்றும் அவர்கள் ஈட்டுவது',
