  'Leave as it is, or choose': 'அப்படியே விடவும், அல்லது தேர்ந்தெடுக்கவும்',
  'As it is': 'அப்படியே',
  'Linking a sign-in account is done on the web.': 'உள்நுழைவுக் கணக்கை இணைப்பது வலையில் செய்யப்படுகிறது.',
  'Targets running today. Setting one again for the same period changes it; it never adds a second.': 'இன்று நடப்பில் உள்ள இலக்குகள். அதே காலத்துக்கு மீண்டும் அமைத்தால் அது மாறும்; இரண்டாவது சேராது.',
  'Set a monthly target for each salesperson, territory or brand to track how far they are.': 'ஒவ்வொரு விற்பனையாளர், மண்டலம் அல்லது பிராண்டுக்கும் மாத இலக்கை அமைத்து அவர்கள் எவ்வளவு தூரம் வந்துள்ளனர் எனப் பாருங்கள்.',
  'Target saved': 'இலக்கு சேமிக்கப்பட்டது',
