  'Download a copy of all your records (customers, products, bills, payments, expenses and stock) as a ZIP of CSV files, then save or send it from the share sheet. Keep it somewhere safe. FlowXP does not restore from it by itself: ask support if you ever need your data put back.': 'আপনার সব রেকর্ডের (গ্রাহক, পণ্য, বিল, পেমেন্ট, খরচ ও স্টক) একটি কপি CSV ফাইলের ZIP হিসেবে ডাউনলোড করুন, তারপর শেয়ার শিট থেকে সংরক্ষণ বা পাঠান। নিরাপদে রাখুন। FlowXP এটি থেকে নিজে পুনরুদ্ধার করে না: ডেটা ফিরে পেতে সাপোর্টকে বলুন।',
