  'When a customer\'s next visit earns their free item (at most once a week).': 'গ্রাহকের পরের ভিজিটে বিনামূল্যে আইটেম মিললে (সপ্তাহে সর্বোচ্চ একবার)।',
  'Offers and reminders only go to customers who have not opted out. Bills and booking messages are service messages and are sent regardless.': 'অফার ও রিমাইন্ডার শুধু তাদের কাছে যায় যাঁরা অপ্ট-আউট করেননি। বিল ও বুকিং বার্তা সেবামূলক বার্তা, তাই সবসময় পাঠানো হয়।',
  'Show the WhatsApp templates to create in Meta': 'Meta-তে তৈরি করার হোয়াটসঅ্যাপ টেমপ্লেট দেখান',
