  'WhatsApp only lets a business start a chat with pre-approved templates. Create each one once in Meta Business Manager (category: Utility for bills and bookings, Marketing for offers), using exactly this name and text.': 'হোয়াটসঅ্যাপ শুধু আগে থেকে অনুমোদিত টেমপ্লেট দিয়ে ব্যবসাকে চ্যাট শুরু করতে দেয়। প্রতিটি Meta Business Manager-এ একবার তৈরি করুন (ক্যাটাগরি: বিল ও বুকিংয়ের জন্য Utility, অফারের জন্য Marketing), ঠিক এই নাম ও লেখা দিয়ে।',
