  // Printers
  'Bluetooth and Wi-Fi printers: receipt and kitchen ticket': 'ব্লুটুথ ও ওয়াই-ফাই প্রিন্টার: রসিদ ও কিচেন টিকিট',
  'Connect a Bluetooth or Wi-Fi thermal printer, and choose what each one prints.': 'ব্লুটুথ বা ওয়াই-ফাই থার্মাল প্রিন্টার যুক্ত করুন এবং প্রতিটি কী ছাপবে তা বেছে নিন।',
  'Printing straight to a printer needs the FlowXP development app. In the Expo Go test copy, use the phone print screen or RawBT in Settings.': 'সরাসরি প্রিন্টারে ছাপতে FlowXP ডেভেলপমেন্ট অ্যাপ লাগবে। Expo Go টেস্ট কপিতে সেটিংসে ফোন প্রিন্ট স্ক্রিন বা RawBT ব্যবহার করুন।',
  'No printers yet.': 'এখনো কোনো প্রিন্টার নেই।',
  'Add a Bluetooth printer': 'ব্লুটুথ প্রিন্টার যোগ করুন',
  'Add a Wi-Fi printer': 'ওয়াই-ফাই প্রিন্টার যোগ করুন',
  'Paired Bluetooth printers': 'জোড়া লাগানো ব্লুটুথ প্রিন্টার',
