  'The bill the customer takes.': 'গ্রাহক যে বিল নিয়ে যান।',
  'Kitchen ticket': 'কিচেন টিকিট',
  'What the kitchen makes, printed when an order is sent to it.': 'কিচেন কী বানাবে, অর্ডার পাঠালে ছাপা হয়।',
  'Print a test': 'টেস্ট ছাপুন',
  'Test sent. If nothing printed, check the printer is on, in range, and has paper.': 'টেস্ট পাঠানো হয়েছে। কিছু না ছাপলে প্রিন্টার চালু, কাছে এবং কাগজ আছে কি না দেখুন।',
  'Could not print.': 'ছাপা যায়নি।',
  'Enter the printer\'s address on your network, like 192.168.1.50': 'আপনার নেটওয়ার্কে প্রিন্টারের ঠিকানা লিখুন, যেমন 192.168.1.50',
  'That address does not look right. It is numbers with dots, like 192.168.1.50': 'ঠিকানাটি ঠিক মনে হচ্ছে না। এটি ডট সহ সংখ্যা, যেমন 192.168.1.50',
  'The port is a number from 1 to 65535 (most printers use 9100)': 'পোর্ট 1 থেকে 65535-এর মধ্যে একটি সংখ্যা (বেশিরভাগ প্রিন্টার 9100 ব্যবহার করে)',
  'Allow FlowXP to use Bluetooth (nearby devices) in the phone settings, then try again.': 'ফোন সেটিংসে FlowXP-কে ব্লুটুথ (কাছের ডিভাইস) ব্যবহারের অনুমতি দিন, তারপর আবার চেষ্টা করুন।',
  'Switch Bluetooth on, then try again.': 'ব্লুটুথ চালু করুন, তারপর আবার চেষ্টা করুন।',
