  'FlowXP cannot know what your card machine or delivery platform charges. Enter your real rates; anything left at 0 is not deducted.': 'আপনার কার্ড মেশিন বা ডেলিভারি প্ল্যাটফর্ম কত নেয় তা FlowXP জানতে পারে না। আপনার আসল হার লিখুন; 0 রাখলে তা বাদ যায় না।',
