  'Net revenue is what was billed before tax, minus discounts and refunds. Cancelled invoices are left out. Food cost is the ingredient cost recorded on each bill when it was made. Fees, commission and packaging use your assumptions: unset means zero. Contribution is what each sale leaves toward rent, salaries and other fixed costs.': 'নিট রাজস্ব হলো করের আগে বিল করা অঙ্ক, ছাড় ও ফেরত বাদ দিয়ে। বাতিল ইনভয়েস বাদ যায়। খাবারের খরচ হলো প্রতিটি বিল তৈরির সময় রেকর্ড করা উপকরণ খরচ। ফি, কমিশন ও প্যাকেজিং আপনার অনুমান ব্যবহার করে: ঠিক না করলে শূন্য। অবদান হলো ভাড়া, বেতন ও অন্যান্য স্থায়ী খরচের জন্য প্রতিটি বিক্রি যা রাখে।',
