  'Printed on the Tally-style invoice. Blank buyer fields use the customer\'s record; a blank consignee means the same as the buyer.': 'టాలీ తరహా ఇన్వాయిస్‌పై ముద్రిస్తుంది. ఖాళీ కొనుగోలుదారు ఫీల్డ్‌లకు కస్టమర్ రికార్డు వాడతారు; ఖాళీ సరుకు స్వీకర్త అంటే కొనుగోలుదారే.',
