  'How this phone shows the app. It stays on this phone and changes nothing on your bills or reports.': 'ఈ ఫోన్ యాప్‌ను ఎలా చూపిస్తుందో. ఇది ఈ ఫోన్‌లోనే ఉంటుంది, మీ బిల్లులు లేదా నివేదికలలో ఏమీ మార్చదు.',
  'Receipts and shared bills always show the exact amount.': 'రసీదులు, షేర్ చేసిన బిల్లులు ఎల్లప్పుడూ ఖచ్చితమైన మొత్తాన్ని చూపుతాయి.',
  'Download a copy of all your records (customers, products, bills, payments, expenses and stock) as a ZIP of CSV files, then save or send it from the share sheet. Keep it somewhere safe. FlowXP does not restore from it by itself: ask support if you ever need your data put back.': 'మీ అన్ని రికార్డుల (కస్టమర్లు, ప్రోడక్ట్‌లు, బిల్లులు, చెల్లింపులు, ఖర్చులు, స్టాక్) కాపీని CSV ఫైళ్ల ZIPగా డౌన్‌లోడ్ చేసి, షేర్ షీట్ నుండి సేవ్ చేయండి లేదా పంపండి. భద్రంగా ఉంచండి. FlowXP దీని నుండి తానే పునరుద్ధరించదు: డేటా తిరిగి కావాలంటే సపోర్ట్‌ను అడగండి.',
  'Could not take the backup.': 'బ్యాకప్ తీసుకోలేకపోయాం.',
  'Could not take the backup. Only the owner can, and the phone needs a connection.': 'బ్యాకప్ తీసుకోలేకపోయాం. యజమాని మాత్రమే తీసుకోగలరు, ఫోన్‌కు కనెక్షన్ ఉండాలి.',
  'This phone cannot share files from FlowXP.': 'ఈ ఫోన్ FlowXP నుండి ఫైళ్లను షేర్ చేయలేదు.',
