  'A customer is their mobile number. Every day they are billed counts as one visit, at any outlet. On the visit that earns it, the free item comes off the bill once it is on the order (the till offers to add it).': 'కస్టమర్ అంటే వారి మొబైల్ నంబర్. బిల్లు చేసే ప్రతి రోజు ఒక సందర్శనగా లెక్కించబడుతుంది, ఏ అవుట్‌లెట్‌లోనైనా. బహుమతి వచ్చే సందర్శనలో, ఉచిత ఐటమ్ ఆర్డర్‌లో చేరాక బిల్లు నుండి తగ్గుతుంది (టిల్ దాన్ని జోడించమని సూచిస్తుంది).',
