  'No coupons yet. Create one and give the code to a customer; the cashier enters it at billing.': 'ఇంకా కూపన్లు లేవు. ఒకటి సృష్టించి కోడ్‌ను కస్టమర్‌కు ఇవ్వండి; క్యాషియర్ బిల్లింగ్‌లో నమోదు చేస్తారు.',
  'Code must be 3 to 24 letters, numbers, - or _': 'కోడ్ 3 నుండి 24 అక్షరాలు, అంకెలు, - లేదా _ అయి ఉండాలి',
  'Enter how much the coupon takes off': 'కూపన్ ఎంత తగ్గిస్తుందో నమోదు చేయండి',
  'A percentage can’t be more than 100': 'శాతం 100 కంటే ఎక్కువ ఉండకూడదు',
  'Amounts must be numbers': 'మొత్తాలు సంఖ్యలు అయి ఉండాలి',
  'Uses must be a whole number above zero': 'వినియోగాలు సున్నా కంటే ఎక్కువ పూర్ణ సంఖ్య అయి ఉండాలి',
  'The end date is before the start date': 'ముగింపు తేదీ ప్రారంభ తేదీ కంటే ముందు ఉంది',
  // Offers search
  'Search by name or barcode, then tap to add': 'పేరు లేదా బార్‌కోడ్‌తో వెతకండి, ఆపై జోడించడానికి నొక్కండి',
  // Messaging
  'Messaging': 'మెసేజింగ్',
  'Counting…': 'లెక్కిస్తున్నారు…',
