  'Send messages by': 'సందేశాలు పంపే మార్గం',
  'Off: send nothing': 'ఆఫ్: ఏదీ పంపవద్దు',
  'WhatsApp': 'వాట్సాప్',
  'SMS': 'SMS',
  'Connected: {name}': 'కనెక్ట్ అయింది: {name}',
  'No messaging service is connected on the server yet, so messages are only recorded as skipped. Ask whoever runs the server to set it up.': 'సర్వర్‌లో ఇంకా మెసేజింగ్ సేవ కనెక్ట్ కాలేదు, కాబట్టి సందేశాలు "దాటవేయబడినవి"గా మాత్రమే నమోదవుతాయి. సర్వర్ నడిపేవారిని దీన్ని సెటప్ చేయమని అడగండి.',
  'Send the bill to customers with a mobile number': 'మొబైల్ నంబర్ ఉన్న కస్టమర్లకు బిల్లు పంపండి',
  'After every sale to a customer, with a link to view the bill.': 'కస్టమర్‌కు ప్రతి అమ్మకం తర్వాత, బిల్లు చూడటానికి లింక్‌తో.',
