  'Waitlist updates': 'వెయిట్‌లిస్ట్ అప్‌డేట్‌లు',
  'When someone joins the waitlist and when their table is ready.': 'ఎవరైనా వెయిట్‌లిస్ట్‌లో చేరినప్పుడు మరియు వారి టేబుల్ సిద్ధమైనప్పుడు.',
  'Loyalty reminder': 'లాయల్టీ రిమైండర్',
  'When a customer\'s next visit earns their free item (at most once a week).': 'కస్టమర్ తదుపరి సందర్శనలో ఉచిత ఐటమ్ వచ్చినప్పుడు (వారానికి గరిష్ఠంగా ఒకసారి).',
  'Offers and reminders only go to customers who have not opted out. Bills and booking messages are service messages and are sent regardless.': 'ఆఫర్లు మరియు రిమైండర్లు వద్దని చెప్పని కస్టమర్లకు మాత్రమే వెళ్తాయి. బిల్లు, బుకింగ్ సందేశాలు సేవా సందేశాలు, అవి ఎలాగైనా పంపబడతాయి.',
  'Show the WhatsApp templates to create in Meta': 'Metaలో సృష్టించాల్సిన వాట్సాప్ టెంప్లేట్లను చూపండి',
  'Hide the WhatsApp templates': 'వాట్సాప్ టెంప్లేట్లను దాచండి',
  'WhatsApp only lets a business start a chat with pre-approved templates. Create each one once in Meta Business Manager (category: Utility for bills and bookings, Marketing for offers), using exactly this name and text.': 'ముందే ఆమోదించిన టెంప్లేట్‌లతో మాత్రమే వాట్సాప్ వ్యాపారాన్ని చాట్ మొదలుపెట్టనిస్తుంది. ప్రతి ఒక్కటి Meta Business Managerలో ఒకసారి సృష్టించండి (వర్గం: బిల్లులు, బుకింగ్‌లకు Utility, ఆఫర్లకు Marketing), సరిగ్గా ఇదే పేరు మరియు పాఠంతో.',
  'Marketing': 'మార్కెటింగ్',
