  // Printers
  'Bluetooth and Wi-Fi printers: receipt and kitchen ticket': 'బ్లూటూత్, వై-ఫై ప్రింటర్లు: రసీదు మరియు కిచెన్ టికెట్',
  'Connect a Bluetooth or Wi-Fi thermal printer, and choose what each one prints.': 'బ్లూటూత్ లేదా వై-ఫై థర్మల్ ప్రింటర్‌ను కనెక్ట్ చేసి, ప్రతిదీ ఏమి ప్రింట్ చేయాలో ఎంచుకోండి.',
  'Printing straight to a printer needs the FlowXP development app. In the Expo Go test copy, use the phone print screen or RawBT in Settings.': 'ప్రింటర్‌కు నేరుగా ప్రింట్ చేయడానికి FlowXP డెవలప్‌మెంట్ యాప్ కావాలి. Expo Go టెస్ట్ కాపీలో సెట్టింగ్స్‌లో ఫోన్ ప్రింట్ స్క్రీన్ లేదా RawBT వాడండి.',
  'No printers yet.': 'ఇంకా ప్రింటర్లు లేవు.',
  'Add a Bluetooth printer': 'బ్లూటూత్ ప్రింటర్ జోడించండి',
  'Add a Wi-Fi printer': 'వై-ఫై ప్రింటర్ జోడించండి',
  'Paired Bluetooth printers': 'పెయిర్ చేసిన బ్లూటూత్ ప్రింటర్లు',
  'Pair the printer first in the phone\'s Bluetooth settings (the code is usually 0000 or 1234), then come back and pick it here.': 'ముందుగా ఫోన్ బ్లూటూత్ సెట్టింగ్స్‌లో ప్రింటర్‌ను పెయిర్ చేయండి (కోడ్ సాధారణంగా 0000 లేదా 1234), ఆపై ఇక్కడికి వచ్చి ఎంచుకోండి.',
  'Look for printers nearby': 'దగ్గరలోని ప్రింటర్లను వెతకండి',
  'No Bluetooth printers found. Switch the printer on and pair it in the phone\'s Bluetooth settings.': 'బ్లూటూత్ ప్రింటర్లు ఏవీ దొరకలేదు. ప్రింటర్‌ను ఆన్ చేసి ఫోన్ బ్లూటూత్ సెట్టింగ్స్‌లో పెయిర్ చేయండి.',
  'Address on the network': 'నెట్‌వర్క్‌లో చిరునామా',
  'Port': 'పోర్ట్',
  'Add this printer': 'ఈ ప్రింటర్‌ను జోడించండి',
  '58 mm paper': '58 మి.మీ. కాగితం',
  '80 mm paper': '80 మి.మీ. కాగితం',
  'What it prints': 'ఇది ఏమి ప్రింట్ చేస్తుంది',
  'Customer receipt': 'కస్టమర్ రసీదు',
  'The bill the customer takes.': 'కస్టమర్ తీసుకెళ్లే బిల్లు.',
  'Kitchen ticket': 'కిచెన్ టికెట్',
  'What the kitchen makes, printed when an order is sent to it.': 'కిచెన్ ఏమి తయారు చేయాలి, ఆర్డర్ పంపినప్పుడు ప్రింట్ అవుతుంది.',
  'Print a test': 'టెస్ట్ ప్రింట్ చేయండి',
  'Test sent. If nothing printed, check the printer is on, in range, and has paper.': 'టెస్ట్ పంపబడింది. ఏమీ ప్రింట్ కాకపోతే ప్రింటర్ ఆన్‌లో, దగ్గరలో, కాగితంతో ఉందో చూడండి.',
  'Could not print.': 'ప్రింట్ చేయలేకపోయాం.',
  'Enter the printer\'s address on your network, like 192.168.1.50': 'మీ నెట్‌వర్క్‌లో ప్రింటర్ చిరునామా నమోదు చేయండి, ఉదా. 192.168.1.50',
  'That address does not look right. It is numbers with dots, like 192.168.1.50': 'ఆ చిరునామా సరిగా లేదు. ఇది చుక్కలతో కూడిన సంఖ్యలు, ఉదా. 192.168.1.50',
  'The port is a number from 1 to 65535 (most printers use 9100)': 'పోర్ట్ 1 నుండి 65535 మధ్య సంఖ్య (చాలా ప్రింటర్లు 9100 వాడతాయి)',
  'Allow FlowXP to use Bluetooth (nearby devices) in the phone settings, then try again.': 'ఫోన్ సెట్టింగ్స్‌లో FlowXPకు బ్లూటూత్ (సమీప పరికరాలు) అనుమతి ఇచ్చి, మళ్లీ ప్రయత్నించండి.',
  'Switch Bluetooth on, then try again.': 'బ్లూటూత్ ఆన్ చేసి, మళ్లీ ప్రయత్నించండి.',
  'Could not reach the printer. Check that it is switched on, in range, and paired in the phone\'s Bluetooth settings.': 'ప్రింటర్‌ను చేరుకోలేకపోయాం. అది ఆన్‌లో, దగ్గరలో, ఫోన్ బ్లూటూత్ సెట్టింగ్స్‌లో పెయిర్ అయి ఉందో చూడండి.',
  'Could not reach the printer. Check that it is switched on, on the same Wi-Fi as this phone, and that the address is right.': 'ప్రింటర్‌ను చేరుకోలేకపోయాం. అది ఆన్‌లో, ఈ ఫోన్ వై-ఫైలోనే ఉందో, చిరునామా సరైనదో చూడండి.',
  'You can keep up to {n} printers.': 'మీరు గరిష్ఠంగా {n} ప్రింటర్లు ఉంచుకోవచ్చు.',
  'Straight to my printers': 'నా ప్రింటర్లకు నేరుగా',
  'Phone print screen': 'ఫోన్ ప్రింట్ స్క్రీన్',
  'Through RawBT': 'RawBT ద్వారా',
  'Kitchen ticket sent to the printer.': 'కిచెన్ టికెట్ ప్రింటర్‌కు పంపబడింది.',
  'Could not print the kitchen ticket. The order was still sent to the kitchen.': 'కిచెన్ టికెట్ ప్రింట్ చేయలేకపోయాం. ఆర్డర్ మాత్రం కిచెన్‌కు పంపబడింది.',
