  'No items sold in this period.': 'ఈ కాలంలో ఏ ఐటమ్ అమ్మబడలేదు.',
  'FlowXP cannot know what your card machine or delivery platform charges. Enter your real rates; anything left at 0 is not deducted.': 'మీ కార్డ్ మెషిన్ లేదా డెలివరీ ప్లాట్‌ఫామ్ ఎంత వసూలు చేస్తుందో FlowXPకి తెలియదు. మీ అసలు రేట్లు నమోదు చేయండి; 0 గా వదిలినది తగ్గించబడదు.',
  'Payment fees (% of amount collected)': 'చెల్లింపు ఫీజులు (వసూలు చేసిన మొత్తంలో %)',
