  'A rate is a percentage from 0 to 100': 'రేటు 0 నుండి 100 వరకు శాతం',
  'Packaging must be an amount in rupees': 'ప్యాకేజింగ్ రూపాయల్లో ఒక మొత్తం అయి ఉండాలి',
  'Net revenue is what was billed before tax, minus discounts and refunds. Cancelled invoices are left out. Food cost is the ingredient cost recorded on each bill when it was made. Fees, commission and packaging use your assumptions: unset means zero. Contribution is what each sale leaves toward rent, salaries and other fixed costs.': 'నికర ఆదాయం అంటే పన్నుకు ముందు బిల్ చేసినది, తగ్గింపులు మరియు రీఫండ్‌లు తీసివేసి. రద్దైన ఇన్‌వాయిస్‌లు వదిలేస్తారు. ఆహార ఖర్చు అంటే ప్రతి బిల్లు చేసినప్పుడు నమోదైన పదార్థాల ఖర్చు. ఫీజులు, కమీషన్, ప్యాకేజింగ్ మీ అంచనాలను వాడతాయి: సెట్ చేయకపోతే సున్నా. అద్దె, జీతాలు, ఇతర స్థిర ఖర్చుల కోసం ప్రతి అమ్మకం మిగిల్చేది కాంట్రిబ్యూషన్.',
  'What to expect, and what to have in the kitchen for it.': 'ఏమి ఆశించాలి, దాని కోసం వంటగదిలో ఏమి ఉండాలి.',
