  'Every way in follows these: the desk, the member\'s phone and the gates.': 'లోపలికి రావడానికి ప్రతి మార్గం వీటిని అనుసరిస్తుంది: డెస్క్, సభ్యుని ఫోన్ మరియు గేట్లు.',
  'Grace days after a membership ends': 'సభ్యత్వం ముగిసిన తర్వాత గ్రేస్ రోజులు',
  'Ignore a repeat scan for (seconds)': 'పునరావృత స్కాన్‌ను ఇంతసేపు విస్మరించండి (సెకన్లు)',
  'Same card at two branches within (minutes)': 'ఒకే కార్డ్ రెండు శాఖల్లో ఇన్ని నిమిషాల్లోపు',
  'Record check-out as well as check-in': 'చెక్-ఇన్‌తో పాటు చెక్-అవుట్‌ను కూడా నమోదు చేయండి',
  'Shows who is in the gym now.': 'ఇప్పుడు జిమ్‌లో ఎవరున్నారో చూపుతుంది.',
  'The desk confirms every scan by looking at the member': 'డెస్క్ సభ్యుని చూసి ప్రతి స్కాన్‌ను నిర్ధారిస్తుంది',
  'Members on their own phone': 'సభ్యులు తమ ఫోన్‌లో',
  'A member signs in with a code sent to their phone, then shows a pass or checks in themselves. No app to install.': 'సభ్యుడు ఫోన్‌కు పంపిన కోడ్‌తో సైన్ ఇన్ చేసి, పాస్ చూపిస్తారు లేదా స్వయంగా చెక్-ఇన్ చేస్తారు. యాప్ ఇన్‌స్టాల్ చేయనవసరం లేదు.',
  'Let members check in from their own phone': 'సభ్యులు తమ ఫోన్ నుండి చెక్-ఇన్ చేయనివ్వండి',
  'They scan the poster at the door with their phone\'s camera.': 'వారు తమ ఫోన్ కెమెరాతో తలుపు వద్ద పోస్టర్‌ను స్కాన్ చేస్తారు.',
  'Also ask for today\'s front-desk code': 'ఈ రోజు ఫ్రంట్-డెస్క్ కోడ్ కూడా అడగండి',
  'Ask for a fresh sign-in code every time': 'ప్రతిసారీ కొత్త సైన్-ఇన్ కోడ్ అడగండి',
  'A code counts for (minutes)': 'ఒక కోడ్ ఎంతసేపు చెల్లుతుంది (నిమిషాలు)',
  'The gym\'s web address': 'జిమ్ వెబ్ చిరునామా',
  'Letters, digits and hyphens. Needed for members to sign in.': 'అక్షరాలు, అంకెలు మరియు హైఫన్లు. సభ్యులు సైన్ ఇన్ చేయడానికి అవసరం.',
  'Member number starts with': 'సభ్యుని నంబర్ దీనితో ప్రారంభమవుతుంది',
