  'A phone pass QR lasts (seconds)': 'ఫోన్ పాస్ QR ఎంతసేపు ఉంటుంది (సెకన్లు)',
  'Classes': 'క్లాస్‌లు',
  'How booking works for members and the desk.': 'సభ్యులు మరియు డెస్క్ కోసం బుకింగ్ ఎలా పనిచేస్తుంది.',
  'Cancel a class free until (hours before)': 'క్లాస్‌ను ఉచితంగా రద్దు చేయవచ్చు, ఇన్ని గంటల ముందు వరకు',
  'Cancel personal training free until (hours before)': 'పర్సనల్ ట్రైనింగ్‌ను ఉచితంగా రద్దు చేయవచ్చు, ఇన్ని గంటల ముందు వరకు',
  'Members can book up to (days ahead)': 'సభ్యులు ఇన్ని రోజుల ముందు వరకు బుక్ చేయవచ్చు',
  'A full class has a waitlist': 'నిండిన క్లాస్‌కు వెయిట్‌లిస్ట్ ఉంటుంది',
  'Save settings': 'సెట్టింగ్‌లను సేవ్ చేయండి',
  'Opening hours': 'ప్రారంభ వేళలు',
