  'Entrance QR': 'ప్రవేశ QR',
  'Put this poster at the door. It only opens the check-in page for this branch.': 'ఈ పోస్టర్‌ను తలుపు వద్ద ఉంచండి. ఇది ఈ శాఖ చెక్-ఇన్ పేజీని మాత్రమే తెరుస్తుంది.',
  'Check in here': 'ఇక్కడ చెక్-ఇన్ చేయండి',
  'Scan with your phone\'s camera. Sign in with the code we send you, then tap Check in.': 'మీ ఫోన్ కెమెరాతో స్కాన్ చేయండి. మేము పంపే కోడ్‌తో సైన్ ఇన్ చేసి, ఆపై చెక్-ఇన్ నొక్కండి.',
  'New QR': 'కొత్త QR',
  'Make a new entrance QR?': 'కొత్త ప్రవేశ QR తయారు చేయాలా?',
  'The poster on the wall stops working. Print the new one and put it up. Use this if the old poster was copied or spread around.': 'గోడపై ఉన్న పోస్టర్ పనిచేయడం ఆగిపోతుంది. కొత్తది ప్రింట్ చేసి అతికించండి. పాత పోస్టర్ కాపీ అయినా లేదా వ్యాపించినా దీన్ని వాడండి.',
  'Make a new QR': 'కొత్త QR తయారు చేయండి',
