  'Online bookings arrive as Booked appointments marked Online. One mobile number can hold up to three upcoming online bookings.': 'ఆన్‌లైన్ బుకింగ్‌లు ఆన్‌లైన్ అని గుర్తించిన బుక్డ్ అపాయింట్‌మెంట్లుగా వస్తాయి. ఒక మొబైల్ నంబర్‌కు గరిష్ఠంగా మూడు రాబోయే ఆన్‌లైన్ బుకింగ్‌లు ఉండవచ్చు.',
