  'How long points last. Empty means they never expire.': 'పాయింట్లు ఎంతకాలం ఉంటాయి. ఖాళీ అంటే ఎప్పటికీ గడువు ముగియదు.',
  'Points expire on their own once a day. Clients are warned first if the Loyalty points expiry message is on under Messages.': 'పాయింట్లు రోజుకు ఒకసారి వాటంతట అవే గడువు ముగుస్తాయి. సందేశాల కింద లాయల్టీ పాయింట్ల గడువు సందేశం ఆన్‌లో ఉంటే క్లయింట్లను ముందుగా హెచ్చరిస్తారు.',
  'Expire old points now': 'పాత పాయింట్లను ఇప్పుడే గడువు ముగించండి',
  'Expire old points now?': 'పాత పాయింట్లను ఇప్పుడే గడువు ముగించాలా?',
