  '{n} records were added.': '{n} రికార్డులు జోడించారు.',
  '{n} records would be added.': '{n} రికార్డులు జోడించబడతాయి.',
  'Restore from a backup': 'బ్యాకప్ నుండి పునరుద్ధరించండి',
  'Choose the backup file': 'బ్యాకప్ ఫైల్‌ను ఎంచుకోండి',
  'Check what would be added': 'ఏమి జోడించబడుతుందో చూడండి',
  'Restore what is missing': 'లేనిదాన్ని పునరుద్ధరించండి',
  'This is only a check. Nothing has been changed yet.': 'ఇది కేవలం తనిఖీ మాత్రమే. ఇంకా ఏదీ మార్చలేదు.',
  'Restored bills do not change the shelf. If goods were lost, count your stock.': 'తిరిగి తెచ్చిన బిల్లులు షెల్ఫ్ స్టాక్‌ను మార్చవు. సరుకు పోయి ఉంటే స్టాక్ లెక్కించండి.',
  'Restored': 'పునరుద్ధరించబడింది',
  'Choose the ZIP file you downloaded from FlowXP': 'FlowXP నుండి డౌన్‌లోడ్ చేసిన ZIP ఫైల్‌ను ఎంచుకోండి',
  'That file is too large to restore here': 'ఆ ఫైల్ ఇక్కడ పునరుద్ధరించడానికి చాలా పెద్దది',
  '{n} added': '{n} జోడించారు',
  '{n} to add': '{n} జోడించబడతాయి',
  '{n} already here': '{n} ఇప్పటికే ఇక్కడ',
  '{n} skipped': '{n} వదిలేశారు',
  'row {n}': 'అడ్డు వరుస {n}',
  'Put back what a backup has and this business does not': 'బ్యాకప్‌లో ఉండి ఈ వ్యాపారంలో లేనిదాన్ని పునరుద్ధరించండి',
  'Only the owner can restore from a backup.': 'యజమాని మాత్రమే బ్యాకప్ నుండి పునరుద్ధరించగలరు.',
  'Choose the ZIP file you downloaded before. Restoring only adds what is missing. Nothing that is already in FlowXP is changed or removed, so it is safe to run twice.': 'ఇంతకు ముందు డౌన్‌లోడ్ చేసిన ZIP ఫైల్‌ను ఎంచుకోండి. పునరుద్ధరణ లేనివాటిని మాత్రమే జోడిస్తుంది. FlowXPలో ఇప్పటికే ఉన్నదేదీ మార్చబడదు లేదా తొలగించబడదు, కాబట్టి రెండుసార్లు చేయడం సురక్షితం.',
  'Make the restore?': 'పునరుద్ధరణ చేయాలా?',
  'The records that are missing are added. Nothing else changes.': 'లేని రికార్డులు జోడించబడతాయి. మరేదీ మారదు.',
  // Workshop extras
