  'Add them': 'జోడించండి',
  'Set up my racks in one step': 'ఒకే దశలో నా రాక్‌లను సెటప్ చేయండి',
  'Tell us how many racks and bins you have. We name them for you (R01, R02 ... and bins A, B, C ...). You can change it later.': 'మీకు ఎన్ని రాక్‌లు, బిన్‌లు ఉన్నాయో చెప్పండి. పేర్లు మేము పెడతాం (R01, R02 ... బిన్‌లు A, B, C ...). తర్వాత మార్చవచ్చు.',
