  'How many racks': 'ఎన్ని రాక్‌లు',
  'Bins in each rack': 'ప్రతి రాక్‌లో బిన్‌లు',
  'A bin is one small place on a rack where a part sits.': 'బిన్ అంటే రాక్‌పై ఒక భాగం ఉంచే చిన్న స్థలం.',
  'Create racks and bins': 'రాక్‌లు, బిన్‌లు సృష్టించండి',
  'This makes {racks} racks and {total} bins. The first bin will be called {code}.': 'ఇది {racks} రాక్‌లు, {total} బిన్‌లు సృష్టిస్తుంది. మొదటి బిన్ పేరు {code}.',
  'Import customers': 'కస్టమర్లను దిగుమతి చేయండి',
  'That file has no rows. The first line must be the column names.': 'ఆ ఫైల్‌లో వరుసలు లేవు. మొదటి వరుస నిలువు వరుసల పేర్లు అయి ఉండాలి.',
  'Mechanic mode': 'మెకానిక్ మోడ్',
  'Turn this on if you also service bikes or cars. Turn it off if you only sell parts. You can change it any time, and nothing is deleted.': 'బైక్ లేదా కారు సర్వీసింగ్ కూడా చేస్తే దీన్ని ఆన్ చేయండి. భాగాలు మాత్రమే అమ్మితే ఆఫ్ చేయండి. ఎప్పుడైనా మార్చవచ్చు, ఏదీ తొలగించబడదు.',
  'This shop also does servicing': 'ఈ దుకాణం సర్వీసింగ్ కూడా చేస్తుంది',
  'On: Job cards, labour and services, what the workshop earned, and staff, attendance and payroll appear in the menu.': 'ఆన్: మెనూలో జాబ్ కార్డులు, కూలి మరియు సేవలు, వర్క్‌షాప్ సంపాదన, సిబ్బంది, హాజరు, జీతాలు కనిపిస్తాయి.',
  'Racks, parts, vehicles, receiving, trade accounts and reports stay either way.': 'రాక్‌లు, భాగాలు, వాహనాలు, స్వీకరణ, ట్రేడ్ ఖాతాలు, నివేదికలు ఎలాగైనా ఉంటాయి.',
  'Only the owner can change mechanic mode.': 'యజమాని మాత్రమే మెకానిక్ మోడ్ మార్చగలరు.',
  'Mechanic mode is on': 'మెకానిక్ మోడ్ ఆన్‌లో ఉంది',
  'Mechanic mode is off': 'మెకానిక్ మోడ్ ఆఫ్‌లో ఉంది',
  'Labour and services': 'కూలి మరియు సేవలు',
  'What you charge for work. On a job card each one is a single tap. Adding a name that is already here changes its charge.': 'పనికి మీరు వసూలు చేసేది. జాబ్ కార్డ్‌లో ప్రతిదీ ఒక్క ట్యాప్‌తో చేరుతుంది. ఇక్కడ ఉన్న పేరును మళ్లీ చేర్చితే దాని ఛార్జీ మారుతుంది.',
  'GST % (optional)': 'GST % (ఐచ్ఛికం)',
