  'Starts your list with the common makes and models sold in India. It adds only names. No part is marked as fitting any vehicle. Adding it again adds only what is missing.': 'భారతదేశంలో అమ్ముడయ్యే సాధారణ కంపెనీలు, మోడళ్లతో మీ జాబితా మొదలవుతుంది. పేర్లు మాత్రమే చేరతాయి. ఏ భాగమూ ఏ వాహనానికీ సరిపోతుందని గుర్తించబడదు. మళ్లీ జోడిస్తే లేనివి మాత్రమే చేరతాయి.',
