  'Check the file': 'ఫైల్‌ను తనిఖీ చేయండి',
  'Import the customers': 'కస్టమర్లను దిగుమతి చేయండి',
  'Choose a CSV file. In Excel, use Save as, CSV.': 'ఒక CSV ఫైల్‌ను ఎంచుకోండి. Excel లో Save as, CSV వాడండి.',
