  'Tax invoice details: consignee, delivery, dispatch': 'ಟ್ಯಾಕ್ಸ್ ಇನ್ವಾಯ್ಸ್ ವಿವರಗಳು: ಸರಕು ಸ್ವೀಕರಿಸುವವರು, ಡೆಲಿವರಿ, ರವಾನೆ',
  'Printed on the Tally-style invoice. Blank buyer fields use the customer\'s record; a blank consignee means the same as the buyer.': 'ಟ್ಯಾಲಿ ಶೈಲಿಯ ಇನ್ವಾಯ್ಸ್‌ನಲ್ಲಿ ಮುದ್ರಿತವಾಗುತ್ತದೆ. ಖಾಲಿ ಖರೀದಿದಾರ ಕ್ಷೇತ್ರಗಳಿಗೆ ಗ್ರಾಹಕರ ದಾಖಲೆ ಬಳಸಲಾಗುತ್ತದೆ; ಖಾಲಿ ಸರಕು ಸ್ವೀಕರಿಸುವವರು ಎಂದರೆ ಖರೀದಿದಾರರೇ.',
  'Invoice details': 'ಇನ್ವಾಯ್ಸ್ ವಿವರಗಳು',
  'Printed on this tax invoice only. Leave the consignee blank when it is the same as the buyer.': 'ಈ ಟ್ಯಾಕ್ಸ್ ಇನ್ವಾಯ್ಸ್‌ನಲ್ಲಿ ಮಾತ್ರ ಮುದ್ರಿತವಾಗುತ್ತದೆ. ಸರಕು ಸ್ವೀಕರಿಸುವವರು ಖರೀದಿದಾರರೇ ಆಗಿದ್ದರೆ ಖಾಲಿ ಬಿಡಿ.',
