  'How this phone shows the app. It stays on this phone and changes nothing on your bills or reports.': 'ಈ ಫೋನ್ ಆ್ಯಪ್ ಅನ್ನು ಹೇಗೆ ತೋರಿಸುತ್ತದೆ. ಇದು ಈ ಫೋನ್‌ನಲ್ಲಿಯೇ ಇರುತ್ತದೆ ಮತ್ತು ನಿಮ್ಮ ಬಿಲ್ ಅಥವಾ ವರದಿಗಳಲ್ಲಿ ಏನನ್ನೂ ಬದಲಾಯಿಸುವುದಿಲ್ಲ.',
  'Receipts and shared bills always show the exact amount.': 'ರಸೀದಿಗಳು ಮತ್ತು ಹಂಚಿದ ಬಿಲ್‌ಗಳು ಯಾವಾಗಲೂ ನಿಖರವಾದ ಮೊತ್ತವನ್ನು ತೋರಿಸುತ್ತವೆ.',
  'Download a copy of all your records (customers, products, bills, payments, expenses and stock) as a ZIP of CSV files, then save or send it from the share sheet. Keep it somewhere safe. FlowXP does not restore from it by itself: ask support if you ever need your data put back.': 'ನಿಮ್ಮ ಎಲ್ಲಾ ದಾಖಲೆಗಳ (ಗ್ರಾಹಕರು, ಉತ್ಪನ್ನಗಳು, ಬಿಲ್‌ಗಳು, ಪಾವತಿಗಳು, ವೆಚ್ಚಗಳು, ಸ್ಟಾಕ್) ಪ್ರತಿಯನ್ನು CSV ಫೈಲ್‌ಗಳ ZIP ಆಗಿ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ, ಶೇರ್ ಶೀಟ್‌ನಿಂದ ಉಳಿಸಿ ಅಥವಾ ಕಳುಹಿಸಿ. ಸುರಕ್ಷಿತವಾಗಿಡಿ. FlowXP ಇದರಿಂದ ತಾನಾಗಿ ಮರುಸ್ಥಾಪಿಸುವುದಿಲ್ಲ: ಡೇಟಾ ಮರಳಿ ಬೇಕಿದ್ದರೆ ಸಪೋರ್ಟ್‌ನ್ನು ಕೇಳಿ.',
  'Could not take the backup.': 'ಬ್ಯಾಕಪ್ ತೆಗೆದುಕೊಳ್ಳಲಾಗಲಿಲ್ಲ.',
  'Could not take the backup. Only the owner can, and the phone needs a connection.': 'ಬ್ಯಾಕಪ್ ತೆಗೆದುಕೊಳ್ಳಲಾಗಲಿಲ್ಲ. ಮಾಲೀಕರು ಮಾತ್ರ ತೆಗೆದುಕೊಳ್ಳಬಹುದು, ಫೋನ್‌ಗೆ ಸಂಪರ್ಕ ಬೇಕು.',
  'This phone cannot share files from FlowXP.': 'ಈ ಫೋನ್ FlowXP ನಿಂದ ಫೈಲ್‌ಗಳನ್ನು ಹಂಚಿಕೊಳ್ಳಲಾಗುವುದಿಲ್ಲ.',
