  'Cut the paper after each receipt': 'ಪ್ರತಿ ರಸೀದಿಯ ನಂತರ ಕಾಗದ ಕತ್ತರಿಸಿ',
  'Composite scheme': 'ಕಾಂಪೊಸಿಷನ್ ಯೋಜನೆ',
  'You pay a flat share of your turnover instead of charging GST. Bills become Bills of Supply with no tax on them.': 'GST ವಿಧಿಸುವ ಬದಲು ನಿಮ್ಮ ವಹಿವಾಟಿನ ನಿಗದಿತ ಪಾಲನ್ನು ಪಾವತಿಸುತ್ತೀರಿ. ಬಿಲ್‌ಗಳು ತೆರಿಗೆ ಇಲ್ಲದ ಪೂರೈಕೆ ಬಿಲ್‌ಗಳಾಗುತ್ತವೆ.',
  'Composite tax rate (% of turnover)': 'ಕಾಂಪೊಸಿಷನ್ ತೆರಿಗೆ ದರ (ವಹಿವಾಟಿನ %)',
  'Compensation cess on top of GST. Set the cess rate on each product (Products → edit); it is added to the line and the bill.': 'GST ಮೇಲೆ ಪರಿಹಾರ ಸೆಸ್. ಪ್ರತಿ ಉತ್ಪನ್ನದಲ್ಲಿ ಸೆಸ್ ದರ ಹೊಂದಿಸಿ (ಉತ್ಪನ್ನಗಳು → ತಿದ್ದು); ಇದು ಸಾಲು ಮತ್ತು ಬಿಲ್‌ಗೆ ಸೇರುತ್ತದೆ.',
  'TCS (tax collected at source)': 'TCS (ಮೂಲದಲ್ಲಿ ಸಂಗ್ರಹಿಸಿದ ತೆರಿಗೆ)',
  'A "Collect TCS" tick appears on the billing screen. When ticked, the TCS is added to that bill.': 'ಬಿಲ್ಲಿಂಗ್ ಪರದೆಯಲ್ಲಿ "TCS ವಸೂಲಿ ಮಾಡಿ" ಟಿಕ್ ಕಾಣಿಸುತ್ತದೆ. ಟಿಕ್ ಮಾಡಿದರೆ ಆ ಬಿಲ್‌ಗೆ TCS ಸೇರುತ್ತದೆ.',
  'TCS rate (%)': 'TCS ದರ (%)',
  'TDS (tax deducted by the customer)': 'TDS (ಗ್ರಾಹಕರು ಕಡಿತ ಮಾಡುವ ತೆರಿಗೆ)',
  'A "Customer deducts TDS" tick appears on the billing screen. When ticked, the TDS is taken off what the customer pays and noted on the bill.': 'ಬಿಲ್ಲಿಂಗ್ ಪರದೆಯಲ್ಲಿ "ಗ್ರಾಹಕರು TDS ಕಡಿತ ಮಾಡುತ್ತಾರೆ" ಟಿಕ್ ಕಾಣಿಸುತ್ತದೆ. ಟಿಕ್ ಮಾಡಿದರೆ ಗ್ರಾಹಕರು ಪಾವತಿಸುವ ಮೊತ್ತದಿಂದ TDS ಕಳೆದು ಬಿಲ್‌ನಲ್ಲಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ.',
  'TDS rate (%)': 'TDS ದರ (%)',
  'A "Tax payable on reverse charge" tick appears on the billing screen and prints on the invoice.': 'ಬಿಲ್ಲಿಂಗ್ ಪರದೆಯಲ್ಲಿ "ರಿವರ್ಸ್ ಚಾರ್ಜ್ ಮೇಲೆ ಪಾವತಿಸಬೇಕಾದ ತೆರಿಗೆ" ಟಿಕ್ ಕಾಣಿಸಿ ಇನ್ವಾಯ್ಸ್‌ನಲ್ಲಿ ಮುದ್ರಿತವಾಗುತ್ತದೆ.',
  'Details, receipt, GST and invoice (owner)': 'ವಿವರಗಳು, ರಸೀದಿ, GST, ಇನ್ವಾಯ್ಸ್ (ಮಾಲೀಕ)',
