  'Upload it on the GST portal (Returns, GSTR-1, Prepare offline) or give it to your accountant. {hsn_rows} HSN rows included.': 'ಇದನ್ನು ಜಿಎಸ್‌ಟಿ ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ (ರಿಟರ್ನ್‌ಗಳು, GSTR-1, ಆಫ್‌ಲೈನ್‌ನಲ್ಲಿ ಸಿದ್ಧಪಡಿಸಿ) ಅಥವಾ ನಿಮ್ಮ ಲೆಕ್ಕಿಗರಿಗೆ ನೀಡಿ. {hsn_rows} HSN ಸಾಲುಗಳು ಸೇರಿವೆ.',
