  'Large inter-state invoice limit (₹)': 'ದೊಡ್ಡ ಅಂತರರಾಜ್ಯ ಇನ್‌ವಾಯ್ಸ್ ಮಿತಿ (₹)',
  'Inter-state sales to people without a GSTIN above this go in the B2CL table. Confirm the current limit with your accountant.': 'GSTIN ಇಲ್ಲದವರಿಗೆ ಇದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಅಂತರರಾಜ್ಯ ಮಾರಾಟಗಳು B2CL ಕೋಷ್ಟಕಕ್ಕೆ ಹೋಗುತ್ತವೆ. ಪ್ರಸ್ತುತ ಮಿತಿಯನ್ನು ನಿಮ್ಮ ಲೆಕ್ಕಿಗರೊಂದಿಗೆ ಖಚಿತಪಡಿಸಿ.',
