  'Your GSTIN is set in Business settings. Add each customer\'s state, pincode and GSTIN on the Customers page, and an HSN/SAC code on every product, so the files come out complete.': 'ನಿಮ್ಮ GSTIN ವ್ಯಾಪಾರ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಹೊಂದಿಸಲಾಗಿದೆ. ಫೈಲ್‌ಗಳು ಪೂರ್ಣವಾಗಿ ಬರಲು ಗ್ರಾಹಕರ ಪುಟದಲ್ಲಿ ಪ್ರತಿ ಗ್ರಾಹಕರ ರಾಜ್ಯ, ಪಿನ್‌ಕೋಡ್, GSTIN ಮತ್ತು ಪ್ರತಿ ಉತ್ಪನ್ನಕ್ಕೆ HSN/SAC ಕೋಡ್ ಸೇರಿಸಿ.',
  '{customers} customers · {taxable} taxable': '{customers} ಗ್ರಾಹಕರು · {taxable} ತೆರಿಗೆ ಅನ್ವಯಿಸುವುದು',
