  'Purchases from suppliers without a GSTIN carry {amount} of tax that is not claimable.': 'GSTIN ಇಲ್ಲದ ಸರಬರಾಜುದಾರರಿಂದ ಖರೀದಿಗಳಲ್ಲಿ {amount} ತೆರಿಗೆ ಇದೆ, ಅದನ್ನು ಕ್ಲೈಮ್ ಮಾಡಲಾಗುವುದಿಲ್ಲ.',
  'E-invoicing applies to businesses above a turnover limit and only for sales to customers with a GSTIN. If it does not apply to you, ignore this tab.': 'ಇ-ಇನ್ವಾಯ್ಸಿಂಗ್ ಒಂದು ವಹಿವಾಟು ಮಿತಿಗಿಂತ ಹೆಚ್ಚಿನ ವ್ಯವಹಾರಗಳಿಗೆ ಮತ್ತು GSTIN ಇರುವ ಗ್ರಾಹಕರಿಗೆ ಮಾರಾಟಕ್ಕೆ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ. ನಿಮಗೆ ಅನ್ವಯಿಸದಿದ್ದರೆ ಈ ಟ್ಯಾಬ್ ಅನ್ನು ಬಿಟ್ಟುಬಿಡಿ.',
