  'A customer is their mobile number. Every day they are billed counts as one visit, at any outlet. On the visit that earns it, the free item comes off the bill once it is on the order (the till offers to add it).': 'ಗ್ರಾಹಕ ಎಂದರೆ ಅವರ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ. ಬಿಲ್ ಮಾಡುವ ಪ್ರತಿ ದಿನ ಒಂದು ಭೇಟಿಯಾಗಿ ಎಣಿಕೆಯಾಗುತ್ತದೆ, ಯಾವುದೇ ಔಟ್‌ಲೆಟ್‌ನಲ್ಲಿ. ಬಹುಮಾನ ಸಿಗುವ ಭೇಟಿಯಲ್ಲಿ, ಉಚಿತ ಐಟಂ ಆರ್ಡರ್‌ಗೆ ಸೇರಿದ ಮೇಲೆ ಬಿಲ್‌ನಿಂದ ಕಡಿಮೆಯಾಗುತ್ತದೆ (ಟಿಲ್ ಅದನ್ನು ಸೇರಿಸಲು ಸೂಚಿಸುತ್ತದೆ).',
