  'Their next bill gets the free item. A nice reason to call them in.': 'ಅವರ ಮುಂದಿನ ಬಿಲ್‌ನಲ್ಲಿ ಉಚಿತ ಐಟಂ ಸಿಗುತ್ತದೆ. ಅವರನ್ನು ಕರೆಯಲು ಒಳ್ಳೆಯ ಕಾರಣ.',
