  'Tiers': 'ಟೈಯರ್‌ಗಳು',
  'A tier is decided by the points a customer has earned over time (spending points never lowers it). A higher tier earns points faster. The first tier must start at 0. Leave empty for no tiers.': 'ಗ್ರಾಹಕರು ಕಾಲಕ್ರಮೇಣ ಗಳಿಸಿದ ಪಾಯಿಂಟ್‌ಗಳ ಮೇಲೆ ಟೈಯರ್ ನಿರ್ಧಾರವಾಗುತ್ತದೆ (ಪಾಯಿಂಟ್ ಖರ್ಚು ಮಾಡಿದರೂ ಅದು ಕಡಿಮೆಯಾಗುವುದಿಲ್ಲ). ಹೆಚ್ಚಿನ ಟೈಯರ್‌ನಲ್ಲಿ ಪಾಯಿಂಟ್‌ಗಳು ವೇಗವಾಗಿ ಸಿಗುತ್ತವೆ. ಮೊದಲ ಟೈಯರ್ 0ಯಿಂದ ಆರಂಭವಾಗಬೇಕು. ಟೈಯರ್ ಬೇಡವೆಂದರೆ ಖಾಲಿ ಬಿಡಿ.',
