  'Reason (kept in their history)': 'ಕಾರಣ (ಅವರ ಇತಿಹಾಸದಲ್ಲಿ ಇಡಲಾಗುತ್ತದೆ)',
  'Birthday gift, service recovery…': 'ಹುಟ್ಟುಹಬ್ಬದ ಉಡುಗೊರೆ, ಸೇವೆ ಸರಿಪಡಿಸುವಿಕೆ…',
  '{name} now has {balance} points': '{name} ಅವರಿಗೆ ಈಗ {balance} ಪಾಯಿಂಟ್‌ಗಳಿವೆ',
  'Points per Rs 100 must be above 0 and at most 100': '₹100ಕ್ಕೆ ಪಾಯಿಂಟ್‌ಗಳು 0 ಕ್ಕಿಂತ ಹೆಚ್ಚು, ಗರಿಷ್ಠ 100 ಇರಬೇಕು',
  'A point must be worth between Rs 0.01 and Rs 1000': 'ಒಂದು ಪಾಯಿಂಟ್‌ನ ಮೌಲ್ಯ ₹0.01 ರಿಂದ ₹1000 ನಡುವೆ ಇರಬೇಕು',
  'The minimum to use must be a whole number of points': 'ಬಳಸಲು ಕನಿಷ್ಠ ಪಾಯಿಂಟ್‌ಗಳು ಪೂರ್ಣ ಸಂಖ್ಯೆ ಆಗಿರಬೇಕು',
  'The most a bill can be paid with points must be 1 to 100 percent': 'ಒಂದು ಬಿಲ್ ಅನ್ನು ಪಾಯಿಂಟ್‌ಗಳಿಂದ ಪಾವತಿಸಬಹುದಾದ ಗರಿಷ್ಠ 1 ರಿಂದ 100 ಶೇಕಡಾ ಇರಬೇಕು',
  'Up to six tiers': 'ಗರಿಷ್ಠ ಆರು ಟೈಯರ್‌ಗಳು',
  'Every tier needs a name (up to 30 characters)': 'ಪ್ರತಿ ಟೈಯರ್‌ಗೆ ಹೆಸರು ಬೇಕು (30 ಅಕ್ಷರಗಳವರೆಗೆ)',
  'Points to reach a tier must be a whole number, 0 or more': 'ಟೈಯರ್ ತಲುಪಲು ಪಾಯಿಂಟ್‌ಗಳು 0 ಅಥವಾ ಹೆಚ್ಚಿನ ಪೂರ್ಣ ಸಂಖ್ಯೆ ಆಗಿರಬೇಕು',
  'Two tiers start at the same number of points': 'ಎರಡು ಟೈಯರ್‌ಗಳು ಒಂದೇ ಪಾಯಿಂಟ್ ಸಂಖ್ಯೆಯಿಂದ ಆರಂಭವಾಗುತ್ತಿವೆ',
  'The earning multiplier must be from 1 to 10': 'ಗಳಿಕೆಯ ಗುಣಕ 1 ರಿಂದ 10 ರ ನಡುವೆ ಇರಬೇಕು',
  'The first tier must start at 0 points so everyone has one': 'ಎಲ್ಲರಿಗೂ ಒಂದು ಟೈಯರ್ ಇರುವಂತೆ ಮೊದಲ ಟೈಯರ್ 0 ಪಾಯಿಂಟ್‌ಗಳಿಂದ ಆರಂಭವಾಗಬೇಕು',
  'Say why, so it is kept in their history': 'ಕಾರಣ ತಿಳಿಸಿ, ಅದು ಅವರ ಇತಿಹಾಸದಲ್ಲಿ ಉಳಿಯುತ್ತದೆ',
  'Enter a whole number of points (negative takes away)': 'ಪಾಯಿಂಟ್‌ಗಳ ಪೂರ್ಣ ಸಂಖ್ಯೆ ನಮೂದಿಸಿ (ಋಣ ಕಡಿಮೆ ಮಾಡುತ್ತದೆ)',
