  'No coupons yet. Create one and give the code to a customer; the cashier enters it at billing.': 'ಇನ್ನೂ ಕೂಪನ್‌ಗಳಿಲ್ಲ. ಒಂದನ್ನು ರಚಿಸಿ ಕೋಡ್ ಅನ್ನು ಗ್ರಾಹಕರಿಗೆ ಕೊಡಿ; ಕ್ಯಾಷಿಯರ್ ಬಿಲ್ಲಿಂಗ್‌ನಲ್ಲಿ ನಮೂದಿಸುತ್ತಾರೆ.',
  'Code must be 3 to 24 letters, numbers, - or _': 'ಕೋಡ್ 3 ರಿಂದ 24 ಅಕ್ಷರಗಳು, ಅಂಕೆಗಳು, - ಅಥವಾ _ ಆಗಿರಬೇಕು',
  'Enter how much the coupon takes off': 'ಕೂಪನ್ ಎಷ್ಟು ಕಡಿಮೆ ಮಾಡುತ್ತದೆ ಎಂದು ನಮೂದಿಸಿ',
