  'Uses must be a whole number above zero': 'ಬಳಕೆಗಳು ಶೂನ್ಯಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಪೂರ್ಣ ಸಂಖ್ಯೆ ಆಗಿರಬೇಕು',
  'The end date is before the start date': 'ಅಂತಿಮ ದಿನಾಂಕ ಆರಂಭ ದಿನಾಂಕಕ್ಕಿಂತ ಮೊದಲಿದೆ',
  // Offers search
  'Search by name or barcode, then tap to add': 'ಹೆಸರು ಅಥವಾ ಬಾರ್‌ಕೋಡ್‌ನಿಂದ ಹುಡುಕಿ, ನಂತರ ಸೇರಿಸಲು ಟ್ಯಾಪ್ ಮಾಡಿ',
  // Messaging
  'Messaging': 'ಸಂದೇಶ ಕಳುಹಿಸುವಿಕೆ',
  'Counting…': 'ಎಣಿಸಲಾಗುತ್ತಿದೆ…',
  'Sending…': 'ಕಳುಹಿಸಲಾಗುತ್ತಿದೆ…',
  'Failed': 'ವಿಫಲ',
  'Sent': 'ಕಳುಹಿಸಲಾಗಿದೆ',
  'WhatsApp or SMS: bills, bookings, offers': 'ವಾಟ್ಸಾಪ್ ಅಥವಾ SMS: ಬಿಲ್‌ಗಳು, ಬುಕಿಂಗ್‌ಗಳು, ಆಫರ್‌ಗಳು',
  'Send bills, booking updates and offers to customers on WhatsApp or SMS.': 'ಗ್ರಾಹಕರಿಗೆ ವಾಟ್ಸಾಪ್ ಅಥವಾ SMS ನಲ್ಲಿ ಬಿಲ್‌ಗಳು, ಬುಕಿಂಗ್ ಅಪ್‌ಡೇಟ್‌ಗಳು ಮತ್ತು ಆಫರ್‌ಗಳನ್ನು ಕಳುಹಿಸಿ.',
  'Send an offer': 'ಆಫರ್ ಕಳುಹಿಸಿ',
  'Message log': 'ಸಂದೇಶ ಲಾಗ್',
  'Messaging is for owners and admins.': 'ಮೆಸೇಜಿಂಗ್ ಮಾಲೀಕರು ಮತ್ತು ಅಡ್ಮಿನ್‌ಗಳಿಗಾಗಿ.',
  'Send messages by': 'ಸಂದೇಶಗಳನ್ನು ಕಳುಹಿಸುವ ಮಾರ್ಗ',
  'Off: send nothing': 'ಆಫ್: ಏನನ್ನೂ ಕಳುಹಿಸಬೇಡಿ',
  'WhatsApp': 'ವಾಟ್ಸಾಪ್',
  'SMS': 'SMS',
  'Connected: {name}': 'ಸಂಪರ್ಕಗೊಂಡಿದೆ: {name}',
  'No messaging service is connected on the server yet, so messages are only recorded as skipped. Ask whoever runs the server to set it up.': 'ಸರ್ವರ್‌ನಲ್ಲಿ ಇನ್ನೂ ಮೆಸೇಜಿಂಗ್ ಸೇವೆ ಸಂಪರ್ಕಗೊಂಡಿಲ್ಲ, ಆದ್ದರಿಂದ ಸಂದೇಶಗಳು "ಬಿಟ್ಟುಬಿಡಲಾಗಿದೆ" ಎಂದು ಮಾತ್ರ ದಾಖಲಾಗುತ್ತವೆ. ಸರ್ವರ್ ನಡೆಸುವವರಿಗೆ ಇದನ್ನು ಹೊಂದಿಸಲು ಹೇಳಿ.',
  'Send the bill to customers with a mobile number': 'ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಇರುವ ಗ್ರಾಹಕರಿಗೆ ಬಿಲ್ ಕಳುಹಿಸಿ',
  'After every sale to a customer, with a link to view the bill.': 'ಗ್ರಾಹಕರಿಗೆ ಪ್ರತಿ ಮಾರಾಟದ ನಂತರ, ಬಿಲ್ ನೋಡಲು ಲಿಂಕ್‌ನೊಂದಿಗೆ.',
  'Booking confirmations and cancellations': 'ಬುಕಿಂಗ್ ದೃಢೀಕರಣ ಮತ್ತು ರದ್ದತಿಗಳು',
  'When a reservation with a mobile number is made or cancelled.': 'ಮೊಬೈಲ್ ಸಂಖ್ಯೆಯೊಂದಿಗೆ ಕಾಯ್ದಿರಿಸುವಿಕೆ ಮಾಡಿದಾಗ ಅಥವಾ ರದ್ದಾದಾಗ.',
  'Waitlist updates': 'ವೇಟ್‌ಲಿಸ್ಟ್ ಅಪ್‌ಡೇಟ್‌ಗಳು',
  'When someone joins the waitlist and when their table is ready.': 'ಯಾರಾದರೂ ವೇಟ್‌ಲಿಸ್ಟ್‌ಗೆ ಸೇರಿದಾಗ ಮತ್ತು ಅವರ ಟೇಬಲ್ ಸಿದ್ಧವಾದಾಗ.',
  'Loyalty reminder': 'ಲಾಯಲ್ಟಿ ಜ್ಞಾಪನೆ',
  'When a customer\'s next visit earns their free item (at most once a week).': 'ಗ್ರಾಹಕರ ಮುಂದಿನ ಭೇಟಿಯಲ್ಲಿ ಉಚಿತ ಐಟಂ ಸಿಗುವಾಗ (ವಾರಕ್ಕೆ ಗರಿಷ್ಠ ಒಮ್ಮೆ).',
  'Offers and reminders only go to customers who have not opted out. Bills and booking messages are service messages and are sent regardless.': 'ಆಫರ್ ಮತ್ತು ಜ್ಞಾಪನೆಗಳು ಹೊರಗುಳಿಯದ ಗ್ರಾಹಕರಿಗೆ ಮಾತ್ರ ಹೋಗುತ್ತವೆ. ಬಿಲ್ ಮತ್ತು ಬುಕಿಂಗ್ ಸಂದೇಶಗಳು ಸೇವಾ ಸಂದೇಶಗಳು, ಅವು ಏನೇ ಆದರೂ ಕಳುಹಿಸಲಾಗುತ್ತವೆ.',
  'Show the WhatsApp templates to create in Meta': 'Meta ನಲ್ಲಿ ರಚಿಸಬೇಕಾದ ವಾಟ್ಸಾಪ್ ಟೆಂಪ್ಲೇಟ್‌ಗಳನ್ನು ತೋರಿಸಿ',
  'Hide the WhatsApp templates': 'ವಾಟ್ಸಾಪ್ ಟೆಂಪ್ಲೇಟ್‌ಗಳನ್ನು ಮರೆಮಾಡಿ',
  'WhatsApp only lets a business start a chat with pre-approved templates. Create each one once in Meta Business Manager (category: Utility for bills and bookings, Marketing for offers), using exactly this name and text.': 'ಮೊದಲೇ ಅನುಮೋದಿತ ಟೆಂಪ್ಲೇಟ್‌ಗಳಿಂದ ಮಾತ್ರ ವಾಟ್ಸಾಪ್ ವ್ಯಾಪಾರಕ್ಕೆ ಚಾಟ್ ಆರಂಭಿಸಲು ಅವಕಾಶ ನೀಡುತ್ತದೆ. ಪ್ರತಿಯೊಂದನ್ನು Meta Business Manager ನಲ್ಲಿ ಒಮ್ಮೆ ರಚಿಸಿ (ವರ್ಗ: ಬಿಲ್ ಮತ್ತು ಬುಕಿಂಗ್‌ಗೆ Utility, ಆಫರ್‌ಗಳಿಗೆ Marketing), ನಿಖರವಾಗಿ ಇದೇ ಹೆಸರು ಮತ್ತು ಪಠ್ಯದೊಂದಿಗೆ.',
