  'Flat 10% off on dinner this weekend. Show this message at the counter.': 'ಈ ವಾರಾಂತ್ಯ ಡಿನ್ನರ್‌ಗೆ 10% ರಿಯಾಯಿತಿ. ಕೌಂಟರ್‌ನಲ್ಲಿ ಈ ಸಂದೇಶವನ್ನು ತೋರಿಸಿ.',
