  'One offer per hour, so customers are not flooded. Customers who opted out are left out automatically.': 'ಗಂಟೆಗೆ ಒಂದು ಆಫರ್, ಆದ್ದರಿಂದ ಗ್ರಾಹಕರಿಗೆ ಸಂದೇಶಗಳ ಪ್ರವಾಹ ಆಗುವುದಿಲ್ಲ. ಹೊರಗುಳಿದವರನ್ನು ತಾನಾಗಿಯೇ ಬಿಡಲಾಗುತ್ತದೆ.',
  'Send offer': 'ಆಫರ್ ಕಳುಹಿಸಿ',
