  // Printers
  'Bluetooth and Wi-Fi printers: receipt and kitchen ticket': 'ಬ್ಲೂಟೂತ್, ವೈ-ಫೈ ಪ್ರಿಂಟರ್‌ಗಳು: ರಸೀದಿ ಮತ್ತು ಅಡುಗೆಮನೆ ಟಿಕೆಟ್',
  'Connect a Bluetooth or Wi-Fi thermal printer, and choose what each one prints.': 'ಬ್ಲೂಟೂತ್ ಅಥವಾ ವೈ-ಫೈ ಥರ್ಮಲ್ ಪ್ರಿಂಟರ್ ಸಂಪರ್ಕಿಸಿ, ಪ್ರತಿಯೊಂದೂ ಏನನ್ನು ಮುದ್ರಿಸಬೇಕು ಎಂದು ಆರಿಸಿ.',
  'Printing straight to a printer needs the FlowXP development app. In the Expo Go test copy, use the phone print screen or RawBT in Settings.': 'ಪ್ರಿಂಟರ್‌ಗೆ ನೇರವಾಗಿ ಮುದ್ರಿಸಲು FlowXP ಡೆವಲಪ್‌ಮೆಂಟ್ ಆ್ಯಪ್ ಬೇಕು. Expo Go ಟೆಸ್ಟ್ ಪ್ರತಿಯಲ್ಲಿ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿರುವ ಫೋನ್ ಪ್ರಿಂಟ್ ಸ್ಕ್ರೀನ್ ಅಥವಾ RawBT ಬಳಸಿ.',
  'No printers yet.': 'ಇನ್ನೂ ಪ್ರಿಂಟರ್‌ಗಳಿಲ್ಲ.',
  'Add a Bluetooth printer': 'ಬ್ಲೂಟೂತ್ ಪ್ರಿಂಟರ್ ಸೇರಿಸಿ',
  'Add a Wi-Fi printer': 'ವೈ-ಫೈ ಪ್ರಿಂಟರ್ ಸೇರಿಸಿ',
  'Paired Bluetooth printers': 'ಜೋಡಿಸಿದ ಬ್ಲೂಟೂತ್ ಪ್ರಿಂಟರ್‌ಗಳು',
  'Pair the printer first in the phone\'s Bluetooth settings (the code is usually 0000 or 1234), then come back and pick it here.': 'ಮೊದಲು ಫೋನ್‌ನ ಬ್ಲೂಟೂತ್ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿ ಪ್ರಿಂಟರ್ ಅನ್ನು ಪೇರ್ ಮಾಡಿ (ಕೋಡ್ ಸಾಮಾನ್ಯವಾಗಿ 0000 ಅಥವಾ 1234), ನಂತರ ಇಲ್ಲಿ ಬಂದು ಆರಿಸಿ.',
  'Look for printers nearby': 'ಹತ್ತಿರದ ಪ್ರಿಂಟರ್‌ಗಳನ್ನು ಹುಡುಕಿ',
  'No Bluetooth printers found. Switch the printer on and pair it in the phone\'s Bluetooth settings.': 'ಯಾವುದೇ ಬ್ಲೂಟೂತ್ ಪ್ರಿಂಟರ್ ಸಿಗಲಿಲ್ಲ. ಪ್ರಿಂಟರ್ ಆನ್ ಮಾಡಿ ಫೋನ್‌ನ ಬ್ಲೂಟೂತ್ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿ ಪೇರ್ ಮಾಡಿ.',
  'Address on the network': 'ನೆಟ್‌ವರ್ಕ್‌ನಲ್ಲಿ ವಿಳಾಸ',
  'Port': 'ಪೋರ್ಟ್',
  'Add this printer': 'ಈ ಪ್ರಿಂಟರ್ ಸೇರಿಸಿ',
  '58 mm paper': '58 ಮಿ.ಮೀ. ಕಾಗದ',
  '80 mm paper': '80 ಮಿ.ಮೀ. ಕಾಗದ',
  'What it prints': 'ಇದು ಏನನ್ನು ಮುದ್ರಿಸುತ್ತದೆ',
  'Customer receipt': 'ಗ್ರಾಹಕರ ರಸೀದಿ',
  'The bill the customer takes.': 'ಗ್ರಾಹಕರು ತೆಗೆದುಕೊಂಡು ಹೋಗುವ ಬಿಲ್.',
  'Kitchen ticket': 'ಅಡುಗೆಮನೆ ಟಿಕೆಟ್',
  'What the kitchen makes, printed when an order is sent to it.': 'ಅಡುಗೆಮನೆ ಏನು ಮಾಡಬೇಕು, ಆರ್ಡರ್ ಕಳುಹಿಸಿದಾಗ ಮುದ್ರಣವಾಗುತ್ತದೆ.',
  'Print a test': 'ಟೆಸ್ಟ್ ಮುದ್ರಿಸಿ',
  'Test sent. If nothing printed, check the printer is on, in range, and has paper.': 'ಟೆಸ್ಟ್ ಕಳುಹಿಸಲಾಗಿದೆ. ಏನೂ ಮುದ್ರಣವಾಗದಿದ್ದರೆ ಪ್ರಿಂಟರ್ ಆನ್ ಆಗಿದೆಯೇ, ಹತ್ತಿರದಲ್ಲಿದೆಯೇ, ಕಾಗದ ಇದೆಯೇ ನೋಡಿ.',
  'Could not print.': 'ಮುದ್ರಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.',
  'Enter the printer\'s address on your network, like 192.168.1.50': 'ನಿಮ್ಮ ನೆಟ್‌ವರ್ಕ್‌ನಲ್ಲಿ ಪ್ರಿಂಟರ್‌ನ ವಿಳಾಸ ನಮೂದಿಸಿ, ಉದಾ. 192.168.1.50',
  'That address does not look right. It is numbers with dots, like 192.168.1.50': 'ಆ ವಿಳಾಸ ಸರಿಯಾಗಿಲ್ಲ. ಇದು ಚುಕ್ಕೆಗಳಿರುವ ಸಂಖ್ಯೆಗಳು, ಉದಾ. 192.168.1.50',
  'The port is a number from 1 to 65535 (most printers use 9100)': 'ಪೋರ್ಟ್ 1 ರಿಂದ 65535 ನಡುವಿನ ಸಂಖ್ಯೆ (ಹೆಚ್ಚಿನ ಪ್ರಿಂಟರ್‌ಗಳು 9100 ಬಳಸುತ್ತವೆ)',
  'Allow FlowXP to use Bluetooth (nearby devices) in the phone settings, then try again.': 'ಫೋನ್ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿ FlowXP ಗೆ ಬ್ಲೂಟೂತ್ (ಹತ್ತಿರದ ಸಾಧನಗಳು) ಅನುಮತಿ ನೀಡಿ, ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.',
  'Switch Bluetooth on, then try again.': 'ಬ್ಲೂಟೂತ್ ಆನ್ ಮಾಡಿ, ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.',
  'Could not reach the printer. Check that it is switched on, in range, and paired in the phone\'s Bluetooth settings.': 'ಪ್ರಿಂಟರ್ ಅನ್ನು ತಲುಪಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಅದು ಆನ್ ಆಗಿದೆಯೇ, ಹತ್ತಿರದಲ್ಲಿದೆಯೇ, ಫೋನ್‌ನ ಬ್ಲೂಟೂತ್ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿ ಪೇರ್ ಆಗಿದೆಯೇ ನೋಡಿ.',
  'Could not reach the printer. Check that it is switched on, on the same Wi-Fi as this phone, and that the address is right.': 'ಪ್ರಿಂಟರ್ ಅನ್ನು ತಲುಪಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಅದು ಆನ್ ಆಗಿದೆಯೇ, ಈ ಫೋನ್‌ನ ಅದೇ ವೈ-ಫೈನಲ್ಲಿದೆಯೇ, ವಿಳಾಸ ಸರಿಯೇ ನೋಡಿ.',
  'You can keep up to {n} printers.': 'ನೀವು ಗರಿಷ್ಠ {n} ಪ್ರಿಂಟರ್‌ಗಳನ್ನು ಇಟ್ಟುಕೊಳ್ಳಬಹುದು.',
  'Straight to my printers': 'ನನ್ನ ಪ್ರಿಂಟರ್‌ಗಳಿಗೆ ನೇರವಾಗಿ',
  'Phone print screen': 'ಫೋನ್ ಪ್ರಿಂಟ್ ಸ್ಕ್ರೀನ್',
  'Through RawBT': 'RawBT ಮೂಲಕ',
  'Kitchen ticket sent to the printer.': 'ಅಡುಗೆಮನೆ ಟಿಕೆಟ್ ಅನ್ನು ಪ್ರಿಂಟರ್‌ಗೆ ಕಳುಹಿಸಲಾಗಿದೆ.',
  'Could not print the kitchen ticket. The order was still sent to the kitchen.': 'ಅಡುಗೆಮನೆ ಟಿಕೆಟ್ ಮುದ್ರಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಆರ್ಡರ್ ಅನ್ನು ಅಡುಗೆಮನೆಗೆ ಕಳುಹಿಸಲಾಗಿದೆ.',
  // Printers (more)
  'Printers': 'ಪ್ರಿಂಟರ್‌ಗಳು',
  'Looking…': 'ಹುಡುಕುತ್ತಿದೆ…',
  'Printer name': 'ಪ್ರಿಂಟರ್ ಹೆಸರು',
  // Printers (more)
  'Receipts go straight to a connected printer. If it cannot be reached, the bill goes to the phone print screen so printing is never stuck.': 'ರಸೀದಿಗಳು ನೇರವಾಗಿ ಸಂಪರ್ಕಿತ ಪ್ರಿಂಟರ್‌ಗೆ ಹೋಗುತ್ತವೆ. ತಲುಪಲಾಗದಿದ್ದರೆ ಬಿಲ್ ಫೋನ್ ಪ್ರಿಂಟ್ ಸ್ಕ್ರೀನ್‌ಗೆ ಹೋಗುತ್ತದೆ, ಆದ್ದರಿಂದ ಮುದ್ರಣ ಎಂದಿಗೂ ನಿಲ್ಲುವುದಿಲ್ಲ.',
