  'Share the e-way bill file (JSON)': 'ಇ-ವೇ ಬಿಲ್ ಫೈಲ್ (JSON) ಹಂಚಿಕೊಳ್ಳಿ',
  'Upload it on the e-way bill portal (Generate in bulk). The portal gives you a 12-digit number: save it here.': 'ಇದನ್ನು ಇ-ವೇ ಬಿಲ್ ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ (ಬಲ್ಕ್‌ನಲ್ಲಿ ಜನರೇಟ್ ಮಾಡಿ). ಪೋರ್ಟಲ್ 12 ಅಂಕಿಯ ಸಂಖ್ಯೆ ನೀಡುತ್ತದೆ: ಅದನ್ನು ಇಲ್ಲಿ ಉಳಿಸಿ.',
  'E-way bill number': 'ಇ-ವೇ ಬಿಲ್ ಸಂಖ್ಯೆ',
