  // Stock counts
  'Scan the shelf and see what differs': 'ಶೆಲ್ಫ್ ಸ್ಕ್ಯಾನ್ ಮಾಡಿ ವ್ಯತ್ಯಾಸ ನೋಡಿ',
  'Stock counts': 'ಸ್ಟಾಕ್ ಎಣಿಕೆಗಳು',
  'Walk the shelf, scan each product once per unit, and see what differs from the system before anything changes.': 'ಶೆಲ್ಫ್ ಉದ್ದಕ್ಕೂ ನಡೆದು, ಪ್ರತಿ ಘಟಕಕ್ಕೆ ಒಮ್ಮೆ ಉತ್ಪನ್ನ ಸ್ಕ್ಯಾನ್ ಮಾಡಿ, ಏನಾದರೂ ಬದಲಾಗುವ ಮೊದಲು ಸಿಸ್ಟಮ್‌ನಿಂದ ಏನು ಭಿನ್ನ ಎಂದು ನೋಡಿ.',
  'Count stock': 'ಸ್ಟಾಕ್ ಎಣಿಸಿ',
  'Start counting': 'ಎಣಿಕೆ ಆರಂಭಿಸಿ',
  'No stock counts yet.': 'ಇನ್ನೂ ಸ್ಟಾಕ್ ಎಣಿಕೆಗಳಿಲ್ಲ.',
  'In progress': 'ನಡೆಯುತ್ತಿದೆ',
  'Whole store': 'ಇಡೀ ಅಂಗಡಿ',
