  'So you can tell counts apart later, like “Aisle 3” or “Month end”.': 'ನಂತರ ಎಣಿಕೆಗಳನ್ನು ಗುರುತಿಸಲು, ಉದಾ. “ಐಸಲ್ 3” ಅಥವಾ “ತಿಂಗಳ ಕೊನೆ”.',
