  'The whole store': 'ಇಡೀ ಅಂಗಡಿ',
  'Give the count a name (up to 80 characters)': 'ಎಣಿಕೆಗೆ ಹೆಸರು ನೀಡಿ (80 ಅಕ್ಷರಗಳವರೆಗೆ)',
