  'Allow the camera so FlowXP can read barcodes. It does not take or keep photos.': 'FlowXP ಬಾರ್‌ಕೋಡ್ ಓದಲು ಕ್ಯಾಮೆರಾಗೆ ಅನುಮತಿ ನೀಡಿ. ಇದು ಫೋಟೋ ತೆಗೆಯುವುದಿಲ್ಲ, ಇಟ್ಟುಕೊಳ್ಳುವುದಿಲ್ಲ.',
