  'Net revenue is what was billed before tax, minus discounts and refunds. Cancelled invoices are left out. Food cost is the ingredient cost recorded on each bill when it was made. Fees, commission and packaging use your assumptions: unset means zero. Contribution is what each sale leaves toward rent, salaries and other fixed costs.': 'ನಿವ್ವಳ ಆದಾಯ ಎಂದರೆ ತೆರಿಗೆಗೆ ಮೊದಲು ಬಿಲ್ ಮಾಡಿದ್ದು, ರಿಯಾಯಿತಿ ಮತ್ತು ಮರುಪಾವತಿ ಕಳೆದು. ರದ್ದಾದ ಇನ್‌ವಾಯ್ಸ್‌ಗಳನ್ನು ಬಿಡಲಾಗುತ್ತದೆ. ಆಹಾರ ವೆಚ್ಚ ಎಂದರೆ ಪ್ರತಿ ಬಿಲ್ ಮಾಡಿದಾಗ ದಾಖಲಾದ ಪದಾರ್ಥ ವೆಚ್ಚ. ಶುಲ್ಕ, ಕಮಿಷನ್, ಪ್ಯಾಕೇಜಿಂಗ್ ನಿಮ್ಮ ಊಹೆಗಳನ್ನು ಬಳಸುತ್ತವೆ: ಹೊಂದಿಸದಿದ್ದರೆ ಶೂನ್ಯ. ಬಾಡಿಗೆ, ಸಂಬಳ, ಇತರ ಸ್ಥಿರ ವೆಚ್ಚಗಳಿಗೆ ಪ್ರತಿ ಮಾರಾಟ ಉಳಿಸುವುದು ಕೊಡುಗೆ.',
  'What to expect, and what to have in the kitchen for it.': 'ಏನು ನಿರೀಕ್ಷಿಸಬೇಕು, ಅದಕ್ಕಾಗಿ ಅಡುಗೆಮನೆಯಲ್ಲಿ ಏನಿರಬೇಕು.',
