  // Forecast
  'Forecasting needs at least three weeks of history for the same weekday. You have {n} trading days so far. Check back as history builds.': 'ಮುನ್ಸೂಚನೆಗೆ ಅದೇ ವಾರದ ದಿನದ ಕನಿಷ್ಠ ಮೂರು ವಾರಗಳ ಇತಿಹಾಸ ಬೇಕು. ಇಲ್ಲಿಯವರೆಗೆ ನಿಮಗೆ {n} ವ್ಯಾಪಾರ ದಿನಗಳಿವೆ. ಇತಿಹಾಸ ಬೆಳೆದಂತೆ ಮತ್ತೆ ನೋಡಿ.',
  // Gym plans and settings
  'What you sell. Each membership keeps the rules it was sold with, so changing a plan only affects the next sale.': 'ನೀವು ಮಾರುವುದು. ಪ್ರತಿ ಸದಸ್ಯತ್ವ ಮಾರಿದಾಗಿನ ನಿಯಮಗಳನ್ನೇ ಉಳಿಸಿಕೊಳ್ಳುತ್ತದೆ, ಆದ್ದರಿಂದ ಪ್ಲಾನ್ ಬದಲಾಯಿಸುವುದು ಮುಂದಿನ ಮಾರಾಟವನ್ನು ಮಾತ್ರ ಪ್ರಭಾವಿಸುತ್ತದೆ.',
