  'Cannot be frozen': 'ಫ್ರೀಜ್ ಮಾಡಲಾಗದು',
  'Edit {name}': '{name} ತಿದ್ದಿ',
  'Changing a plan does not change memberships already sold: each keeps the rules it was sold with.': 'ಪ್ಲಾನ್ ಬದಲಾಯಿಸುವುದರಿಂದ ಈಗಾಗಲೇ ಮಾರಿದ ಸದಸ್ಯತ್ವಗಳು ಬದಲಾಗುವುದಿಲ್ಲ: ಪ್ರತಿಯೊಂದೂ ಮಾರಿದಾಗಿನ ನಿಯಮಗಳನ್ನೇ ಉಳಿಸಿಕೊಳ್ಳುತ್ತದೆ.',
  'Monthly, Student quarterly, Off-peak annual': 'ಮಾಸಿಕ, ವಿದ್ಯಾರ್ಥಿ ತ್ರೈಮಾಸಿಕ, ಆಫ್-ಪೀಕ್ ವಾರ್ಷಿಕ',
  'Who it is for': 'ಇದು ಯಾರಿಗಾಗಿ',
