  'Price (₹, before GST)': 'ಬೆಲೆ (₹, GSTಗೆ ಮೊದಲು)',
  'GST rate': 'GST ದರ',
  'Gym memberships are usually 18%.': 'ಜಿಮ್ ಸದಸ್ಯತ್ವಗಳಿಗೆ ಸಾಮಾನ್ಯವಾಗಿ 18%.',
  'Description (optional)': 'ವಿವರಣೆ (ಐಚ್ಛಿಕ)',
  'People covered': 'ಒಳಗೊಂಡ ಜನರು',
  'Payment and access': 'ಪಾವತಿ ಮತ್ತು ಪ್ರವೇಶ',
  'Can they come in before they have paid?': 'ಪಾವತಿಸುವ ಮೊದಲು ಅವರು ಒಳಗೆ ಬರಬಹುದೇ?',
  'Days they can come in before paying': 'ಪಾವತಿಸುವ ಮೊದಲು ಅವರು ಬರಬಹುದಾದ ದಿನಗಳು',
  'Grace days after it ends (optional)': 'ಮುಗಿದ ನಂತರದ ಗ್ರೇಸ್ ದಿನಗಳು (ಐಚ್ಛಿಕ)',
  'Empty uses the gym\'s default. 0 means none for this plan.': 'ಖಾಲಿ ಬಿಟ್ಟರೆ ಜಿಮ್‌ನ ಡೀಫಾಲ್ಟ್ ಬಳಕೆಯಾಗುತ್ತದೆ. 0 ಎಂದರೆ ಈ ಪ್ಲಾನ್‌ಗೆ ಯಾವುದೂ ಇಲ್ಲ.',
  'Where and when it works': 'ಇದು ಎಲ್ಲಿ ಮತ್ತು ಯಾವಾಗ ಕೆಲಸ ಮಾಡುತ್ತದೆ',
  'Branches': 'ಶಾಖೆಗಳು',
  'Only at certain times (an off-peak plan)': 'ನಿರ್ದಿಷ್ಟ ಸಮಯಗಳಲ್ಲಿ ಮಾತ್ರ (ಆಫ್-ಪೀಕ್ ಪ್ಲಾನ್)',
  'From': 'ಇಂದ',
  'To': 'ವರೆಗೆ',
  'Members can freeze it': 'ಸದಸ್ಯರು ಇದನ್ನು ಫ್ರೀಜ್ ಮಾಡಬಹುದು',
  'Most days they can freeze in all': 'ಒಟ್ಟಾರೆ ಅವರು ಫ್ರೀಜ್ ಮಾಡಬಹುದಾದ ಗರಿಷ್ಠ ದಿನಗಳು',
