  'Create plan': 'ಪ್ಲಾನ್ ರಚಿಸಿ',
  'Gym settings': 'ಜಿಮ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು',
  'The rules for coming in, each branch\'s hours, and the entrance QR.': 'ಒಳಗೆ ಬರುವ ನಿಯಮಗಳು, ಪ್ರತಿ ಶಾಖೆಯ ಸಮಯ ಮತ್ತು ಪ್ರವೇಶ QR.',
  'Rules': 'ನಿಯಮಗಳು',
  'Branches and QR': 'ಶಾಖೆಗಳು ಮತ್ತು QR',
  'Check-in rules': 'ಚೆಕ್-ಇನ್ ನಿಯಮಗಳು',
  'Every way in follows these: the desk, the member\'s phone and the gates.': 'ಒಳಗೆ ಬರುವ ಪ್ರತಿ ದಾರಿ ಇವುಗಳನ್ನು ಅನುಸರಿಸುತ್ತದೆ: ಡೆಸ್ಕ್, ಸದಸ್ಯರ ಫೋನ್ ಮತ್ತು ಗೇಟ್‌ಗಳು.',
  'Grace days after a membership ends': 'ಸದಸ್ಯತ್ವ ಮುಗಿದ ನಂತರದ ಗ್ರೇಸ್ ದಿನಗಳು',
  'Ignore a repeat scan for (seconds)': 'ಪುನರಾವರ್ತಿತ ಸ್ಕ್ಯಾನ್ ಅನ್ನು ಇಷ್ಟು ಹೊತ್ತು ನಿರ್ಲಕ್ಷಿಸಿ (ಸೆಕೆಂಡುಗಳು)',
  'Same card at two branches within (minutes)': 'ಒಂದೇ ಕಾರ್ಡ್ ಎರಡು ಶಾಖೆಗಳಲ್ಲಿ ಇಷ್ಟು ನಿಮಿಷಗಳೊಳಗೆ',
  'Record check-out as well as check-in': 'ಚೆಕ್-ಇನ್ ಜೊತೆಗೆ ಚೆಕ್-ಔಟ್ ಅನ್ನೂ ದಾಖಲಿಸಿ',
  'Shows who is in the gym now.': 'ಈಗ ಜಿಮ್‌ನಲ್ಲಿ ಯಾರಿದ್ದಾರೆ ಎಂದು ತೋರಿಸುತ್ತದೆ.',
  'The desk confirms every scan by looking at the member': 'ಡೆಸ್ಕ್ ಸದಸ್ಯರನ್ನು ನೋಡಿ ಪ್ರತಿ ಸ್ಕ್ಯಾನ್ ದೃಢೀಕರಿಸುತ್ತದೆ',
  'Members on their own phone': 'ಸದಸ್ಯರು ತಮ್ಮ ಫೋನ್‌ನಲ್ಲಿ',
  'A member signs in with a code sent to their phone, then shows a pass or checks in themselves. No app to install.': 'ಸದಸ್ಯರು ಫೋನ್‌ಗೆ ಕಳುಹಿಸಿದ ಕೋಡ್‌ನೊಂದಿಗೆ ಸೈನ್ ಇನ್ ಮಾಡಿ, ಪಾಸ್ ತೋರಿಸುತ್ತಾರೆ ಅಥವಾ ತಾವೇ ಚೆಕ್-ಇನ್ ಮಾಡುತ್ತಾರೆ. ಆ್ಯಪ್ ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಬೇಕಿಲ್ಲ.',
  'Let members check in from their own phone': 'ಸದಸ್ಯರು ತಮ್ಮ ಫೋನ್‌ನಿಂದ ಚೆಕ್-ಇನ್ ಮಾಡಲು ಬಿಡಿ',
  'They scan the poster at the door with their phone\'s camera.': 'ಅವರು ತಮ್ಮ ಫೋನ್ ಕ್ಯಾಮೆರಾದಿಂದ ಬಾಗಿಲಲ್ಲಿರುವ ಪೋಸ್ಟರ್ ಸ್ಕ್ಯಾನ್ ಮಾಡುತ್ತಾರೆ.',
  'Also ask for today\'s front-desk code': 'ಇಂದಿನ ಫ್ರಂಟ್-ಡೆಸ್ಕ್ ಕೋಡ್ ಸಹ ಕೇಳಿ',
  'Ask for a fresh sign-in code every time': 'ಪ್ರತಿ ಬಾರಿ ಹೊಸ ಸೈನ್-ಇನ್ ಕೋಡ್ ಕೇಳಿ',
  'A code counts for (minutes)': 'ಒಂದು ಕೋಡ್ ಎಷ್ಟು ಹೊತ್ತು ಮಾನ್ಯ (ನಿಮಿಷಗಳು)',
  'The gym\'s web address': 'ಜಿಮ್‌ನ ವೆಬ್ ವಿಳಾಸ',
  'Letters, digits and hyphens. Needed for members to sign in.': 'ಅಕ್ಷರಗಳು, ಅಂಕೆಗಳು ಮತ್ತು ಹೈಫನ್‌ಗಳು. ಸದಸ್ಯರು ಸೈನ್ ಇನ್ ಮಾಡಲು ಬೇಕು.',
  'Member number starts with': 'ಸದಸ್ಯ ಸಂಖ್ಯೆ ಇದರಿಂದ ಆರಂಭ',
  'Stay signed in for (days)': 'ಇಷ್ಟು ದಿನ ಸೈನ್ ಇನ್ ಆಗಿರಿ',
  'A phone pass QR lasts (seconds)': 'ಫೋನ್ ಪಾಸ್ QR ಎಷ್ಟು ಹೊತ್ತು ಇರುತ್ತದೆ (ಸೆಕೆಂಡುಗಳು)',
  'Classes': 'ಕ್ಲಾಸ್‌ಗಳು',
  'How booking works for members and the desk.': 'ಸದಸ್ಯರು ಮತ್ತು ಡೆಸ್ಕ್‌ಗೆ ಬುಕಿಂಗ್ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ.',
  'Cancel a class free until (hours before)': 'ಕ್ಲಾಸ್ ಉಚಿತವಾಗಿ ರದ್ದುಮಾಡಬಹುದು, ಇಷ್ಟು ಗಂಟೆ ಮೊದಲಿನವರೆಗೆ',
  'Cancel personal training free until (hours before)': 'ಪರ್ಸನಲ್ ಟ್ರೈನಿಂಗ್ ಉಚಿತವಾಗಿ ರದ್ದುಮಾಡಬಹುದು, ಇಷ್ಟು ಗಂಟೆ ಮೊದಲಿನವರೆಗೆ',
  'Members can book up to (days ahead)': 'ಸದಸ್ಯರು ಇಷ್ಟು ದಿನ ಮೊದಲಿನವರೆಗೆ ಬುಕ್ ಮಾಡಬಹುದು',
  'A full class has a waitlist': 'ತುಂಬಿದ ಕ್ಲಾಸ್‌ಗೆ ಕಾಯುವ ಪಟ್ಟಿ ಇರುತ್ತದೆ',
  'Save settings': 'ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಉಳಿಸಿ',
  'Opening hours': 'ತೆರೆಯುವ ಸಮಯ',
  'Nobody is let in outside these hours, whatever their plan.': 'ಈ ಸಮಯದ ಹೊರಗೆ ಯಾರನ್ನೂ ಒಳಗೆ ಬಿಡುವುದಿಲ್ಲ, ಅವರ ಪ್ಲಾನ್ ಏನೇ ಆಗಿರಲಿ.',
  'Open all day, every day': 'ಪ್ರತಿ ದಿನ ಇಡೀ ದಿನ ತೆರೆದಿರುತ್ತದೆ',
  'Opens': 'ತೆರೆಯುತ್ತದೆ',
  'Closes': 'ಮುಚ್ಚುತ್ತದೆ',
  'Holidays (closed all day)': 'ರಜೆಗಳು (ಇಡೀ ದಿನ ಮುಚ್ಚಿರುತ್ತದೆ)',
  'One date a line, like 2026-11-08.': 'ಒಂದು ಸಾಲಿಗೆ ಒಂದು ದಿನಾಂಕ, ಉದಾ. 2026-11-08.',
  'Save hours': 'ಸಮಯ ಉಳಿಸಿ',
  'Entrance QR': 'ಪ್ರವೇಶ QR',
  'Put this poster at the door. It only opens the check-in page for this branch.': 'ಈ ಪೋಸ್ಟರ್ ಅನ್ನು ಬಾಗಿಲಲ್ಲಿ ಇಡಿ. ಇದು ಈ ಶಾಖೆಯ ಚೆಕ್-ಇನ್ ಪುಟವನ್ನು ಮಾತ್ರ ತೆರೆಯುತ್ತದೆ.',
  'Check in here': 'ಇಲ್ಲಿ ಚೆಕ್-ಇನ್ ಮಾಡಿ',
  'Scan with your phone\'s camera. Sign in with the code we send you, then tap Check in.': 'ನಿಮ್ಮ ಫೋನ್‌ನ ಕ್ಯಾಮೆರಾದಿಂದ ಸ್ಕ್ಯಾನ್ ಮಾಡಿ. ನಾವು ಕಳುಹಿಸುವ ಕೋಡ್‌ನೊಂದಿಗೆ ಸೈನ್ ಇನ್ ಮಾಡಿ, ನಂತರ ಚೆಕ್-ಇನ್ ಟ್ಯಾಪ್ ಮಾಡಿ.',
  'New QR': 'ಹೊಸ QR',
  'Make a new entrance QR?': 'ಹೊಸ ಪ್ರವೇಶ QR ಮಾಡಬೇಕೇ?',
  'The poster on the wall stops working. Print the new one and put it up. Use this if the old poster was copied or spread around.': 'ಗೋಡೆಯ ಮೇಲಿನ ಪೋಸ್ಟರ್ ಕೆಲಸ ಮಾಡುವುದು ನಿಲ್ಲಿಸುತ್ತದೆ. ಹೊಸದನ್ನು ಪ್ರಿಂಟ್ ಮಾಡಿ ಹಾಕಿ. ಹಳೆಯ ಪೋಸ್ಟರ್ ನಕಲಾಗಿದ್ದರೆ ಅಥವಾ ಹರಡಿದ್ದರೆ ಇದನ್ನು ಬಳಸಿ.',
  'Make a new QR': 'ಹೊಸ QR ಮಾಡಿ',
  'New QR made. Print it now.': 'ಹೊಸ QR ಮಾಡಲಾಗಿದೆ. ಈಗಲೇ ಪ್ರಿಂಟ್ ಮಾಡಿ.',
  'Phone check-in is switched off. Turn it on under Rules before putting the poster up.': 'ಫೋನ್ ಚೆಕ್-ಇನ್ ಆಫ್ ಆಗಿದೆ. ಪೋಸ್ಟರ್ ಹಾಕುವ ಮೊದಲು ನಿಯಮಗಳಲ್ಲಿ ಇದನ್ನು ಆನ್ ಮಾಡಿ.',
