  'Add a monthly plan to start selling memberships.': 'ಸದಸ್ಯತ್ವ ಮಾರಾಟ ಆರಂಭಿಸಲು ಮಾಸಿಕ ಪ್ಲಾನ್ ಸೇರಿಸಿ.',
  'Anyone': 'ಯಾರಾದರೂ',
