  'The length is a whole number of days, 1 or more': 'ಅವಧಿ ದಿನಗಳ ಪೂರ್ಣ ಸಂಖ್ಯೆ, 1 ಅಥವಾ ಹೆಚ್ಚು',
  'Enter the price (before GST)': 'ಬೆಲೆ ನಮೂದಿಸಿ (ಜಿಎಸ್‌ಟಿಗೆ ಮೊದಲು)',
  'The GST rate is a percentage from 0 to 100': 'ಜಿಎಸ್‌ಟಿ ದರ 0 ರಿಂದ 100 ರ ನಡುವಿನ ಶೇಕಡಾ',
  'People covered is a whole number, 1 or more': 'ಒಳಗೊಂಡ ಜನರು ಪೂರ್ಣ ಸಂಖ್ಯೆ, 1 ಅಥವಾ ಹೆಚ್ಚು',
  'Days before paying is a whole number, 1 or more': 'ಪಾವತಿಸುವ ಮೊದಲಿನ ದಿನಗಳು ಪೂರ್ಣ ಸಂಖ್ಯೆ, 1 ಅಥವಾ ಹೆಚ್ಚು',
  'Grace days is a whole number, or empty to use the gym\'s default': 'ಗ್ರೇಸ್ ದಿನಗಳು ಪೂರ್ಣ ಸಂಖ್ಯೆ, ಅಥವಾ ಜಿಮ್‌ನ ಡೀಫಾಲ್ಟ್‌ಗೆ ಖಾಲಿ ಬಿಡಿ',
  'Most freeze days is a whole number, 1 or more': 'ಗರಿಷ್ಠ ಫ್ರೀಜ್ ದಿನಗಳು ಪೂರ್ಣ ಸಂಖ್ಯೆ, 1 ಅಥವಾ ಹೆಚ್ಚು',
