  'Printed cards can be lent to a friend. With this on, the desk sees the member\'s photo and confirms.': 'ಮುದ್ರಿತ ಕಾರ್ಡ್‌ಗಳನ್ನು ಸ್ನೇಹಿತರಿಗೆ ಕೊಡಬಹುದು. ಇದನ್ನು ಆನ್ ಮಾಡಿದರೆ ಡೆಸ್ಕ್ ಸದಸ್ಯರ ಫೋಟೋ ನೋಡಿ ದೃಢೀಕರಿಸುತ್ತದೆ.',
