  'The address is 3 to 40 letters, digits or hyphens': 'ವಿಳಾಸ 3 ರಿಂದ 40 ಅಕ್ಷರಗಳು, ಅಂಕೆಗಳು ಅಥವಾ ಹೈಫನ್‌ಗಳು',
