  '{date} is not a date. Write one a line, like 2026-11-08.': '{date} ದಿನಾಂಕವಲ್ಲ. ಒಂದು ಸಾಲಿಗೆ ಒಂದು ಬರೆಯಿರಿ, ಉದಾ. 2026-11-08.',
