  'Its own hours': 'ಇದರ ಸ್ವಂತ ಸಮಯ',
  'Online booking': 'ಆನ್‌ಲೈನ್ ಬುಕಿಂಗ್',
  'A page clients can use to book themselves, without calling. It follows your opening hours, team hours, leave and booking rules.': 'ಕರೆ ಮಾಡದೆ ಗ್ರಾಹಕರು ತಾವೇ ಬುಕ್ ಮಾಡಬಹುದಾದ ಪುಟ. ಇದು ನಿಮ್ಮ ತೆರೆಯುವ ಸಮಯ, ತಂಡದ ಸಮಯ, ರಜೆ ಮತ್ತು ಬುಕಿಂಗ್ ನಿಯಮಗಳನ್ನು ಅನುಸರಿಸುತ್ತದೆ.',
  'Let clients book online': 'ಗ್ರಾಹಕರು ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಬುಕ್ ಮಾಡಲು ಬಿಡಿ',
