  'Letters, numbers and dashes. This becomes part of the link.': 'ಅಕ್ಷರಗಳು, ಸಂಖ್ಯೆಗಳು ಮತ್ತು ಡ್ಯಾಶ್‌ಗಳು. ಇದು ಲಿಂಕ್‌ನ ಭಾಗವಾಗುತ್ತದೆ.',
  'Message at the top of the page': 'ಪುಟದ ಮೇಲ್ಭಾಗದ ಸಂದೇಶ',
  'Optional — parking, what to bring, a festive notice.': 'ಐಚ್ಛಿಕ — ಪಾರ್ಕಿಂಗ್, ಏನು ತರಬೇಕು, ಹಬ್ಬದ ಸೂಚನೆ.',
  'Online bookings arrive as Booked appointments marked Online. One mobile number can hold up to three upcoming online bookings.': 'ಆನ್‌ಲೈನ್ ಬುಕಿಂಗ್‌ಗಳು ಆನ್‌ಲೈನ್ ಎಂದು ಗುರುತಿಸಿದ ಬುಕ್ಡ್ ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್‌ಗಳಾಗಿ ಬರುತ್ತವೆ. ಒಂದು ಮೊಬೈಲ್ ಸಂಖ್ಯೆಗೆ ಗರಿಷ್ಠ ಮೂರು ಮುಂಬರುವ ಆನ್‌ಲೈನ್ ಬುಕಿಂಗ್‌ಗಳಿರಬಹುದು.',
