  'Worked out on the service’s list price, since nothing is charged at the time.': 'ಆ ಸಮಯದಲ್ಲಿ ಏನೂ ಶುಲ್ಕ ವಿಧಿಸದ ಕಾರಣ ಸೇವೆಯ ಪಟ್ಟಿ ಬೆಲೆಯ ಮೇಲೆ ಲೆಕ್ಕಹಾಕಲಾಗಿದೆ.',
