  'Points per ₹100, what a point is worth, and the most a bill can be paid with points.': '₹100ಕ್ಕೆ ಪಾಯಿಂಟ್‌ಗಳು, ಒಂದು ಪಾಯಿಂಟ್‌ನ ಮೌಲ್ಯ, ಪಾಯಿಂಟ್‌ಗಳಿಂದ ಬಿಲ್‌ನಲ್ಲಿ ಪಾವತಿಸಬಹುದಾದ ಗರಿಷ್ಠ.',
  'Earning rates by kind of sale': 'ಮಾರಾಟದ ವಿಧದ ಪ್ರಕಾರ ಗಳಿಕೆ ದರಗಳು',
  'Leave the rate empty to use the programme’s rate. Turn a kind off and it earns nothing. Gift cards never earn.': 'ಕಾರ್ಯಕ್ರಮದ ದರ ಬಳಸಲು ದರವನ್ನು ಖಾಲಿ ಬಿಡಿ. ಒಂದು ವಿಧವನ್ನು ಆಫ್ ಮಾಡಿದರೆ ಏನೂ ಗಳಿಸದು. ಗಿಫ್ಟ್ ಕಾರ್ಡ್‌ಗಳು ಎಂದಿಗೂ ಗಳಿಸುವುದಿಲ್ಲ.',
