  'Points per ₹100': '₹100ಕ್ಕೆ ಪಾಯಿಂಟ್‌ಗಳು',
  'Earns points': 'ಪಾಯಿಂಟ್ ಗಳಿಸುತ್ತದೆ',
  'Expiry': 'ಅವಧಿ',
  'How long points last. Empty means they never expire.': 'ಪಾಯಿಂಟ್‌ಗಳು ಎಷ್ಟು ಕಾಲ ಇರುತ್ತವೆ. ಖಾಲಿ ಎಂದರೆ ಎಂದಿಗೂ ಮುಕ್ತಾಯವಾಗುವುದಿಲ್ಲ.',
  'Points expire on their own once a day. Clients are warned first if the Loyalty points expiry message is on under Messages.': 'ಪಾಯಿಂಟ್‌ಗಳು ದಿನಕ್ಕೆ ಒಮ್ಮೆ ತಾನಾಗಿ ಮುಕ್ತಾಯವಾಗುತ್ತವೆ. ಸಂದೇಶಗಳ ಅಡಿಯಲ್ಲಿ ಲಾಯಲ್ಟಿ ಪಾಯಿಂಟ್ ಮುಕ್ತಾಯ ಸಂದೇಶ ಆನ್ ಆಗಿದ್ದರೆ ಗ್ರಾಹಕರಿಗೆ ಮೊದಲು ಎಚ್ಚರಿಕೆ ನೀಡಲಾಗುತ್ತದೆ.',
  'Expire old points now': 'ಹಳೆಯ ಪಾಯಿಂಟ್‌ಗಳನ್ನು ಈಗಲೇ ಮುಕ್ತಾಯಗೊಳಿಸಿ',
  'Expire old points now?': 'ಹಳೆಯ ಪಾಯಿಂಟ್‌ಗಳನ್ನು ಈಗಲೇ ಮುಕ್ತಾಯಗೊಳಿಸಬೇಕೇ?',
  'Points older than the expiry period are taken off clients’ balances. Running it twice changes nothing more.': 'ಮುಕ್ತಾಯ ಅವಧಿಗಿಂತ ಹಳೆಯ ಪಾಯಿಂಟ್‌ಗಳನ್ನು ಗ್ರಾಹಕರ ಬ್ಯಾಲೆನ್ಸ್‌ನಿಂದ ತೆಗೆಯಲಾಗುತ್ತದೆ. ಎರಡು ಬಾರಿ ನಡೆಸಿದರೂ ಹೆಚ್ಚೇನೂ ಬದಲಾಗುವುದಿಲ್ಲ.',
  'Expire points': 'ಪಾಯಿಂಟ್‌ಗಳನ್ನು ಮುಕ್ತಾಯಗೊಳಿಸಿ',
