  'The price you type is what the client pays; GST is worked out from inside it.': 'ನೀವು ಟೈಪ್ ಮಾಡುವ ಬೆಲೆಯನ್ನೇ ಗ್ರಾಹಕರು ಪಾವತಿಸುತ್ತಾರೆ; ಜಿಎಸ್‌ಟಿ ಅದರೊಳಗಿಂದ ಲೆಕ್ಕ ಹಾಕಲಾಗುತ್ತದೆ.',
