  'Free goods and discounts for shops: who gets them, when, and what they cost': 'ಅಂಗಡಿಗಳಿಗೆ ಉಚಿತ ಸರಕು ಮತ್ತು ರಿಯಾಯಿತಿ: ಯಾರಿಗೆ, ಯಾವಾಗ, ಎಷ್ಟು ವೆಚ್ಚ',
