  'Make an offer: buy 10 cartons, get 1 free; 5% off 100 units; ₹2,000 off an order above ₹50,000.': 'ಆಫರ್ ಮಾಡಿ: 10 ಕಾರ್ಟನ್ ಖರೀದಿಸಿದರೆ 1 ಉಚಿತ; 100 ಘಟಕಗಳಿಗೆ 5% ರಿಯಾಯಿತಿ; ₹50,000 ಮೇಲಿನ ಆರ್ಡರ್‌ಗೆ ₹2,000 ರಿಯಾಯಿತಿ.',
  'Tell qualifying shops?': 'ಅರ್ಹ ಅಂಗಡಿಗಳಿಗೆ ತಿಳಿಸಬೇಕೆ?',
  'A message goes out through your messaging channel to every shop that qualifies. Those who opted out are skipped.': 'ಅರ್ಹ ಪ್ರತಿ ಅಂಗಡಿಗೆ ನಿಮ್ಮ ಮೆಸೇಜಿಂಗ್ ಚಾನೆಲ್ ಮೂಲಕ ಸಂದೇಶ ಹೋಗುತ್ತದೆ. ಬೇಡವೆಂದವರನ್ನು ಬಿಡಲಾಗುತ್ತದೆ.',
  'Tell the shops': 'ಅಂಗಡಿಗಳಿಗೆ ತಿಳಿಸಿ',
  'A scheme that orders have used can only be switched off.': 'ಆರ್ಡರ್‌ಗಳು ಬಳಸಿದ ಸ್ಕೀಮ್ ಅನ್ನು ಆಫ್ ಮಾಡಲು ಮಾತ್ರ ಸಾಧ್ಯ.',
  'Name or barcode': 'ಹೆಸರು ಅಥವಾ ಬಾರ್‌ಕೋಡ್',
  'Leave empty to give the same product free.': 'ಅದೇ ಉತ್ಪನ್ನವನ್ನು ಉಚಿತವಾಗಿ ನೀಡಲು ಖಾಲಿ ಬಿಡಿ.',
  'Choose a free product, as this scheme is not for one product.': 'ಈ ಸ್ಕೀಮ್ ಒಂದು ಉತ್ಪನ್ನಕ್ಕಲ್ಲದ ಕಾರಣ ಉಚಿತ ಉತ್ಪನ್ನವನ್ನು ಆರಿಸಿ.',
  'Buy 30 with a 10+1 scheme: 3 free; otherwise 1': '10+1 ಸ್ಕೀಮ್‌ನಲ್ಲಿ 30 ಖರೀದಿಸಿದರೆ 3 ಉಚಿತ; ಇಲ್ಲದಿದ್ದರೆ 1',
  'Discount (%)': 'ರಿಯಾಯಿತಿ (%)',
