  'A principal': 'ಒಬ್ಬ ಪ್ರಿನ್ಸಿಪಾಲ್',
  'You claim the cost back from them': 'ವೆಚ್ಚವನ್ನು ನೀವು ಅವರಿಂದ ಮರಳಿ ಪಡೆಯುತ್ತೀರಿ',
  'Only named shops and territories are set on the web. A scheme you edit here keeps the ones it has.': 'ಹೆಸರಿಸಿದ ಅಂಗಡಿಗಳು ಮತ್ತು ಟೆರಿಟರಿಗಳನ್ನು ವೆಬ್‌ನಲ್ಲಿ ಹೊಂದಿಸಲಾಗುತ್ತದೆ. ಇಲ್ಲಿ ಬದಲಿಸಿದ ಸ್ಕೀಮ್ ಇರುವವನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತದೆ.',
  'Sales team': 'ಮಾರಾಟ ತಂಡ',
  'Your salespeople, their targets and what they earn': 'ನಿಮ್ಮ ಮಾರಾಟ ಸಿಬ್ಬಂದಿ, ಅವರ ಗುರಿಗಳು ಮತ್ತು ಅವರ ಗಳಿಕೆ',
