  'As it is': 'ಇದ್ದಂತೆ',
  'Linking a sign-in account is done on the web.': 'ಸೈನ್-ಇನ್ ಖಾತೆಯನ್ನು ಲಿಂಕ್ ಮಾಡುವುದನ್ನು ವೆಬ್‌ನಲ್ಲಿ ಮಾಡಲಾಗುತ್ತದೆ.',
  'Targets running today. Setting one again for the same period changes it; it never adds a second.': 'ಇಂದು ನಡೆಯುತ್ತಿರುವ ಗುರಿಗಳು. ಅದೇ ಅವಧಿಗೆ ಮತ್ತೆ ಹೊಂದಿಸಿದರೆ ಅದು ಬದಲಾಗುತ್ತದೆ; ಎರಡನೆಯದು ಸೇರುವುದಿಲ್ಲ.',
