  'Target saved': 'ಗುರಿ ಉಳಿಸಲಾಗಿದೆ',
  'Each sold line earns under the most specific rule that fits. Without rules each person earns their own default percentage.': 'ಮಾರಾಟವಾದ ಪ್ರತಿ ಸಾಲು ಅತ್ಯಂತ ಹೊಂದುವ ನಿಯಮದಂತೆ ಗಳಿಸುತ್ತದೆ. ನಿಯಮಗಳಿಲ್ಲದಿದ್ದರೆ ಪ್ರತಿಯೊಬ್ಬರೂ ತಮ್ಮ ಡೀಫಾಲ್ಟ್ ಶೇಕಡಾ ಗಳಿಸುತ್ತಾರೆ.',
