  'Restored bills do not change the shelf. If goods were lost, count your stock.': 'ಮರುಸ್ಥಾಪಿಸಿದ ಬಿಲ್‌ಗಳು ಶೆಲ್ಫ್ ಸ್ಟಾಕ್ ಅನ್ನು ಬದಲಿಸುವುದಿಲ್ಲ. ಸರಕು ಕಳೆದುಹೋಗಿದ್ದರೆ ಸ್ಟಾಕ್ ಎಣಿಸಿ.',
