  '{n} skipped': '{n} ಬಿಡಲಾಗಿದೆ',
  'row {n}': 'ಸಾಲು {n}',
  'Put back what a backup has and this business does not': 'ಬ್ಯಾಕಪ್‌ನಲ್ಲಿ ಇದ್ದು ಈ ವ್ಯವಹಾರದಲ್ಲಿ ಇಲ್ಲದ್ದನ್ನು ಮರುಸ್ಥಾಪಿಸಿ',
  'Only the owner can restore from a backup.': 'ಮಾಲೀಕರು ಮಾತ್ರ ಬ್ಯಾಕಪ್‌ನಿಂದ ಮರುಸ್ಥಾಪಿಸಬಹುದು.',
  'Choose the ZIP file you downloaded before. Restoring only adds what is missing. Nothing that is already in FlowXP is changed or removed, so it is safe to run twice.': 'ಮೊದಲು ಡೌನ್‌ಲೋಡ್ ಮಾಡಿದ ZIP ಫೈಲ್ ಆರಿಸಿ. ಮರುಸ್ಥಾಪನೆ ಇಲ್ಲದಿರುವುದನ್ನು ಮಾತ್ರ ಸೇರಿಸುತ್ತದೆ. FlowXP ನಲ್ಲಿ ಈಗಾಗಲೇ ಇರುವ ಯಾವುದೂ ಬದಲಾಗುವುದಿಲ್ಲ ಅಥವಾ ತೆಗೆಯಲ್ಪಡುವುದಿಲ್ಲ, ಆದ್ದರಿಂದ ಎರಡು ಬಾರಿ ಮಾಡುವುದು ಸುರಕ್ಷಿತ.',
  'Make the restore?': 'ಮರುಸ್ಥಾಪನೆ ಮಾಡಬೇಕೆ?',
