  'A bin is one small place on a rack where a part sits.': 'ಬಿನ್ ಎಂದರೆ ರ‍್ಯಾಕ್‌ನಲ್ಲಿ ಒಂದು ಭಾಗ ಇಡುವ ಚಿಕ್ಕ ಜಾಗ.',
  'Create racks and bins': 'ರ‍್ಯಾಕ್‌ಗಳು ಮತ್ತು ಬಿನ್‌ಗಳನ್ನು ರಚಿಸಿ',
  'This makes {racks} racks and {total} bins. The first bin will be called {code}.': 'ಇದು {racks} ರ‍್ಯಾಕ್‌ಗಳು ಮತ್ತು {total} ಬಿನ್‌ಗಳನ್ನು ರಚಿಸುತ್ತದೆ. ಮೊದಲ ಬಿನ್ ಹೆಸರು {code}.',
  'Import customers': 'ಗ್ರಾಹಕರನ್ನು ಆಮದು ಮಾಡಿ',
  'That file has no rows. The first line must be the column names.': 'ಆ ಫೈಲ್‌ನಲ್ಲಿ ಸಾಲುಗಳಿಲ್ಲ. ಮೊದಲ ಸಾಲು ಕಾಲಮ್ ಹೆಸರುಗಳಾಗಿರಬೇಕು.',
  'Mechanic mode': 'ಮೆಕ್ಯಾನಿಕ್ ಮೋಡ್',
  'Turn this on if you also service bikes or cars. Turn it off if you only sell parts. You can change it any time, and nothing is deleted.': 'ಬೈಕ್ ಅಥವಾ ಕಾರು ಸರ್ವೀಸ್ ಕೂಡ ಮಾಡಿದರೆ ಇದನ್ನು ಆನ್ ಮಾಡಿ. ಭಾಗಗಳನ್ನು ಮಾತ್ರ ಮಾರಿದರೆ ಆಫ್ ಮಾಡಿ. ಯಾವಾಗ ಬೇಕಾದರೂ ಬದಲಾಯಿಸಬಹುದು, ಏನೂ ಅಳಿಯುವುದಿಲ್ಲ.',
  'This shop also does servicing': 'ಈ ಅಂಗಡಿ ಸರ್ವೀಸ್ ಕೂಡ ಮಾಡುತ್ತದೆ',
  'On: Job cards, labour and services, what the workshop earned, and staff, attendance and payroll appear in the menu.': 'ಆನ್: ಮೆನುವಿನಲ್ಲಿ ಜಾಬ್ ಕಾರ್ಡ್‌ಗಳು, ಕೂಲಿ ಮತ್ತು ಸೇವೆಗಳು, ವರ್ಕ್‌ಶಾಪ್ ಗಳಿಕೆ, ಸಿಬ್ಬಂದಿ, ಹಾಜರಾತಿ, ವೇತನ ಕಾಣಿಸುತ್ತವೆ.',
  'Racks, parts, vehicles, receiving, trade accounts and reports stay either way.': 'ರ‍್ಯಾಕ್‌ಗಳು, ಭಾಗಗಳು, ವಾಹನಗಳು, ಸ್ವೀಕರಣೆ, ಟ್ರೇಡ್ ಖಾತೆಗಳು, ವರದಿಗಳು ಎರಡೂ ಸಂದರ್ಭದಲ್ಲಿ ಇರುತ್ತವೆ.',
  'Only the owner can change mechanic mode.': 'ಮಾಲೀಕರು ಮಾತ್ರ ಮೆಕ್ಯಾನಿಕ್ ಮೋಡ್ ಬದಲಾಯಿಸಬಹುದು.',
  'Mechanic mode is on': 'ಮೆಕ್ಯಾನಿಕ್ ಮೋಡ್ ಆನ್ ಆಗಿದೆ',
  'Mechanic mode is off': 'ಮೆಕ್ಯಾನಿಕ್ ಮೋಡ್ ಆಫ್ ಆಗಿದೆ',
  'Labour and services': 'ಕೂಲಿ ಮತ್ತು ಸೇವೆಗಳು',
  'What you charge for work. On a job card each one is a single tap. Adding a name that is already here changes its charge.': 'ಕೆಲಸಕ್ಕೆ ನೀವು ಪಡೆಯುವುದು. ಜಾಬ್ ಕಾರ್ಡ್‌ನಲ್ಲಿ ಪ್ರತಿಯೊಂದೂ ಒಂದೇ ಟ್ಯಾಪ್‌ನಲ್ಲಿ ಸೇರುತ್ತದೆ. ಇಲ್ಲಿ ಈಗಾಗಲೇ ಇರುವ ಹೆಸರನ್ನು ಮತ್ತೆ ಸೇರಿಸಿದರೆ ಅದರ ಶುಲ್ಕ ಬದಲಾಗುತ್ತದೆ.',
  'GST % (optional)': 'GST % (ಐಚ್ಛಿಕ)',
  'Blank: the shop\'s labour rate': 'ಖಾಲಿ: ಅಂಗಡಿಯ ಕೂಲಿ ದರ',
  'No services yet. Add the work you do most, with its charge.': 'ಇನ್ನೂ ಸೇವೆಗಳಿಲ್ಲ. ಹೆಚ್ಚು ಮಾಡುವ ಕೆಲಸವನ್ನು ಶುಲ್ಕದೊಂದಿಗೆ ಸೇರಿಸಿ.',
  'Shop GST rate': 'ಅಂಗಡಿಯ GST ದರ',
  'GST {n}%': 'GST {n}%',
