  'Enter the charge': 'ಶುಲ್ಕ ನಮೂದಿಸಿ',
  'GST is a number from 0 to 100': 'GST ಎಂದರೆ 0 ರಿಂದ 100 ರ ನಡುವಿನ ಸಂಖ್ಯೆ',
  'Or type a charge': 'ಅಥವಾ ಶುಲ್ಕವನ್ನು ಟೈಪ್ ಮಾಡಿ',
  'Remember this as a service, so next time it is one tap': 'ಇದನ್ನು ಸೇವೆಯಾಗಿ ನೆನಪಿಡಿ, ಮುಂದಿನ ಬಾರಿ ಒಂದೇ ಟ್ಯಾಪ್ ಸಾಕು',
  'Tap a service to add it': 'ಸೇರಿಸಲು ಒಂದು ಸೇವೆಯನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ',
  'What we earned': 'ನಾವು ಗಳಿಸಿದ್ದು',
  'Labour and parts on the bills made from job cards. These bills are also in your sales.': 'ಜಾಬ್ ಕಾರ್ಡ್‌ಗಳಿಂದ ಮಾಡಿದ ಬಿಲ್‌ಗಳಲ್ಲಿ ಕೂಲಿ ಮತ್ತು ಭಾಗಗಳು. ಈ ಬಿಲ್‌ಗಳು ನಿಮ್ಮ ಮಾರಾಟದಲ್ಲಿಯೂ ಸೇರುತ್ತವೆ.',
  'Jobs billed': 'ಬಿಲ್ ಮಾಡಿದ ಕೆಲಸಗಳು',
