  'Tell the customer on WhatsApp': 'ಗ್ರಾಹಕರಿಗೆ WhatsApp ನಲ್ಲಿ ತಿಳಿಸಿ',
  'We have your vehicle': 'ನಿಮ್ಮ ವಾಹನ ನಮಗೆ ಸಿಕ್ಕಿದೆ',
  'Send the estimate': 'ಅಂದಾಜು ಕಳುಹಿಸಿ',
  'It is ready': 'ಸಿದ್ಧವಾಗಿದೆ',
  'This customer has no mobile number.': 'ಈ ಗ್ರಾಹಕರಿಗೆ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಇಲ್ಲ.',
  'WhatsApp opens with the message ready. You press send.': 'ಸಂದೇಶ ಸಿದ್ಧವಾಗಿ WhatsApp ತೆರೆಯುತ್ತದೆ. ನೀವು ಕಳುಹಿಸು ಒತ್ತಿ.',
  'Starts your list with the common makes and models sold in India. It adds only names. No part is marked as fitting any vehicle. Adding it again adds only what is missing.': 'ಭಾರತದಲ್ಲಿ ಮಾರಾಟವಾಗುವ ಸಾಮಾನ್ಯ ಕಂಪನಿಗಳು ಮತ್ತು ಮಾದರಿಗಳೊಂದಿಗೆ ನಿಮ್ಮ ಪಟ್ಟಿ ಆರಂಭವಾಗುತ್ತದೆ. ಹೆಸರುಗಳು ಮಾತ್ರ ಸೇರುತ್ತವೆ. ಯಾವ ಭಾಗವೂ ಯಾವ ವಾಹನಕ್ಕೂ ಹೊಂದುತ್ತದೆ ಎಂದು ಗುರುತಿಸಲಾಗುವುದಿಲ್ಲ. ಮತ್ತೆ ಸೇರಿಸಿದರೆ ಇಲ್ಲದ್ದು ಮಾತ್ರ ಸೇರುತ್ತದೆ.',
  'Nothing was missing.': 'ಯಾವುದೂ ಕಾಣೆಯಾಗಿರಲಿಲ್ಲ.',
  'Added {models} models from {makes} new makes.': '{makes} ಹೊಸ ಕಂಪನಿಗಳ {models} ಮಾದರಿಗಳನ್ನು ಸೇರಿಸಲಾಗಿದೆ.',
  'Name your store or godown': 'ನಿಮ್ಮ ಅಂಗಡಿ ಅಥವಾ ಗೋದಾಮಿನ ಹೆಸರು ನೀಡಿ',
  'Racks from 1 to 40 and bins from 1 to 26 in each rack, as whole numbers': 'ರ‍್ಯಾಕ್‌ಗಳು 1 ರಿಂದ 40, ಪ್ರತಿ ರ‍್ಯಾಕ್‌ನಲ್ಲಿ ಬಿನ್‌ಗಳು 1 ರಿಂದ 26, ಪೂರ್ಣ ಸಂಖ್ಯೆಗಳಲ್ಲಿ',
  '{n} rows': '{n} ಸಾಲುಗಳು',
  'Main store': 'ಮುಖ್ಯ ಅಂಗಡಿ',
  'Bring your customers from Tally, Vyapar, Busy or Excel. Save the file as CSV first. People already here (same phone, or same name when there is no phone) are skipped. What a customer owes is worked out from their unpaid bills, so it is not imported.': 'ನಿಮ್ಮ ಗ್ರಾಹಕರನ್ನು Tally, Vyapar, Busy ಅಥವಾ Excel ನಿಂದ ತನ್ನಿ. ಮೊದಲು ಫೈಲ್ ಅನ್ನು CSV ಆಗಿ ಸೇವ್ ಮಾಡಿ. ಈಗಾಗಲೇ ಇಲ್ಲಿರುವವರನ್ನು (ಅದೇ ಫೋನ್, ಫೋನ್ ಇಲ್ಲದಿದ್ದರೆ ಅದೇ ಹೆಸರು) ಬಿಟ್ಟುಬಿಡಲಾಗುತ್ತದೆ. ಗ್ರಾಹಕರು ಕೊಡಬೇಕಾದದ್ದು ಅವರ ಪಾವತಿಸದ ಬಿಲ್‌ಗಳಿಂದ ಲೆಕ್ಕವಾಗುತ್ತದೆ, ಆದ್ದರಿಂದ ಅದನ್ನು ಆಮದು ಮಾಡುವುದಿಲ್ಲ.',
  'Choose the customer file': 'ಗ್ರಾಹಕರ ಫೈಲ್ ಆರಿಸಿ',
