  'Import the customers': 'ಗ್ರಾಹಕರನ್ನು ಆಮದು ಮಾಡಿ',
  'Choose a CSV file. In Excel, use Save as, CSV.': 'ಒಂದು CSV ಫೈಲ್ ಆರಿಸಿ. Excel ನಲ್ಲಿ Save as, CSV ಬಳಸಿ.',
  'That file is too large': 'ಆ ಫೈಲ್ ತುಂಬಾ ದೊಡ್ಡದು',
